import { Entity, Quat, TranslateGizmo, Vec3 } from 'playcanvas';

import { Events } from '../events';
import { Scene } from '../scene';
import { Splat } from '../splat';
import { Transform } from '../transform';

interface MeasurementPoint {
    worldPosition: Vec3;
    splat: Splat;
    splatIndex: number;
}

class MeasureTransformHandler {
    activate() {}
    deactivate() {}
}

class DistanceMeasurement {
    activate: () => void;
    deactivate: () => void;

    active = false;
    private points: MeasurementPoint[] = [];
    private lineEntity: HTMLElement | null = null;
    private previewLineEntity: HTMLElement | null = null;
    private pointMarkers: HTMLElement[] = [];
    private events: Events;
    private scene: Scene;
    private currentMousePosition: Vec3 = new Vec3(); // Current mouse position (world coordinates)
    private previewUpdateRequested: boolean = false; // Flag for RAF optimization
    private lastMouseX: number = 0; // Last mouse screen X coordinate
    private lastMouseY: number = 0; // Last mouse screen Y coordinate
    
    // Scale-related properties
    private scale: number = 1.0; // Default scale (1 unit = 1 meter)
    private unit: string = 'm'; // Default unit
    private isSetReferenceMode: boolean = false;
    private referenceDistance: number | null = null;

    // Gizmo-based point editing
    private gizmo: TranslateGizmo;
    private pivotEntity: Entity;
    private transformHandler = new MeasureTransformHandler();
    private selectedPointIndex: number = -1;
    private static readonly HIT_THRESHOLD_PX = 12;
    // When picking a new measurement point, search this radius (in depth-RT pixels) and pick the
    // visually-frontmost surface — clicks slightly off a feature snap to the feature instead of
    // grabbing a faint background gaussian.
    private static readonly PICK_RADIUS_PX = 5;

    constructor(events: Events, scene: Scene, canvasContainer: { dom: HTMLElement }) {
        this.events = events;
        this.scene = scene;

        // === Gizmo setup ===
        this.gizmo = new TranslateGizmo(scene.camera.camera, scene.gizmoLayer);
        this.pivotEntity = new Entity('measurementGizmoPivot');

        this.gizmo.on('render:update', () => {
            scene.forceRender = true;
        });

        this.gizmo.on('transform:start', () => {
            events.invoke('pivot').start();
        });

        this.gizmo.on('transform:move', () => {
            events.invoke('pivot').moveTRS(
                this.pivotEntity.getLocalPosition(),
                this.pivotEntity.getLocalRotation(),
                this.pivotEntity.getLocalScale()
            );
        });

        this.gizmo.on('transform:end', () => {
            events.invoke('pivot').end();
        });

        // When gizmo drags, update the selected measurement point's world position
        events.on('pivot.moved', () => {
            if (this.active &&
                this.selectedPointIndex >= 0 &&
                this.selectedPointIndex < this.points.length) {
                const p = events.invoke('pivot').transform.position;
                this.points[this.selectedPointIndex].worldPosition.copy(p);
                if (this.points.length === 2) this.calculateAndDisplayDistance();
                scene.forceRender = true;
            }
        });

        // Per-frame overlay sync (replaces the old setInterval polling)
        events.on('postrender', () => {
            if (this.active) this.updateOverlayPositions();
        });

        const updateGizmoSize = () => {
            const { camera, canvas } = scene;
            this.gizmo.size = camera.ortho
                ? 1125 / canvas.clientHeight
                : 1200 / Math.max(canvas.clientWidth, canvas.clientHeight);
        };
        updateGizmoSize();
        events.on('camera.resize', updateGizmoSize);
        events.on('camera.ortho', updateGizmoSize);

        // === Panel 이벤트 연결 ===
        events.on('measurement.scaleChanged', (value: number) => {
            this.scale = value;
            this.syncScaleToPanel();
            if (this.points.length === 2) this.calculateAndDisplayDistance();
        });

        events.on('measurement.unitChanged', (value: string) => {
            this.unit = value;
            this.syncScaleToPanel();
            if (this.points.length === 2) this.calculateAndDisplayDistance();
        });

        events.on('measurement.setReference', () => {
            this.handleSetReference();
        });

        events.on('measurement.clear', () => {
            this.clearPoints();
        });

        // Click detection: track pointer start position, distinguish click from drag
        let clickStartX = 0;
        let clickStartY = 0;
        let isClick = false;
        const CLICK_THRESHOLD_SQ = 25; // 5px squared

        const isPrimary = (e: PointerEvent) => {
            return e.pointerType === 'mouse' ? e.button === 0 : e.isPrimary;
        };

        const pointerdown = (e: PointerEvent) => {
            if (isPrimary(e)) {
                clickStartX = e.offsetX;
                clickStartY = e.offsetY;
                isClick = true;
            }
        };

        const pointermove = (e: PointerEvent) => {
            if (isClick) {
                const dx = e.offsetX - clickStartX;
                const dy = e.offsetY - clickStartY;
                if (dx * dx + dy * dy > CLICK_THRESHOLD_SQ) {
                    isClick = false;
                }
            }

            // Preview line update when first point is placed
            if (this.points.length === 1) {
                this.lastMouseX = e.clientX;
                this.lastMouseY = e.clientY;
                this.updateMousePosition(e.clientX, e.clientY);
                this.requestPreviewUpdate();
            }
        };

        const pointerup = async (e: PointerEvent) => {
            if (isClick && isPrimary(e)) {
                isClick = false;

                // First, hit-test existing point markers
                const hitIndex = this.hitTestPoint(e.offsetX, e.offsetY);
                if (hitIndex >= 0) {
                    this.selectPoint(hitIndex);
                    e.preventDefault();
                    e.stopPropagation();
                    return;
                }

                // Only add a new point if there is room (no auto-reset on 3rd click)
                if (this.points.length < 2) {
                    const containerDom = canvasContainer.dom;
                    const nx = e.offsetX / containerDom.clientWidth;
                    const ny = e.offsetY / containerDom.clientHeight;

                    const result = await scene.camera.intersect(nx, ny, DistanceMeasurement.PICK_RADIUS_PX);

                    if (result) {
                        this.addPoint(result.splat as Splat, result.position, 0);
                        // Auto-select the freshly placed point so the gizmo appears
                        this.selectPoint(this.points.length - 1);
                    }
                }

                e.preventDefault();
                e.stopPropagation();
            }
            isClick = false;
        };

        this.activate = () => {
            this.active = true;
            this.clearPoints();
            scene.canvas.style.cursor = 'crosshair';
            document.body.classList.add('measurement-active');
            events.fire('measurePanel.setVisible', true);

            canvasContainer.dom.addEventListener('pointerdown', pointerdown);
            canvasContainer.dom.addEventListener('pointermove', pointermove);
            canvasContainer.dom.addEventListener('pointerup', pointerup, true);

            events.fire('transformHandler.push', this.transformHandler);
        };

        this.deactivate = () => {
            this.active = false;
            this.clearPoints();
            scene.canvas.style.cursor = 'default';
            document.body.classList.remove('measurement-active');
            events.fire('measurePanel.setVisible', false);

            canvasContainer.dom.removeEventListener('pointerdown', pointerdown);
            canvasContainer.dom.removeEventListener('pointermove', pointermove);
            canvasContainer.dom.removeEventListener('pointerup', pointerup, true);

            events.fire('transformHandler.pop');
        };
    }

    private addPoint(splat: Splat, worldPosition: Vec3, splatIndex: number) {
        console.log(`🔴 Adding point ${this.points.length + 1}:`, worldPosition, 'from splat:', splat.filename);

        // Refuse extra points once we already have two — caller must Clear first
        if (this.points.length >= 2) {
            console.log('⚠️ Two points already placed. Use Clear to start a new measurement.');
            return;
        }

        this.points.push({
            worldPosition: worldPosition.clone(),
            splat,
            splatIndex
        });

        console.log(`📍 Total points now: ${this.points.length}`);
        console.log(`📍 All points:`, this.points.map(p => p.worldPosition));
        
        this.updateVisuals();
        
        // When the first point is added, also prepare an initial preview line
        if (this.points.length === 1) {
            console.log('🟡 First point added, will show preview line on mouse move');
        }
    }

    private clearPoints() {
        this.points = [];
        this.selectedPointIndex = -1;
        this.gizmo.detach();
        this.removeLineEntity();
        this.removePreviewLine();
        this.removePointMarkers();
        this.events.fire('measurement.distanceUpdated', 'Select two points');
    }

    // Return the index of a point marker within HIT_THRESHOLD_PX of the given canvas-local pixel, or -1
    private hitTestPoint(offsetX: number, offsetY: number): number {
        const screen = new Vec3();
        const canvas = this.scene.canvas;
        const w = canvas.clientWidth;
        const h = canvas.clientHeight;
        const r2 = DistanceMeasurement.HIT_THRESHOLD_PX * DistanceMeasurement.HIT_THRESHOLD_PX;

        for (let i = 0; i < this.points.length; i++) {
            this.scene.camera.worldToScreen(this.points[i].worldPosition, screen);
            const dx = offsetX - screen.x * w;
            const dy = offsetY - screen.y * h;
            if (dx * dx + dy * dy < r2) return i;
        }
        return -1;
    }

    // Select a point and attach the gizmo to it (or detach when index === -1)
    private selectPoint(index: number) {
        this.selectedPointIndex = index;

        if (index >= 0 && index < this.points.length) {
            const pos = this.points[index].worldPosition;
            this.pivotEntity.setLocalPosition(pos);
            const t = new Transform();
            t.set(pos, Quat.IDENTITY, Vec3.ONE);
            this.events.invoke('pivot').place(t);
            this.gizmo.attach(this.pivotEntity);
        } else {
            this.gizmo.detach();
        }

        this.updateMarkerHighlight();
        this.scene.forceRender = true;
    }

    // Re-color markers to indicate which one is selected
    private updateMarkerHighlight() {
        this.pointMarkers.forEach((marker, i) => {
            const selected = i === this.selectedPointIndex;
            const innerPoly = marker.querySelector('svg polygon:nth-of-type(2)') as SVGPolygonElement | null;
            if (innerPoly) {
                innerPoly.setAttribute('fill', selected ? '#ffaa00' : '#ff0000');
            }
        });
    }

        private updateVisuals() {
        console.log('Updating visuals, points count:', this.points.length);
        this.removeLineEntity();
        this.removePreviewLine(); // Also remove preview line
        this.removePointMarkers();
        this.createPointMarkers();
        
        if (this.points.length === 1) {
            console.log('First point selected, waiting for second point');
            this.events.fire('measurement.distanceUpdated', 'Click second point');
            // Prepare preview line when the first point is selected
            // Initialize mouse position near the first point
            this.currentMousePosition.copy(this.points[0].worldPosition);
            this.currentMousePosition.x += 0.1; // Initialize slightly to the side
            
            // Indicate state with cursor change
            this.scene.canvas.style.cursor = 'crosshair';
        } else if (this.points.length === 2) {
            console.log('Two points selected, creating line and calculating distance');
            this.createLine();
            this.calculateAndDisplayDistance();
            
            // Keep measurement tool active
            this.scene.canvas.style.cursor = 'crosshair'; // Keep crosshair cursor
        }
    }

    private createLine() {
        if (this.points.length !== 2) {
            console.log('❌ Cannot create line: need exactly 2 points, have', this.points.length);
            return;
        }

        console.log('🔵 Creating final measurement line using HTML/CSS...');
        console.log('  Point 1:', this.points[0].worldPosition);
        console.log('  Point 2:', this.points[1].worldPosition);

        try {
            // Create the final line using an HTML div
            const lineDiv = document.createElement('div');
            lineDiv.className = 'measurement-final-line';
            lineDiv.style.position = 'absolute';
            lineDiv.style.backgroundColor = 'rgb(255, 0, 0)'; // Strong red
            lineDiv.style.height = '3px'; // Slightly thicker than preview
            lineDiv.style.zIndex = '1000';
            lineDiv.style.pointerEvents = 'none';
            lineDiv.style.transformOrigin = '0 50%';
            lineDiv.style.boxShadow = '0 0 4px rgba(255, 0, 0, 0.5)'; // Glow effect
            
            // Convert both points to screen coordinates
            const point1Screen = new Vec3();
            const point2Screen = new Vec3();
            
            this.scene.camera.worldToScreen(this.points[0].worldPosition, point1Screen);
            this.scene.camera.worldToScreen(this.points[1].worldPosition, point2Screen);
            
            const canvas = this.scene.canvas;
            const rect = canvas.getBoundingClientRect();
            
            // Compute screen coordinates (convert normalized 0-1 to pixel coordinates)
            const x1 = rect.left + point1Screen.x * rect.width;
            const y1 = rect.top + point1Screen.y * rect.height;
            const x2 = rect.left + point2Screen.x * rect.width;
            const y2 = rect.top + point2Screen.y * rect.height;
            
            // Compute line length and angle
            const length = Math.sqrt((x2 - x1) ** 2 + (y2 - y1) ** 2);
            const angle = Math.atan2(y2 - y1, x2 - x1) * 180 / Math.PI;
            
            // Apply line styles
            lineDiv.style.left = `${x1}px`;
            lineDiv.style.top = `${y1}px`;
            lineDiv.style.width = `${length}px`;
            lineDiv.style.transform = `rotate(${angle}deg)`;
            
            document.body.appendChild(lineDiv);

            // Store final line (removed in removeLineEntity);
            // position is kept in sync via updateOverlayPositions() called from postrender
            this.lineEntity = lineDiv as any;

            console.log('✅ Final line created as HTML element');
            console.log(`  Screen coords: (${x1.toFixed(0)}, ${y1.toFixed(0)}) -> (${x2.toFixed(0)}, ${y2.toFixed(0)})`);
            console.log(`  Length: ${length.toFixed(0)}px, Angle: ${angle.toFixed(1)}°`);

        } catch (error) {
            console.error('❌ Error creating measurement line:', error);
            console.log('Line fallback - Distance between points:', this.points[0].worldPosition, 'and', this.points[1].worldPosition);
        }
    }

    private removeLineEntity() {
        if (this.lineEntity) {
            this.lineEntity.remove();
            this.lineEntity = null;
        }
    }

    // True if the world position projects to a valid screen location with the current camera.
    // worldToScreen returns garbage (sign-flipped) for points behind the camera because the
    // perspective divide is by a negative w; we must explicitly cull those.
    private isInFrontOfCamera(worldPos: Vec3): boolean {
        const camEntity = this.scene.camera.mainCamera;
        const camPos = camEntity.getPosition();
        const forward = camEntity.forward;
        return (worldPos.x - camPos.x) * forward.x +
               (worldPos.y - camPos.y) * forward.y +
               (worldPos.z - camPos.z) * forward.z > 0;
    }

    // Shared per-frame update for all HTML overlays (markers + final line).
    // Called from postrender when active — also covers gizmo-drag updates.
    private updateOverlayPositions() {
        if (this.points.length === 0 && !this.lineEntity) return;

        const canvas = this.scene.canvas;
        const rect = canvas.getBoundingClientRect();

        // markers
        const screen = new Vec3();
        for (let i = 0; i < this.points.length; i++) {
            const marker = this.pointMarkers[i];
            if (!marker) continue;
            const worldPos = this.points[i].worldPosition;
            if (!this.isInFrontOfCamera(worldPos)) {
                marker.style.display = 'none';
                continue;
            }
            this.scene.camera.worldToScreen(worldPos, screen);
            const absX = rect.left + screen.x * rect.width;
            const absY = rect.top + screen.y * rect.height;
            marker.style.left = `${absX}px`;
            marker.style.top = `${absY}px`;
            marker.style.display = 'block';
        }

        // final line — hide if either endpoint is behind the camera
        if (this.lineEntity && this.points.length === 2) {
            const p0 = this.points[0].worldPosition;
            const p1 = this.points[1].worldPosition;
            if (!this.isInFrontOfCamera(p0) || !this.isInFrontOfCamera(p1)) {
                this.lineEntity.style.display = 'none';
                return;
            }
            const s0 = new Vec3();
            const s1 = new Vec3();
            this.scene.camera.worldToScreen(p0, s0);
            this.scene.camera.worldToScreen(p1, s1);
            const x1 = rect.left + s0.x * rect.width;
            const y1 = rect.top + s0.y * rect.height;
            const x2 = rect.left + s1.x * rect.width;
            const y2 = rect.top + s1.y * rect.height;
            const len = Math.hypot(x2 - x1, y2 - y1);
            const angle = Math.atan2(y2 - y1, x2 - x1) * 180 / Math.PI;
            this.lineEntity.style.left = `${x1}px`;
            this.lineEntity.style.top = `${y1}px`;
            this.lineEntity.style.width = `${len}px`;
            this.lineEntity.style.transform = `rotate(${angle}deg)`;
            this.lineEntity.style.display = '';
        }
    }

    private removePreviewLine() {
        if (this.previewLineEntity) {
            this.previewLineEntity.remove();
            this.previewLineEntity = null;
        }
    }

    // Convert mouse screen coordinates to world coordinates and store
    private updateMousePosition(screenX: number, screenY: number) {
        try {
            // Compute mouse position only when the first point exists
            if (this.points.length >= 1) {
                const firstPoint = this.points[0].worldPosition;
                
                console.log(`🖱️ Mouse absolute screen: (${screenX}, ${screenY})`);
                
                // Get the screen coordinates of the first point
                const firstPointScreen = new Vec3();
                this.scene.camera.worldToScreen(firstPoint, firstPointScreen);
                
                const canvas = this.scene.canvas;
                const rect = canvas.getBoundingClientRect();
                
                console.log(`📍 First point screen coords: (${firstPointScreen.x.toFixed(1)}, ${firstPointScreen.y.toFixed(1)})`);
                console.log(`📍 Canvas rect: left=${rect.left.toFixed(1)}, top=${rect.top.toFixed(1)}, width=${rect.width.toFixed(1)}, height=${rect.height.toFixed(1)}`);
                
                // Absolute screen coordinates of the first point (convert normalized 0-1 to pixel coordinates)
                const firstPointAbsX = rect.left + firstPointScreen.x * rect.width;
                const firstPointAbsY = rect.top + firstPointScreen.y * rect.height;
                
                console.log(`📍 First point absolute: (${firstPointAbsX.toFixed(1)}, ${firstPointAbsY.toFixed(1)})`);
                
                // Screen distance between the mouse and the first point (pixels)
                const screenDeltaX = screenX - firstPointAbsX;
                const screenDeltaY = screenY - firstPointAbsY;
                
                console.log(`🖱️ Screen delta: (${screenDeltaX.toFixed(1)}, ${screenDeltaY.toFixed(1)})`);
                
                // Simple test: use a fixed distance to verify direction
                const fixedDistance = 1.0; // 1 world unit
                const length = Math.sqrt(screenDeltaX * screenDeltaX + screenDeltaY * screenDeltaY);
                
                if (length > 5) { // Only if moved at least 5 pixels
                    // Use a simpler and more stable method
                    const camera = this.scene.camera;
                    const cameraPos = camera.mainCamera.getPosition();
                    const distanceToFirstPoint = cameraPos.distance(firstPoint);
                    
                    // Revert to accurate FOV-based calculation
                    const canvas = this.scene.canvas;
                    const fov = camera.fov * Math.PI / 180; // Convert to radians
                    
                    // Original formula: convert screen pixels to world units
                    const pixelToWorldAtDistance = (2 * Math.tan(fov / 2) * distanceToFirstPoint) / canvas.height;
                    
                    console.log(`📏 Distance to first point: ${distanceToFirstPoint.toFixed(3)}`);
                    console.log(`📏 FOV: ${camera.fov.toFixed(1)}°`);
                    console.log(`📏 Pixel to world scale: ${pixelToWorldAtDistance.toFixed(6)}`);
                    
                    // Use the same scale for X and Y (accurate FOV-based)
                    const pixelToWorldX = pixelToWorldAtDistance;
                    const pixelToWorldY = pixelToWorldAtDistance;
                    
                    // Compute world offset (per-axis for better accuracy)
                    const worldOffsetX = screenDeltaX * pixelToWorldX;
                    const worldOffsetY = -screenDeltaY * pixelToWorldY; // Y is inverted relative to screen
                    
                    // Set the new mouse world position
                    this.currentMousePosition.copy(firstPoint);
                    this.currentMousePosition.x += worldOffsetX;
                    this.currentMousePosition.y += worldOffsetY;
                    
                    console.log(`🖱️ FOV method - World offset: (${worldOffsetX.toFixed(3)}, ${worldOffsetY.toFixed(3)})`);
                    console.log(`🖱️ Updated mouse world position:`, this.currentMousePosition);
                } else {
                    // If barely moved, position next to the first point
                    this.currentMousePosition.copy(firstPoint);
                    this.currentMousePosition.x += 0.1;
                }
            }
        } catch (error) {
            console.error('❌ Failed to update mouse position:', error);
            // Fallback default — set near the first point
            if (this.points.length >= 1) {
                this.currentMousePosition.copy(this.points[0].worldPosition);
                this.currentMousePosition.x += 0.5; // By default, offset 0.5 units along X
            }
        }
    }



    // Request a preview update via RAF
    private requestPreviewUpdate() {
        if (!this.previewUpdateRequested) {
            this.previewUpdateRequested = true;
            requestAnimationFrame(() => {
                this.updatePreviewLine();
                this.previewUpdateRequested = false;
            });
        }
    }

    // Update preview line (HTML/CSS-based)
    private updatePreviewLine() {
        if (this.points.length !== 1) {
            console.log('❌ Cannot create preview line: need exactly 1 point, have', this.points.length);
            return;
        }

        this.removePreviewLine(); // Remove existing preview line

        console.log('🟡 Creating preview line using HTML/CSS...');
        console.log('  Point 1:', this.points[0].worldPosition);
        console.log('  Mouse pos:', this.currentMousePosition);

        try {
            // Create the line using an HTML div
            const lineDiv = document.createElement('div');
            lineDiv.className = 'measurement-preview-line';
            lineDiv.style.position = 'absolute';
            lineDiv.style.backgroundColor = 'rgba(255, 100, 100, 0.8)'; // Light red
            lineDiv.style.height = '2px';
            lineDiv.style.zIndex = '999';
            lineDiv.style.pointerEvents = 'none';
            lineDiv.style.transformOrigin = '0 50%';
            
            // Convert the first point to screen coordinates
            const point1Screen = new Vec3();
            this.scene.camera.worldToScreen(this.points[0].worldPosition, point1Screen);
            
            const canvas = this.scene.canvas;
            const rect = canvas.getBoundingClientRect();
            
            // Screen coordinates of the first point (convert normalized 0-1 to pixel coordinates)
            const x1 = rect.left + point1Screen.x * rect.width;
            const y1 = rect.top + point1Screen.y * rect.height;
            
            // Use stored mouse position as the second point (actual screen coordinates)
            const x2 = this.lastMouseX || (x1 + 100); // fallback
            const y2 = this.lastMouseY || (y1 + 100); // fallback
            
            // Compute line length and angle
            const length = Math.sqrt((x2 - x1) ** 2 + (y2 - y1) ** 2);
            const angle = Math.atan2(y2 - y1, x2 - x1) * 180 / Math.PI;
            
            // Apply line styles
            lineDiv.style.left = `${x1}px`;
            lineDiv.style.top = `${y1}px`;
            lineDiv.style.width = `${length}px`;
            lineDiv.style.transform = `rotate(${angle}deg)`;
            
            document.body.appendChild(lineDiv);
            
            // Store preview line (removed in removePreviewLine)
            this.previewLineEntity = lineDiv as any;
            
            console.log('✅ Preview line created as HTML element');
            console.log(`  Screen coords: (${x1.toFixed(0)}, ${y1.toFixed(0)}) -> (${x2.toFixed(0)}, ${y2.toFixed(0)})`);
            console.log(`  Length: ${length.toFixed(0)}px, Angle: ${angle.toFixed(1)}°`);
            
            // Accurate distance preview calculation
            if (this.points.length === 1) {
                try {
                    const realWorldDistance = this.points[0].worldPosition.distance(this.currentMousePosition);
                    const scaledDistance = realWorldDistance / this.scale;
                    this.events.fire('measurement.distanceUpdated', `~ ${this.formatDistance(scaledDistance)}`);
                } catch (error) {
                    // fallback
                }
            }
            
        } catch (error) {
            console.error('❌ Error creating preview line:', error);
        }
    }

    private createPointMarkers() {
        this.points.forEach((point, index) => {
            this.createScreenMarker(point.worldPosition, index);
        });
    }
    
    // Create an HTML marker at screen coordinates
    private createScreenMarker(worldPosition: Vec3, index: number) {
        const markerDiv = document.createElement('div');
        markerDiv.className = 'measurement-marker';
        markerDiv.innerHTML = `
            <div class="marker-icon">
                <svg viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">
                    <!-- Outer triangle (white outline) - apex pointing downward -->
                    <polygon points="12,22 2,4 22,4" fill="#ffffff" stroke="#000000" stroke-width="1"/>
                    <!-- Inner triangle (red) -->
                    <polygon points="12,20 4,6 20,6" fill="#ff0000"/>
                    <!-- Center dot (near the apex) -->
                    <circle cx="12" cy="18" r="2" fill="#ffffff"/>
                    <!-- Point number (shown at the top of the triangle) -->
                    <text x="12" y="10" text-anchor="middle" dominant-baseline="central" 
                          font-family="Arial, sans-serif" font-size="8" font-weight="bold" fill="#000000">
                        ${index + 1}
                    </text>
                </svg>
            </div>
        `;
        
        // CSS positioning
        markerDiv.style.position = 'absolute';
        markerDiv.style.left = '0px'; // Initial value 0
        markerDiv.style.top = '0px'; // Initial value 0
        markerDiv.style.transform = 'translate(-50%, -92%)'; // Align the triangle apex to the exact click position
        markerDiv.style.pointerEvents = 'none';
        markerDiv.style.zIndex = '1000';
        markerDiv.style.display = 'none'; // Hidden initially (shown after positioning)
        markerDiv.style.width = '24px';
        markerDiv.style.height = '24px';
        markerDiv.style.filter = 'drop-shadow(2px 2px 4px rgba(0, 0, 0, 0.5))'; // Drop shadow effect
        
        // Append marker to the document
        document.body.appendChild(markerDiv);

        // Store for later removal (HTMLElement instead of Entity).
        // Position is kept in sync via updateOverlayPositions() called from postrender.
        this.pointMarkers.push(markerDiv as any);

        // Compute position immediately and show
        this.updateMarkerPositionImmediate(markerDiv, worldPosition);

        console.log(`✅ Screen marker ${index + 1} created:`, worldPosition);
    }
    
    // Update marker position immediately (when the marker is created)
    private updateMarkerPositionImmediate(markerElement: HTMLElement, worldPosition: Vec3) {
        try {
            const screenPos = new Vec3();
            this.scene.camera.worldToScreen(worldPosition, screenPos);
            
            // Convert to screen coordinates relative to the canvas
            const canvas = this.scene.canvas;
            const rect = canvas.getBoundingClientRect();
            
            // Convert canvas-local coordinates to absolute browser coordinates (convert normalized 0-1 to pixel coordinates)
            const absoluteX = rect.left + screenPos.x * rect.width;
            const absoluteY = rect.top + screenPos.y * rect.height;
            
            // Set position and then show
            markerElement.style.left = `${absoluteX}px`;
            markerElement.style.top = `${absoluteY}px`;
            markerElement.style.display = 'block';
            
            console.log(`✅ Marker positioned immediately: world(${worldPosition.x.toFixed(2)}, ${worldPosition.y.toFixed(2)}, ${worldPosition.z.toFixed(2)}) -> screen(${absoluteX.toFixed(0)}, ${absoluteY.toFixed(0)})`);
            
        } catch (error) {
            console.error('❌ Failed to set marker position immediately:', error);
            // On failure, show near the click position
            markerElement.style.left = '200px';
            markerElement.style.top = '200px';
            markerElement.style.display = 'block';
        }
    }

    private removePointMarkers() {
        this.pointMarkers.forEach((marker) => {
            if (marker) marker.remove();
        });
        this.pointMarkers = [];
    }

    private formatDistance(scaledDistance: number): string {
        switch (this.unit) {
            case 'mm':
                if (scaledDistance < 1) return `${(scaledDistance * 1000).toFixed(2)} μm`;
                if (scaledDistance < 10) return `${scaledDistance.toFixed(3)} mm`;
                return `${scaledDistance.toFixed(1)} mm`;
            case 'cm':
                if (scaledDistance < 0.1) return `${(scaledDistance * 10).toFixed(2)} mm`;
                if (scaledDistance < 100) return `${scaledDistance.toFixed(2)} cm`;
                return `${(scaledDistance / 100).toFixed(2)} m`;
            case 'm':
                if (scaledDistance < 0.01) return `${(scaledDistance * 1000).toFixed(1)} mm`;
                if (scaledDistance < 1) return `${(scaledDistance * 100).toFixed(1)} cm`;
                if (scaledDistance < 1000) return `${scaledDistance.toFixed(3)} m`;
                return `${(scaledDistance / 1000).toFixed(2)} km`;
            case 'km':
                if (scaledDistance < 1) return `${(scaledDistance * 1000).toFixed(0)} m`;
                return `${scaledDistance.toFixed(3)} km`;
            case 'in':
                if (scaledDistance < 1) return `${(scaledDistance * 16).toFixed(2)}/16 in`;
                if (scaledDistance < 12) return `${scaledDistance.toFixed(2)} in`;
                return `${(scaledDistance / 12).toFixed(2)} ft`;
            case 'ft':
                if (scaledDistance < 1) return `${(scaledDistance * 12).toFixed(1)} in`;
                if (scaledDistance < 5280) return `${scaledDistance.toFixed(2)} ft`;
                return `${(scaledDistance / 5280).toFixed(2)} mi`;
            default:
                return `${scaledDistance.toFixed(3)} ${this.unit}`;
        }
    }

    private calculateAndDisplayDistance() {
        if (this.points.length !== 2) return;

        const rawDistance = this.points[0].worldPosition.distance(this.points[1].worldPosition);
        const scaledDistance = rawDistance / this.scale;
        this.events.fire('measurement.distanceUpdated', this.formatDistance(scaledDistance));
    }

    private syncScaleToPanel() {
        this.events.fire('measurement.scaleUpdated', {
            scale: this.scale,
            unit: this.unit,
            info: `Scale: ${this.scale.toFixed(6)} units/${this.unit}`
        });
    }

    // Toggle reference distance mode
    private async handleSetReference() {
        if (this.points.length !== 2) {
            await this.events.invoke('showPopup', {
                type: 'info',
                header: 'Set Reference',
                message: 'Please select two points first.\n\n1. Click the first point on the 3D model\n2. Click the second point\n3. Click Set Reference and enter the real distance'
            });
            return;
        }

        const point1 = this.points[0].worldPosition;
        const point2 = this.points[1].worldPosition;
        const currentDistance = point1.distance(point2);

        const result = await this.events.invoke('showPopup', {
            type: 'input',
            header: 'Set Reference Distance',
            message: `Current measured distance: ${currentDistance.toFixed(3)} units\n\nEnter the known real-world distance between these two points (${this.unit}):`,
            defaultValue: '1.0',
            placeholder: `Distance in ${this.unit}`
        });

        if (!result || result.action !== 'ok') return;

        const realDistanceNum = parseFloat(result.value);
        if (isNaN(realDistanceNum) || realDistanceNum <= 0) {
            await this.events.invoke('showPopup', {
                type: 'error',
                header: 'Invalid Value',
                message: 'Please enter a valid number (greater than 0)'
            });
            return;
        }

        const newScale = currentDistance / realDistanceNum;
        this.scale = newScale;
        this.syncScaleToPanel();
        this.calculateAndDisplayDistance();

        await this.events.invoke('showPopup', {
            type: 'info',
            header: 'Reference Set',
            message: `Real distance: ${realDistanceNum} ${this.unit}\nNew scale: ${newScale.toFixed(6)}`
        });
    }

}

export { DistanceMeasurement };
