/**
 * AboutPopup (New)
 * Pure HTML/CSS replacement for PCUI AboutPopup.
 */

import { version as appVersion } from '../../package.json';
import { createContainer, createLabel } from './dom-helpers';

class NewAboutPopup {
    dom: HTMLDivElement;
    private _hidden = true;

    constructor() {
        // Overlay
        this.dom = createContainer({ id: 'about-popup', class: 'ax-modal-overlay', style: { display: 'none' } });
        this.dom.tabIndex = -1;

        this.dom.addEventListener('keydown', (e: KeyboardEvent) => {
            if (e.key === 'Escape') this.hidden = true;
            e.stopPropagation();
        });

        this.dom.addEventListener('click', () => { this.hidden = true; });

        // Dialog
        const dialog = createContainer({ class: 'ax-modal', parent: this.dom });
        dialog.style.minWidth = '320px';
        dialog.style.maxWidth = '400px';
        dialog.addEventListener('click', e => e.stopPropagation());

        // Header
        const headerEl = createContainer({ class: 'ax-modal__header', parent: dialog });
        createLabel({ text: 'About', parent: headerEl });

        // Body
        const body = createContainer({ class: 'ax-modal__body', parent: dialog });
        body.style.display = 'flex';
        body.style.flexDirection = 'column';
        body.style.alignItems = 'center';
        body.style.gap = '16px';

        // Logo
        const logoEl = createContainer({ parent: body });
        logoEl.innerHTML = '<img src="./static/icons/logo.svg" width="64" height="64" alt="annx ai editor" />';
        logoEl.style.cursor = 'pointer';
        logoEl.addEventListener('click', () => {
            window.open('https://annx.ai', '_blank')?.focus();
        });

        // App info
        const appInfoEl = createContainer({ parent: body });
        appInfoEl.style.textAlign = 'center';
        appInfoEl.style.cursor = 'pointer';
        appInfoEl.addEventListener('click', () => {
            window.open('https://annx.ai', '_blank')?.focus();
        });
        createLabel({ text: 'annx ai editor', parent: appInfoEl, style: { display: 'block', fontSize: '18px', fontWeight: '700', color: 'var(--ax-text-primary)' } });
        createLabel({ text: `v${appVersion}`, parent: appInfoEl, style: { display: 'block', fontSize: '13px', color: 'var(--ax-text-muted)', marginTop: '4px' } });
    }

    get hidden() { return this._hidden; }
    set hidden(v: boolean) {
        this._hidden = v;
        this.dom.style.display = v ? 'none' : '';
        if (!v) this.dom.focus();
    }
}

export { NewAboutPopup };
