/**
 * EditorShell
 * New 3-column layout shell replacing the PCUI-based EditorUI.
 * Provides the same external interface (appContainer, canvas, canvasContainer, toolsContainer)
 * so main.ts and tools can use it without changes.
 */

import { Mat4, path, Vec3 } from 'playcanvas';

import { Events } from '../events';
import { localize } from '../ui/localization';
import { version } from '../../package.json';

import { createContainer, createElement, createLabel, blockPointerEvents } from './dom-helpers';
import { MenuBar } from './menu-bar';
import { LeftToolbar } from './left-toolbar';
import { NewScenePanel } from './scene-panel';
import { TooltipSystem } from './tooltip-system';
import { ViewOptionsPanel } from './view-options-panel';
import { ColorAdjustmentsPanel } from './color-adjustments-panel';
import { FovPanel } from './fov-panel';
import { CameraAlignmentPanel } from './camera-alignment-panel';
import { MeasurementPanel } from './measurement-panel';
import { NewPopup } from './popup';
import { SecondaryToolbar } from './secondary-toolbar';
import { NewSpinner } from './spinner';
import { NewProgress } from './progress';

import { NewShortcutsPopup } from './shortcuts-popup';
import { NewExportPopup } from './export-popup';
import { NewImageSettingsDialog } from './image-settings-dialog';
import { NewVideoSettingsDialog } from './video-settings-dialog';
import { NewAboutPopup } from './about-popup';
import { NewTimelinePanel } from './timeline-panel';
import { NewDataPanel } from './data-panel';
import { NewStatusBar } from './status-bar';
import { NewViewCube } from './view-cube';

// Wrapper that mimics PCUI Container's interface for backward compatibility
// main.ts and tools access .dom and .append() on these
class DomWrapper {
    dom: HTMLElement;

    constructor(el: HTMLElement) {
        this.dom = el;
    }

    append(child: DomWrapper | { dom: HTMLElement } | HTMLElement) {
        if (child instanceof HTMLElement) {
            this.dom.appendChild(child);
        } else if ('dom' in child) {
            this.dom.appendChild(child.dom);
        }
    }

    get hidden() {
        return this.dom.style.display === 'none';
    }

    set hidden(value: boolean) {
        this.dom.style.display = value ? 'none' : '';
    }
}

class EditorUI {
    appContainer: DomWrapper;
    topContainer: DomWrapper;
    canvasContainer: DomWrapper;
    toolsContainer: DomWrapper;
    canvas: HTMLCanvasElement;
    popup: any; // Will be set after popup creation

    // New layout elements (for Phase 2+)
    leftSidebar: HTMLDivElement;
    leftToolbar: HTMLDivElement;
    leftPanel: HTMLDivElement;
    centerArea: HTMLDivElement;
    rightSidebar: HTMLDivElement;
    menuBar: MenuBar;

    constructor(events: Events) {
        // favicon
        const link = document.createElement('link');
        link.rel = 'icon';
        link.href = './static/icons/logo.svg';
        document.head.appendChild(link);

        // ---- Build DOM structure ----

        // Root container
        const appContainerEl = createContainer({ id: 'app-container' });

        // === TOP BARS (full width) ===
        // Menu bar
        const menuBar = new MenuBar(events);
        appContainerEl.appendChild(menuBar.dom);

        // Secondary toolbar (below menu bar)
        const secondaryToolbarSlot = createContainer({ id: 'secondary-toolbar-slot', parent: appContainerEl });

        // === CONTENT AREA (row: toolbar | canvas | right sidebar) ===
        const editorContainer = createContainer({ id: 'editor-container', parent: appContainerEl });

        // Left toolbar (icons only, no panel)
        const leftSidebar = createContainer({ id: 'left-sidebar', parent: editorContainer });
        const leftToolbar = createContainer({ id: 'left-toolbar', parent: leftSidebar });
        const leftPanel = createContainer({ id: 'left-panel', parent: leftSidebar });

        // Center area (canvas + bottom panels)
        const centerArea = createContainer({ id: 'center-area', parent: editorContainer });

        // Canvas container
        const canvasContainerEl = createContainer({ id: 'canvas-container', parent: centerArea });

        // Canvas
        const canvas = document.createElement('canvas');
        canvas.id = 'canvas';
        canvasContainerEl.appendChild(canvas);

        // App label
        const appLabel = createLabel({
            id: 'app-label',
            text: `annx ai editor v${version}`,
            parent: canvasContainerEl
        });

        // Cursor label
        const cursorLabel = createLabel({
            id: 'cursor-label',
            parent: canvasContainerEl
        });

        let fullprecision = '';

        events.on('camera.focalPointPicked', (details: { position: Vec3 }) => {
            cursorLabel.textContent = `${details.position.x.toFixed(2)}, ${details.position.y.toFixed(2)}, ${details.position.z.toFixed(2)}`;
            fullprecision = `${details.position.x}, ${details.position.y}, ${details.position.z}`;
        });

        blockPointerEvents(cursorLabel);

        cursorLabel.addEventListener('pointerdown', () => {
            navigator.clipboard.writeText(fullprecision);
            const orig = cursorLabel.textContent;
            cursorLabel.textContent = localize('cursor.click-to-copy');
            setTimeout(() => {
                cursorLabel.textContent = orig;
            }, 1000);
        });

        // Tools container
        const toolsContainerEl = createContainer({ id: 'tools-container', parent: canvasContainerEl });

        // View cube container
        const viewCubeContainer = createContainer({ id: 'view-cube-container', parent: canvasContainerEl });

        // Mask canvas
        // (created in main.ts, appended to toolsContainer)

        // === RIGHT SIDEBAR ===
        const rightSidebar = createContainer({
            id: 'right-sidebar',
            class: 'hidden',
            parent: editorContainer
        });

        // === OVERLAY CONTAINERS ===
        const tooltipsContainer = createContainer({ id: 'tooltips-container', parent: appContainerEl });
        const topContainer = createContainer({ id: 'top-container', parent: appContainerEl });

        // ---- Create new tooltip system ----
        const newTooltips = new TooltipSystem(tooltipsContainer);

        // ---- Create scene panel floating container ----
        const scenePanelFloat = createContainer({
            id: 'scene-panel-float',
            parent: canvasContainerEl
        });
        scenePanelFloat.style.display = 'none';

        // ---- Create secondary toolbar ----
        const secondaryToolbar = new SecondaryToolbar(events, newTooltips, () => {
            const isVisible = scenePanelFloat.style.display !== 'none';
            scenePanelFloat.style.display = isVisible ? 'none' : '';
        });
        secondaryToolbarSlot.replaceWith(secondaryToolbar.dom);

        // ---- Create new components (Phase 2) ----
        const leftToolbarComponent = new LeftToolbar(events, newTooltips, leftToolbar);
        const scenePanelComponent = new NewScenePanel(events, newTooltips, scenePanelFloat);

        // Hide left panel (no longer used for scene manager)
        leftPanel.style.display = 'none';

        // ---- Create new right sidebar panels (Phase 3) ----
        const viewOptionsPanel = new ViewOptionsPanel(events, newTooltips, rightSidebar);
        const colorAdjustmentsPanel = new ColorAdjustmentsPanel(events, newTooltips, rightSidebar);
        const fovPanel = new FovPanel(events, newTooltips, rightSidebar);
        const cameraAlignmentPanel = new CameraAlignmentPanel(events, newTooltips, rightSidebar);

        // === Distance Measurement Panel (right sidebar) ===
        const measurementPanel = new MeasurementPanel(events, newTooltips, rightSidebar);

        // Show/hide right sidebar based on panel visibility
        const updateRightSidebar = () => {
            const anyVisible = !viewOptionsPanel.hidden || !colorAdjustmentsPanel.hidden || !cameraAlignmentPanel.hidden || !measurementPanel.hidden;
            rightSidebar.classList.toggle('hidden', !anyVisible);
        };

        events.on('viewPanel.visible', updateRightSidebar);
        events.on('colorPanel.visible', updateRightSidebar);
        events.on('cameraAlignmentPanel.visible', updateRightSidebar);
        events.on('measurePanel.visible', updateRightSidebar);

        // Register cursor label tooltip with new system
        newTooltips.register(cursorLabel, localize('cursor.click-to-copy'), 'top');

        // Window resize for letterbox
        window.addEventListener('resize', () => {
            fovPanel.handleResize();
        });

        // ---- New Phase 4 components ----
        // ViewCube
        const viewCube = new NewViewCube(events, viewCubeContainer);
        events.on('prerender', (cameraMatrix: any) => {
            viewCube.update(cameraMatrix);
        });

        // StatusBar
        const statusBar = new NewStatusBar(events, newTooltips);
        centerArea.appendChild(statusBar.dom);

        // Popup
        const popup = new NewPopup();
        topContainer.appendChild(popup.dom);
        this.popup = popup;

        events.function('showPopup', (options: any) => {
            return this.popup.show(options);
        });

        // Spinner
        const spinner = new NewSpinner();
        topContainer.appendChild(spinner.dom);

        let spinnerCount = 0;
        events.on('startSpinner', () => {
            spinnerCount++;
            if (spinnerCount === 1) spinner.hidden = false;
        });
        events.on('stopSpinner', () => {
            spinnerCount = Math.max(0, spinnerCount - 1);
            if (spinnerCount === 0) spinner.hidden = true;
        });

        // Progress
        const progress = new NewProgress();
        topContainer.appendChild(progress.dom);

        events.on('progressStart', (header: string, cancellable?: boolean) => {
            progress.hidden = false;
            progress.setHeader(header);
            progress.setText('');
            progress.setProgress(0);
            progress.showCancelButton(!!cancellable);
            progress.onCancel = cancellable ? () => events.fire('progressCancel') : null;
        });

        events.on('progressUpdate', (options: { text?: string; progress?: number }) => {
            if (options.text !== undefined) progress.setText(options.text);
            if (options.progress !== undefined) progress.setProgress(options.progress);
        });

        events.on('progressEnd', () => {
            progress.hidden = true;
            progress.showCancelButton(false);
            progress.onCancel = null;
        });

        // ---- Store references (before _createLegacyComponents which uses this.menuBar) ----
        this.appContainer = new DomWrapper(appContainerEl);
        this.topContainer = new DomWrapper(topContainer);
        this.canvasContainer = new DomWrapper(canvasContainerEl);
        this.toolsContainer = new DomWrapper(toolsContainerEl);
        this.canvas = canvas;

        this.leftSidebar = leftSidebar;
        this.leftToolbar = leftToolbar;
        this.leftPanel = leftPanel;
        this.centerArea = centerArea;
        this.rightSidebar = rightSidebar;
        this.menuBar = menuBar;

        // ---- Mount remaining legacy PCUI components (complex dialogs) ----
        this._createLegacyComponents(events, canvasContainerEl, centerArea, topContainer, tooltipsContainer, appLabel, cursorLabel, toolsContainerEl, leftSidebar, statusBar, newTooltips, secondaryToolbar.dom, leftToolbarComponent);

        // Mount to document
        document.body.appendChild(appContainerEl);
        document.body.setAttribute('tabIndex', '-1');

        // Initialize canvas size
        const pixelRatio = window.devicePixelRatio;
        canvas.width = Math.ceil(canvasContainerEl.offsetWidth * pixelRatio);
        canvas.height = Math.ceil(canvasContainerEl.offsetHeight * pixelRatio);

        // Prevent context menu and gestures
        ['contextmenu', 'gesturestart', 'gesturechange', 'gestureend'].forEach((event) => {
            document.addEventListener(event, (e) => {
                e.preventDefault();
            }, true);
        });

        // Focus body when clicking canvas
        canvasContainerEl.addEventListener('pointerdown', (event: PointerEvent) => {
            if (event.target === canvas || toolsContainerEl.contains(event.target as Node)) {
                document.body.focus();
            }
        }, true);
    }

    private _createLegacyComponents(
        events: Events,
        canvasContainerEl: HTMLDivElement,
        centerArea: HTMLDivElement,
        topContainer: HTMLDivElement,
        tooltipsContainer: HTMLDivElement,
        appLabel: HTMLElement,
        cursorLabel: HTMLElement,
        toolsContainerEl: HTMLDivElement,
        leftSidebar: HTMLDivElement,
        statusBar: NewStatusBar,
        newTooltips: TooltipSystem,
        secondaryToolbarEl: HTMLElement,
        leftToolbarComponent: LeftToolbar
    ) {
        // Timeline & Data panels
        const timelinePanel = new NewTimelinePanel(events, newTooltips);
        const dataPanel = new NewDataPanel(events);

        timelinePanel.hidden = true;
        dataPanel.hidden = true;

        // Insert before status bar
        centerArea.insertBefore(timelinePanel.dom, statusBar.dom);
        centerArea.insertBefore(dataPanel.dom, statusBar.dom);

        events.on('statusBar.panelChanged', (panel: string | null) => {
            timelinePanel.hidden = panel !== 'timeline';
            dataPanel.hidden = panel !== 'splatData';
        });

        // Subscription-based UI visibility (Flutter)
        const updateUIForSubscription = (isSubscribed: boolean) => {
            if (window.isFlutterApp) {
                const shouldHide = !isSubscribed;
                // 항상 숨김: 메뉴바, 2번째 줄 toolbar, 타임라인
                this.menuBar.dom.style.display = shouldHide ? 'none' : '';
                secondaryToolbarEl.style.display = shouldHide ? 'none' : '';
                if (shouldHide) {
                    timelinePanel.hidden = true;
                }
                // 미구독시에도 보임: left sidebar, status bar, tooltips, cursor label, tools container, app label
                leftSidebar.style.display = '';
                cursorLabel.style.display = '';
                toolsContainerEl.style.display = '';
                statusBar.hidden = false;
                tooltipsContainer.style.display = '';
                appLabel.style.display = '';
                // left toolbar 버튼 활성화/비활성화
                leftToolbarComponent.setSubscriptionState(isSubscribed);
            }
        };

        updateUIForSubscription(window.isSubscribed === true);
        events.on('subscription.statusChanged', (isSubscribed: boolean) => {
            updateUIForSubscription(isSubscribed);
        });

        // Dialogs
        const shortcutsPopup = new NewShortcutsPopup(events);
        const exportPopup = new NewExportPopup(events);
        const imageSettingsDialog = new NewImageSettingsDialog(events);
        const videoSettingsDialog = new NewVideoSettingsDialog(events);
        const aboutPopup = new NewAboutPopup();

        topContainer.appendChild(exportPopup.dom);
        topContainer.appendChild(imageSettingsDialog.dom);
        topContainer.appendChild(videoSettingsDialog.dom);
        topContainer.appendChild(shortcutsPopup.dom);
        topContainer.appendChild(aboutPopup.dom);

        events.on('show.shortcuts', () => { shortcutsPopup.hidden = false; });

        events.function('show.exportPopup', (exportType: any, splatNames: [string], showFilenameEdit: boolean) => {
            return exportPopup.show(exportType, splatNames, showFilenameEdit);
        });

        events.function('show.imageSettingsDialog', async () => {
            const imageSettings = await imageSettingsDialog.show();
            if (imageSettings) {
                await events.invoke('render.image', imageSettings);
            }
        });

        const removeExtension = (filename: string) => {
            return filename.substring(0, filename.length - path.getExtension(filename).length);
        };

        events.function('show.videoSettingsDialog', async () => {
            const videoSettings = await videoSettingsDialog.show();
            if (videoSettings) {
                try {
                    const docName = events.invoke('doc.name');
                    let fileExtension: string;
                    let filePickerTypes: any[];
                    const codecNames: Record<string, string> = { 'h264': 'H.264', 'h265': 'H.265', 'vp9': 'VP9', 'av1': 'AV1' };
                    const codecName = codecNames[videoSettings.codec] || videoSettings.codec.toUpperCase();

                    if (videoSettings.format === 'webm') { fileExtension = '.webm'; filePickerTypes = [{ description: `WebM Video (${codecName})`, accept: { 'video/webm': ['.webm'] } }]; }
                    else if (videoSettings.format === 'mov') { fileExtension = '.mov'; filePickerTypes = [{ description: `MOV Video (${codecName})`, accept: { 'video/quicktime': ['.mov'] } }]; }
                    else if (videoSettings.format === 'mkv') { fileExtension = '.mkv'; filePickerTypes = [{ description: `MKV Video (${codecName})`, accept: { 'video/x-matroska': ['.mkv'] } }]; }
                    else { fileExtension = '.mp4'; filePickerTypes = [{ description: `MP4 Video (${codecName})`, accept: { 'video/mp4': ['.mp4'] } }]; }

                    const suggested = `${removeExtension(docName ?? 'annx-ai-editor')}${fileExtension}`;
                    let writable;
                    let fileHandle: FileSystemFileHandle | undefined;

                    if (window.showSaveFilePicker) {
                        fileHandle = await window.showSaveFilePicker({ id: 'SuperSplatVideoFileExport', types: filePickerTypes, suggestedName: suggested });
                        writable = await fileHandle.createWritable();
                    }

                    const result = await events.invoke('render.video', videoSettings, writable);
                    if (result === false && fileHandle?.remove) { await fileHandle.remove(); }
                } catch (error: any) {
                    if (error instanceof DOMException && error.name === 'AbortError') return;
                    await events.invoke('showPopup', { type: 'error', header: 'Failed to render video', message: `'${error.message ?? error}'` });
                }
            }
        });

        events.on('show.about', () => { aboutPopup.hidden = false; });
    }
}

export { EditorUI };
