/**
 * ImageSettingsDialog (New)
 * Pure HTML/CSS replacement for PCUI ImageSettingsDialog.
 */

import { Events } from '../events';
import { ImageSettings } from '../render';
import { localize } from '../ui/localization';
import { createContainer, createLabel, createButton, createFormRow } from './dom-helpers';
import { BooleanInput, SelectInput, NumericInput } from './input-components';

class NewImageSettingsDialog {
    dom: HTMLDivElement;
    show: () => Promise<ImageSettings | null>;
    hide: () => void;
    private _hidden = true;

    constructor(events: Events) {
        this.dom = createContainer({ id: 'image-settings-dialog', class: 'ax-modal-overlay', style: { display: 'none' } });
        this.dom.tabIndex = -1;

        const dialog = createContainer({ class: 'ax-modal', parent: this.dom });
        dialog.style.minWidth = '400px';
        dialog.addEventListener('click', e => e.stopPropagation());

        // Header
        const headerEl = createContainer({ class: 'ax-modal__header', parent: dialog });
        createLabel({ text: localize('popup.render-image.header').toUpperCase(), parent: headerEl });

        // Body
        const body = createContainer({ class: 'ax-modal__body', parent: dialog });
        body.style.display = 'flex';
        body.style.flexDirection = 'column';
        body.style.gap = '8px';

        // Preset
        const { row: presetRow, value: presetVal } = createFormRow({ label: localize('popup.render-image.preset'), parent: body });
        const presetSelect = new SelectInput({
            value: 'viewport',
            options: [
                { value: 'viewport', label: localize('popup.render-image.resolution-current') },
                { value: 'HD', label: 'HD' },
                { value: 'QHD', label: 'QHD' },
                { value: '4K', label: '4K' },
                { value: 'custom', label: localize('popup.render-image.resolution-custom') }
            ],
            parent: presetVal
        });

        // Resolution
        const { row: resRow, value: resVal } = createFormRow({ label: localize('popup.render-image.resolution'), parent: body });
        const resW = new NumericInput({ value: 1024, min: 4, max: 16000, precision: 0, parent: resVal });
        resW.dom.style.width = '80px';
        createLabel({ text: '×', parent: resVal, style: { padding: '0 4px' } });
        const resH = new NumericInput({ value: 768, min: 4, max: 16000, precision: 0, parent: resVal });
        resH.dom.style.width = '80px';
        resW.enabled = false;
        resH.enabled = false;

        // Transparent BG
        const { value: tbVal } = createFormRow({ label: localize('popup.render-image.transparent-bg'), parent: body });
        const transparentBg = new BooleanInput({ type: 'toggle', value: false, parent: tbVal });

        // Show Debug
        const { value: dbVal } = createFormRow({ label: localize('popup.render-image.show-debug'), parent: body });
        const showDebug = new BooleanInput({ type: 'toggle', value: false, parent: dbVal });

        // Footer
        const footer = createContainer({ class: 'ax-modal__footer', parent: dialog });
        const cancelBtn = createButton({ text: localize('panel.render.cancel'), parent: footer });
        const okBtn = createButton({ text: localize('panel.render.ok'), variant: 'primary', parent: footer });

        // Logic
        let targetSize = { width: 1024, height: 768 };

        const updateResolution = () => {
            const w: Record<string, number> = { viewport: targetSize.width, HD: 1920, QHD: 2560, '4K': 3840 };
            const h: Record<string, number> = { viewport: targetSize.height, HD: 1080, QHD: 1440, '4K': 2160 };
            const p = presetSelect.value;
            if (w[p] !== undefined) { resW.value = w[p]; resH.value = h[p]; }
        };

        presetSelect.dom.addEventListener('change', () => {
            const isCustom = presetSelect.value === 'custom';
            resW.enabled = isCustom;
            resH.enabled = isCustom;
            if (!isCustom) updateResolution();
        });

        let onCancel: () => void;
        let onOK: () => void;

        cancelBtn.addEventListener('click', () => onCancel());
        okBtn.addEventListener('click', () => onOK());

        const keydown = (e: KeyboardEvent) => {
            if (e.key === 'Escape') { e.preventDefault(); e.stopPropagation(); onCancel(); }
        };

        this.show = () => {
            targetSize = events.invoke('targetSize');
            updateResolution();
            this.dom.style.display = '';
            this._hidden = false;
            document.addEventListener('keydown', keydown);
            this.dom.focus();

            return new Promise<ImageSettings | null>((resolve) => {
                onCancel = () => resolve(null);
                onOK = () => resolve({ width: resW.value, height: resH.value, transparentBg: transparentBg.value, showDebug: showDebug.value });
            }).finally(() => {
                document.removeEventListener('keydown', keydown);
                this.hide();
            });
        };

        this.hide = () => { this.dom.style.display = 'none'; this._hidden = true; };
    }

    get hidden() { return this._hidden; }
    set hidden(v: boolean) { this._hidden = v; this.dom.style.display = v ? 'none' : ''; }
}

export { NewImageSettingsDialog };
