/**
 * TimelinePanel (New)
 * Pure HTML/CSS replacement for PCUI TimelinePanel.
 */

import { Events } from '../events';
import { ShortcutManager } from '../shortcut-manager';
import { localize } from '../ui/localization';
import { createContainer, createButton, createToolButton, createLabel } from './dom-helpers';
import { NumericInput, SelectInput } from './input-components';
import { TooltipSystem } from './tooltip-system';

// SVG icons for timeline buttons
const iconPrev = `<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polygon points="19 20 9 12 19 4 19 20"/><line x1="5" y1="19" x2="5" y2="5"/></svg>`;
const iconPlay = `<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polygon points="6 3 20 12 6 21 6 3"/></svg>`;
const iconPause = `<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="14" y="4" width="4" height="16" rx="1"/><rect x="6" y="4" width="4" height="16" rx="1"/></svg>`;
const iconNext = `<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polygon points="5 4 15 12 5 20 5 4"/><line x1="19" y1="5" x2="19" y2="19"/></svg>`;
const iconAddKey = `<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 5v14"/><path d="M5 12h14"/></svg>`;
const iconRemoveKey = `<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12h14"/></svg>`;

// ============================================
// Ticks (timeline ruler with keys & cursor)
// ============================================
class Ticks {
    dom: HTMLDivElement;

    constructor(events: Events) {
        this.dom = createContainer({ id: 'ticks' });
        const workArea = createContainer({ id: 'ticks-area', parent: this.dom });

        let frameFromOffset: (offset: number) => number;
        let moveCursor: (frame: number) => void;

        const rebuild = () => {
            workArea.innerHTML = '';

            const numFrames = events.invoke('timeline.frames');
            const currentFrame = events.invoke('timeline.frame');

            const padding = 20;
            const width = this.dom.getBoundingClientRect().width - padding * 2;
            const labelStep = Math.max(1, Math.floor(numFrames / Math.max(1, Math.floor(width / 50))));
            const numLabels = Math.max(1, Math.ceil(numFrames / labelStep));

            const offsetFromFrame = (frame: number) => padding + Math.floor(frame / (numFrames - 1) * width);

            frameFromOffset = (offset: number) => Math.max(0, Math.min(numFrames - 1, Math.floor((offset - padding) / width * (numFrames - 1))));

            for (let i = 0; i < numLabels; i++) {
                const thisFrame = Math.floor(i * labelStep);
                const label = document.createElement('div');
                label.classList.add('time-label');
                label.style.left = `${offsetFromFrame(thisFrame)}px`;
                label.textContent = thisFrame.toString();
                workArea.appendChild(label);
            }

            const keys = events.invoke('track.keys') as number[] ?? [];

            keys.forEach((keyFrame: number) => {
                const label = document.createElement('div');
                label.classList.add('time-label', 'key');
                label.style.left = `${offsetFromFrame(keyFrame)}px`;
                label.dataset.frame = keyFrame.toString();
                let dragging = false;
                let copying = false;
                let clone: HTMLElement | null = null;
                let toFrame = -1;

                label.addEventListener('pointerdown', (event) => {
                    if (!dragging && event.isPrimary) {
                        dragging = true;
                        copying = event.shiftKey;
                        label.setPointerCapture(event.pointerId);
                        event.stopPropagation();
                        if (copying) {
                            clone = document.createElement('div');
                            clone.classList.add('time-label', 'key', 'dragging');
                            clone.style.left = label.style.left;
                            workArea.appendChild(clone);
                            label.classList.add('copying');
                        } else {
                            label.classList.add('dragging');
                        }
                    }
                });

                label.addEventListener('pointermove', (event: PointerEvent) => {
                    if (dragging) {
                        toFrame = frameFromOffset(parseInt(label.style.left, 10) + event.offsetX);
                        if (copying && clone) {
                            clone.style.left = `${offsetFromFrame(toFrame)}px`;
                        } else {
                            label.style.left = `${offsetFromFrame(toFrame)}px`;
                        }
                    }
                });

                label.addEventListener('pointerup', (event: PointerEvent) => {
                    if (dragging && event.isPrimary) {
                        const fromFrame = parseInt(label.dataset.frame!, 10);
                        if (copying && clone) {
                            workArea.removeChild(clone);
                            clone = null;
                            label.classList.remove('copying');
                        } else {
                            label.classList.remove('dragging');
                        }
                        label.releasePointerCapture(event.pointerId);
                        if (fromFrame !== toFrame && toFrame >= 0) {
                            if (copying) {
                                events.fire('track.copyKey', fromFrame, toFrame);
                            } else {
                                events.fire('track.moveKey', fromFrame, toFrame);
                            }
                        }
                        copying = false;
                        dragging = false;
                    }
                });

                workArea.appendChild(label);
            });

            const cursor = document.createElement('div');
            cursor.classList.add('time-label', 'cursor');
            cursor.style.left = `${offsetFromFrame(currentFrame)}px`;
            cursor.textContent = currentFrame.toString();
            workArea.appendChild(cursor);

            moveCursor = (frame: number) => {
                cursor.style.left = `${offsetFromFrame(frame)}px`;
                cursor.textContent = frame.toString();
            };
        };

        // Scrubbing
        let scrubbing = false;
        workArea.addEventListener('pointerdown', (event: PointerEvent) => {
            if (!scrubbing && event.isPrimary) {
                scrubbing = true;
                workArea.setPointerCapture(event.pointerId);
                events.fire('timeline.setFrame', frameFromOffset(event.offsetX));
            }
        });
        workArea.addEventListener('pointermove', (event: PointerEvent) => {
            if (scrubbing) events.fire('timeline.setFrame', frameFromOffset(event.offsetX));
        });
        workArea.addEventListener('pointerup', (event: PointerEvent) => {
            if (scrubbing && event.isPrimary) {
                workArea.releasePointerCapture(event.pointerId);
                scrubbing = false;
            }
        });

        new ResizeObserver(() => rebuild()).observe(workArea);

        events.on('timeline.frames', () => rebuild());
        events.on('timeline.frame', (frame: number) => moveCursor(frame));
        events.on('track.keyAdded', () => rebuild());
        events.on('track.keyRemoved', () => rebuild());
        events.on('track.keyMoved', () => rebuild());
        events.on('track.keyUpdated', () => rebuild());
        events.on('track.keysLoaded', () => rebuild());
        events.on('track.keysCleared', () => rebuild());
    }
}

// ============================================
// TimelinePanel
// ============================================
class NewTimelinePanel {
    dom: HTMLDivElement;
    private _hidden = true;

    constructor(events: Events, tooltips: TooltipSystem) {
        this.dom = createContainer({ id: 'timeline-panel' });
        this.dom.style.display = 'none';

        // === Play controls ===
        const prev = createToolButton({ icon: iconPrev });
        const play = createToolButton({ icon: iconPlay });
        const next = createToolButton({ icon: iconNext });
        const addKey = createToolButton({ icon: iconAddKey });
        const removeKey = createToolButton({ icon: iconRemoveKey });
        removeKey.disabled = true;

        const buttonControls = createContainer({ id: 'button-controls' });
        buttonControls.appendChild(prev);
        buttonControls.appendChild(play);
        buttonControls.appendChild(next);
        buttonControls.appendChild(addKey);
        buttonControls.appendChild(removeKey);

        // === Settings ===
        const speed = new SelectInput({
            value: '30',
            options: [
                { value: '1', label: '1 fps' },
                { value: '6', label: '6 fps' },
                { value: '12', label: '12 fps' },
                { value: '24', label: '24 fps' },
                { value: '30', label: '30 fps' },
                { value: '60', label: '60 fps' }
            ],
            onChange: (v) => events.fire('timeline.setFrameRate', parseInt(v, 10))
        });
        speed.dom.id = 'speed';

        events.on('timeline.frameRate', (frameRate: number) => {
            speed.value = frameRate.toString();
        });

        const frames = new NumericInput({
            value: 180,
            min: 1,
            max: 10000,
            precision: 0
        });
        frames.dom.id = 'totalFrames';
        frames.dom.addEventListener('change', () => {
            events.fire('timeline.setFrames', frames.value);
        });

        events.on('timeline.frames', (framesIn: number) => {
            frames.value = framesIn;
        });

        const smoothness = new NumericInput({
            value: 1,
            min: 0,
            max: 1,
            step: 0.05,
            precision: 2
        });
        smoothness.dom.id = 'smoothness';
        smoothness.dom.addEventListener('change', () => {
            events.fire('timeline.setSmoothness', smoothness.value);
        });

        events.on('timeline.smoothness', (v: number) => {
            smoothness.value = v;
        });

        const settingsControls = createContainer({ id: 'settings-controls' });
        settingsControls.appendChild(speed.dom);
        settingsControls.appendChild(frames.dom);
        settingsControls.appendChild(smoothness.dom);

        // === Layout ===
        const controlsWrap = createContainer({ id: 'controls-wrap' });
        const spacerL = createContainer({ class: 'spacer' });
        const spacerR = createContainer({ class: 'spacer' });
        spacerR.appendChild(settingsControls);

        controlsWrap.appendChild(spacerL);
        controlsWrap.appendChild(buttonControls);
        controlsWrap.appendChild(spacerR);

        const ticks = new Ticks(events);

        this.dom.appendChild(controlsWrap);
        this.dom.appendChild(ticks.dom);

        // === Event handlers ===
        prev.addEventListener('click', (evt: MouseEvent) => {
            events.fire(evt.shiftKey ? 'timeline.prevKey' : 'timeline.prevFrame');
        });
        next.addEventListener('click', (evt: MouseEvent) => {
            events.fire(evt.shiftKey ? 'timeline.nextKey' : 'timeline.nextFrame');
        });
        play.addEventListener('click', () => {
            events.fire('timeline.setPlaying', !events.invoke('timeline.playing'));
        });

        events.on('timeline.playing', (isPlaying: boolean) => {
            play.innerHTML = isPlaying ? iconPause : iconPlay;
        });

        addKey.addEventListener('click', () => events.fire('track.addKey'));
        removeKey.addEventListener('click', () => {
            events.fire('track.removeKey', events.invoke('timeline.frame'));
        });

        const updateKeyButtonStates = () => {
            const keys = events.invoke('track.keys') as number[] ?? [];
            const frame = events.invoke('timeline.frame');
            removeKey.disabled = !keys.includes(frame);
        };

        events.on('timeline.frame', updateKeyButtonStates);
        events.on('track.keyAdded', updateKeyButtonStates);
        events.on('track.keyRemoved', updateKeyButtonStates);
        events.on('track.keyMoved', updateKeyButtonStates);
        events.on('track.keyUpdated', updateKeyButtonStates);
        events.on('track.keysLoaded', updateKeyButtonStates);
        events.on('track.keysCleared', updateKeyButtonStates);

        // === Tooltips ===
        const shortcutManager: ShortcutManager = events.invoke('shortcutManager');
        const tip = (key: string, sid?: string) => {
            const t = localize(key);
            if (sid) { const s = shortcutManager.formatShortcut(sid); if (s) return `${t} ( ${s} )`; }
            return t;
        };

        tooltips.register(prev, tip('tooltip.timeline.prev-frame', 'timeline.prevFrame'), 'top');
        tooltips.register(play, tip('tooltip.timeline.play', 'timeline.togglePlay'), 'top');
        tooltips.register(next, tip('tooltip.timeline.next-frame', 'timeline.nextFrame'), 'top');
        tooltips.register(addKey, tip('tooltip.timeline.add-key', 'track.addKey'), 'top');
        tooltips.register(removeKey, tip('tooltip.timeline.remove-key', 'track.removeKey'), 'top');
        tooltips.register(speed.dom, localize('tooltip.timeline.frame-rate'), 'top');
        tooltips.register(frames.dom, localize('tooltip.timeline.total-frames'), 'top');
        tooltips.register(smoothness.dom, localize('tooltip.timeline.smoothness'), 'top');
    }

    get hidden() { return this._hidden; }
    set hidden(v: boolean) {
        this._hidden = v;
        this.dom.style.display = v ? 'none' : '';
    }
}

export { NewTimelinePanel };
