/**
 * EnhancedSpinner (New)
 * Pure HTML/CSS replacement - progress spinner with status text.
 */

import { Events } from '../events';
import { createContainer, createLabel } from './dom-helpers';

class EnhancedSpinner {
    dom: HTMLDivElement;
    private _statusEl: HTMLSpanElement;
    private _progressTrack: HTMLDivElement;
    private _progressBar: HTMLDivElement;
    private _isDownloading = false;
    private _hidden = true;

    constructor(events: Events) {
        this.dom = createContainer({ id: 'enhanced-spinner-container' });
        this.dom.style.display = 'none';
        this.dom.tabIndex = 0;

        const center = createContainer({ class: 'enhanced-spinner-center-container', parent: this.dom });

        const spinner = document.createElement('div');
        spinner.className = 'enhanced-spinner-animation';
        center.appendChild(spinner);

        this._statusEl = createLabel({ text: '로딩 중...', class: 'enhanced-spinner-status', parent: center });

        this._progressTrack = createContainer({ class: 'enhanced-spinner-progress-track', parent: center });
        this._progressTrack.style.display = 'none';

        this._progressBar = createContainer({ class: 'enhanced-spinner-progress-bar', parent: this._progressTrack });

        this.dom.addEventListener('keydown', (e) => {
            if (this._hidden) return;
            e.stopPropagation();
            e.preventDefault();
        });

        this._registerEvents(events);
    }

    private _setProgress(progress: number) {
        this._progressBar.style.width = `${Math.round(Math.max(0, Math.min(1, progress)) * 100)}%`;
    }

    private _registerEvents(events: Events) {
        events.on('s3.downloadStart', (filename: string) => {
            this.hidden = false;
            this._isDownloading = true;
            this._statusEl.textContent = `파일 다운로드 중: ${filename}`;
            this._progressTrack.style.display = '';
            this._setProgress(0);
        });

        events.on('s3.downloadProgress', (progress: number) => {
            if (this._isDownloading) {
                this._setProgress(progress);
                this._statusEl.textContent = `다운로드 중... ${Math.round(progress * 100)}%`;
            }
        });

        events.on('s3.downloadComplete', () => {
            this._statusEl.textContent = '다운로드 완료, 모델 처리 중...';
            this._setProgress(1);
        });

        events.on('s3.modelProcessing', (message: string) => {
            this._statusEl.textContent = message || '모델 처리 중...';
        });

        events.on('s3.processingComplete', () => {
            this._statusEl.textContent = '로드 완료';
            this._setProgress(1);
            setTimeout(() => { this.hidden = true; this._resetState(); }, 500);
        });

        events.on('s3.error', (errorMessage: string) => {
            this._statusEl.textContent = `오류: ${errorMessage}`;
            this._progressTrack.style.display = 'none';
            setTimeout(() => { this.hidden = true; this._resetState(); }, 3000);
        });
    }

    private _resetState() {
        this._isDownloading = false;
        this._statusEl.textContent = '로딩 중...';
        this._progressTrack.style.display = 'none';
        this._setProgress(0);
    }

    get hidden() { return this._hidden; }
    set hidden(v: boolean) {
        this._hidden = v;
        this.dom.style.display = v ? 'none' : 'flex';
    }
}

export { EnhancedSpinner };
