/**
 * CameraAlignmentPanel
 * Right sidebar panel for COLMAP camera display options.
 */

import { Events } from '../events';
import { createPanel, createFormRow, createContainer, createLabel, blockPointerEvents } from './dom-helpers';
import { SelectInput, SliderInput } from './input-components';
import { TooltipSystem } from './tooltip-system';

class CameraAlignmentPanel {
    dom: HTMLDivElement;
    private _hidden = true;

    constructor(events: Events, tooltips: TooltipSystem, parent: HTMLElement) {
        const { panel, body } = createPanel({
            title: 'Camera Alignment',
            collapsible: false,
            parent
        });

        this.dom = panel;
        this.dom.id = 'camera-alignment-panel';
        blockPointerEvents(this.dom);

        let thumbnailsLoaded = false;
        let currentMode = 'frustum';

        // === Display Mode ===
        const { value: modeValue } = createFormRow({ label: 'Display', parent: body });
        const modeSelect = new SelectInput({
            options: [
                { value: 'frustum', label: 'Camera Position' },
                { value: 'thumbnail', label: 'Camera Thumbnail' }
            ],
            value: 'frustum',
            parent: modeValue,
            onChange: async (value: string) => {
                if (value === currentMode) return;

                if (value === 'thumbnail') {
                    // 썸네일이 아직 로드되지 않았으면 로드
                    if (!thumbnailsLoaded) {
                        if (window.isFlutterApp && window.flutter_inappwebview) {
                            events.fire('showPopup', {
                                type: 'info',
                                header: 'Camera Thumbnail',
                                message: 'Loading camera thumbnails. This may take a while for the first time...'
                            });
                            await events.invoke('colmapCamera.loadThumbnails');
                            thumbnailsLoaded = true;
                        }
                    }
                    events.invoke('colmapCamera.setDisplayMode', 'thumbnail');
                    thumbnailOptions.style.display = '';
                } else {
                    events.invoke('colmapCamera.setDisplayMode', 'frustum');
                    thumbnailOptions.style.display = 'none';
                }
                currentMode = value;
            }
        });

        // === Camera Size ===
        const { value: sizeValue } = createFormRow({ label: 'Size', parent: body });
        const sizeSlider = new SliderInput({
            min: 0.1,
            max: 3.0,
            step: 0.1,
            value: 1.0,
            precision: 1,
            onChange: (value: number) => {
                events.invoke('colmapCamera.setScale', value);
            }
        });
        sizeValue.appendChild(sizeSlider.dom);

        // === Thumbnail Options (initially hidden) ===
        const thumbnailOptions = createContainer({ parent: body });
        thumbnailOptions.style.display = 'none';

        // 클릭 동작 선택
        const { value: clickValue } = createFormRow({ label: 'On Click', parent: thumbnailOptions });
        const clickSelect = new SelectInput({
            options: [
                { value: 'move', label: 'Move to Camera' },
                { value: 'preview', label: 'Show Original Image' }
            ],
            value: 'move',
            parent: clickValue,
            onChange: (value: string) => {
                events.fire('colmapCamera.clickMode', value);
            }
        });

        // 초기 상태: 숨김
        this.hidden = true;

        // === 원본 이미지 팝업 ===
        const imageOverlay = createContainer({
            id: 'colmap-image-overlay',
            style: {
                display: 'none',
                position: 'fixed',
                top: '0', left: '0', right: '0', bottom: '0',
                backgroundColor: 'rgba(0,0,0,0.8)',
                zIndex: '10000',
                justifyContent: 'center',
                alignItems: 'center',
                cursor: 'pointer'
            }
        });

        const imageTitle = createLabel({
            style: {
                position: 'absolute',
                top: '16px', left: '0', right: '0',
                textAlign: 'center',
                color: 'white',
                fontSize: '14px'
            },
            parent: imageOverlay
        });

        const imageEl = document.createElement('img');
        imageEl.style.maxWidth = '90%';
        imageEl.style.maxHeight = '85%';
        imageEl.style.objectFit = 'contain';
        imageOverlay.appendChild(imageEl);

        imageOverlay.addEventListener('click', () => {
            imageOverlay.style.display = 'none';
        });

        document.body.appendChild(imageOverlay);

        events.on('colmapCamera.showImagePopup', (data: { imageName: string, imageUrl: string }) => {
            imageEl.src = data.imageUrl;
            imageTitle.textContent = data.imageName;
            imageOverlay.style.display = 'flex';
        });

        // 패널 toggle 이벤트
        events.on('cameraAlignmentPanel.toggleVisible', () => {
            this.hidden = !this._hidden;
            events.fire('cameraAlignmentPanel.visible', !this._hidden);
        });

        events.on('cameraAlignmentPanel.setVisible', (visible: boolean) => {
            this.hidden = !visible;
            events.fire('cameraAlignmentPanel.visible', visible);
        });
    }

    get hidden() {
        return this._hidden;
    }

    set hidden(value: boolean) {
        this._hidden = value;
        this.dom.style.display = value ? 'none' : '';
    }
}

export { CameraAlignmentPanel };
