/**
 * StatusBar (New)
 * Pure HTML/CSS replacement for PCUI StatusBar.
 */

import { Events } from '../events';
import { ShortcutManager } from '../shortcut-manager';
import { Splat } from '../splat';
import { localize, formatInteger } from '../ui/localization';
import { createContainer, createElement, createLabel, createButton } from './dom-helpers';
import { TooltipSystem } from './tooltip-system';

class NewStatusBar {
    dom: HTMLDivElement;

    constructor(events: Events, tooltips: TooltipSystem) {
        this.dom = createContainer({ id: 'status-bar' });

        let activePanel = '';

        // Toggle buttons
        const timelineBtn = createButton({
            text: localize('status-bar.timeline').toUpperCase(),
            variant: 'ghost',
            parent: this.dom,
            style: { fontSize: 'var(--ax-font-size-xs)', padding: '2px 8px', height: '20px' }
        });

        // Flutter 환경에서는 TIMELINE 버튼 숨김
        if (window.isFlutterApp) {
            timelineBtn.style.display = 'none';
        }

        const splatDataBtn = createButton({
            text: localize('status-bar.splat-data').toUpperCase(),
            variant: 'ghost',
            parent: this.dom,
            style: { fontSize: 'var(--ax-font-size-xs)', padding: '2px 8px', height: '20px' }
        });

        // Spacer
        createContainer({ parent: this.dom, style: { flex: '1' } });

        // Stats
        const statsContainer = createContainer({
            parent: this.dom,
            style: { display: 'flex', gap: '16px', alignItems: 'center' }
        });

        const createStat = (labelText: string): HTMLSpanElement => {
            const container = createContainer({
                parent: statsContainer,
                style: { display: 'flex', gap: '4px', alignItems: 'center' }
            });
            createLabel({
                text: labelText,
                parent: container,
                style: { color: 'var(--ax-text-muted)', fontSize: 'var(--ax-font-size-xs)' }
            });
            return createLabel({
                text: '0',
                parent: container,
                style: { fontSize: 'var(--ax-font-size-xs)', fontFamily: 'var(--ax-font-mono)' }
            });
        };

        const splatsValue = createStat(localize('status-bar.splats'));
        const selectedValue = createStat(localize('status-bar.selected'));
        const lockedValue = createStat(localize('status-bar.locked'));
        const deletedValue = createStat(localize('status-bar.deleted'));

        // Panel toggle logic
        const setActivePanel = (panel: string) => {
            activePanel = panel;
            timelineBtn.classList.toggle('active', panel === 'timeline');
            splatDataBtn.classList.toggle('active', panel === 'splatData');
            events.fire('statusBar.panelChanged', panel || null);
        };

        timelineBtn.addEventListener('click', () => {
            setActivePanel(activePanel === 'timeline' ? '' : 'timeline');
        });

        splatDataBtn.addEventListener('click', () => {
            if (splatDataBtn.disabled) return;
            setActivePanel(activePanel === 'splatData' ? '' : 'splatData');
        });

        // Tooltips
        const shortcutManager: ShortcutManager = events.invoke('shortcutManager');
        const tip = (key: string, shortcutId?: string) => {
            const text = localize(key);
            if (shortcutId) {
                const s = shortcutManager.formatShortcut(shortcutId);
                if (s) return `${text} ( ${s} )`;
            }
            return text;
        };

        tooltips.register(timelineBtn, tip('tooltip.status-bar.timeline', 'timelinePanel.toggle'), 'top');
        tooltips.register(splatDataBtn, tip('tooltip.status-bar.splat-data', 'dataPanel.toggle'), 'top');

        // Subscription-based disable for SPLAT DATA
        const updateSplatDataSubscription = (isSubscribed: boolean) => {
            splatDataBtn.disabled = !isSubscribed;
            splatDataBtn.style.opacity = isSubscribed ? '' : '0.4';
            splatDataBtn.style.cursor = isSubscribed ? '' : 'default';
            // Pro 배지 토글
            const existing = splatDataBtn.querySelector('.pro-badge');
            if (!isSubscribed && !existing) {
                const badge = document.createElement('span');
                badge.className = 'pro-badge';
                badge.textContent = 'Pro';
                splatDataBtn.style.position = 'relative';
                splatDataBtn.appendChild(badge);
            } else if (isSubscribed && existing) {
                existing.remove();
            }
            if (!isSubscribed && activePanel === 'splatData') {
                setActivePanel('');
            }
        };

        if (window.isFlutterApp) {
            updateSplatDataSubscription(window.isSubscribed === true);
            events.on('subscription.statusChanged', (isSubscribed: boolean) => {
                updateSplatDataSubscription(isSubscribed);
            });
        }

        // Keyboard shortcuts
        events.on('dataPanel.toggle', () => {
            if (splatDataBtn.disabled) return;
            setActivePanel(activePanel === 'splatData' ? '' : 'splatData');
        });
        events.on('timelinePanel.toggle', () => {
            setActivePanel(activePanel === 'timeline' ? '' : 'timeline');
        });

        // Stats
        let splat: Splat;
        const updateStats = () => {
            if (!splat) return;
            const state = splat.splatData.getProp('state') as Uint8Array;
            if (state) {
                splatsValue.textContent = formatInteger(state.length - splat.numDeleted);
                selectedValue.textContent = formatInteger(splat.numSelected);
                lockedValue.textContent = formatInteger(splat.numLocked);
                deletedValue.textContent = formatInteger(splat.numDeleted);
            }
        };

        events.on('splat.stateChanged', (s: Splat) => { splat = s; updateStats(); });
        events.on('selection.changed', (selection: any) => {
            if (selection instanceof Splat) { splat = selection; updateStats(); }
        });
    }

    get hidden() { return this.dom.style.display === 'none'; }
    set hidden(v: boolean) { this.dom.style.display = v ? 'none' : ''; }
}

export { NewStatusBar };
