/**
 * ViewOptionsPanel (New)
 * Pure HTML/CSS replacement for PCUI ViewPanel.
 * Shows in the right sidebar.
 */

import { Color } from 'playcanvas';

import { Events } from '../events';
import { ShortcutManager } from '../shortcut-manager';
import { localize } from '../ui/localization';
import { createContainer, createPanel, createFormRow, blockPointerEvents } from './dom-helpers';
import { SliderInput, BooleanInput, SelectInput } from './input-components';
import { TooltipSystem } from './tooltip-system';

class ViewOptionsPanel {
    dom: HTMLDivElement;
    private _hidden = true;

    constructor(events: Events, tooltips: TooltipSystem, parent: HTMLElement) {
        const { panel, body } = createPanel({
            title: localize('panel.view-options'),
            collapsible: false,
            parent
        });

        this.dom = panel;
        this.dom.id = 'view-options-panel';
        blockPointerEvents(this.dom);

        // === Colors ===
        const createColorRow = (label: string, initialColor: string): HTMLInputElement => {
            const { value } = createFormRow({ label, parent: body });
            const input = document.createElement('input');
            input.type = 'color';
            input.value = initialColor;
            input.className = 'ax-color-swatch';
            input.style.cursor = 'pointer';
            input.style.border = 'none';
            input.style.padding = '0';
            input.style.width = '32px';
            input.style.height = '24px';
            value.appendChild(input);
            return input;
        };

        const bgClrPicker = createColorRow(localize('panel.view-options.background-color'), '#000000');
        const selectedClrPicker = createColorRow(localize('panel.view-options.selected-color'), '#000000');
        const unselectedClrPicker = createColorRow(localize('panel.view-options.unselected-color'), '#000000');
        const lockedClrPicker = createColorRow(localize('panel.view-options.locked-color'), '#000000');

        const colorToHex = (clr: Color): string => {
            const r = Math.round(clr.r * 255).toString(16).padStart(2, '0');
            const g = Math.round(clr.g * 255).toString(16).padStart(2, '0');
            const b = Math.round(clr.b * 255).toString(16).padStart(2, '0');
            return `#${r}${g}${b}`;
        };

        // Store current alpha values (input type=color doesn't support alpha)
        const alphas = { bg: 1, selected: 1, unselected: 1, locked: 1 };

        const hexToColor = (hex: string, alpha: number): Color => {
            const r = parseInt(hex.slice(1, 3), 16) / 255;
            const g = parseInt(hex.slice(3, 5), 16) / 255;
            const b = parseInt(hex.slice(5, 7), 16) / 255;
            return new Color(r, g, b, alpha);
        };

        events.on('bgClr', (clr: Color) => { bgClrPicker.value = colorToHex(clr); alphas.bg = clr.a; });
        events.on('selectedClr', (clr: Color) => { selectedClrPicker.value = colorToHex(clr); alphas.selected = clr.a; });
        events.on('unselectedClr', (clr: Color) => { unselectedClrPicker.value = colorToHex(clr); alphas.unselected = clr.a; });
        events.on('lockedClr', (clr: Color) => { lockedClrPicker.value = colorToHex(clr); alphas.locked = clr.a; });

        const fireClr = (picker: HTMLInputElement, eventName: string, alpha: () => number) => {
            const handler = () => {
                events.fire(eventName, hexToColor(picker.value, alpha()));
            };
            picker.addEventListener('input', handler);
            picker.addEventListener('change', handler);
        };

        fireClr(bgClrPicker, 'setBgClr', () => alphas.bg);
        fireClr(selectedClrPicker, 'setSelectedClr', () => alphas.selected);
        fireClr(unselectedClrPicker, 'setUnselectedClr', () => alphas.unselected);
        fireClr(lockedClrPicker, 'setLockedClr', () => alphas.locked);

        // === Tonemapping ===
        const { value: tmValue } = createFormRow({ label: localize('panel.view-options.tonemapping'), parent: body });
        const tonemappingSelect = new SelectInput({
            value: 'linear',
            options: [
                { value: 'linear', label: localize('panel.view-options.tonemapping.linear') },
                { value: 'neutral', label: localize('panel.view-options.tonemapping.neutral') },
                { value: 'aces', label: localize('panel.view-options.tonemapping.aces') },
                { value: 'aces2', label: localize('panel.view-options.tonemapping.aces2') },
                { value: 'filmic', label: localize('panel.view-options.tonemapping.filmic') },
                { value: 'hejl', label: localize('panel.view-options.tonemapping.hejl') }
            ],
            parent: tmValue,
            onChange: (v) => events.fire('camera.setTonemapping', v)
        });
        events.on('camera.tonemapping', (v: string) => { tonemappingSelect.value = v; });

        // === FOV ===
        const { value: fovValue } = createFormRow({ label: localize('panel.view-options.fov'), parent: body });
        const fovSlider = new SliderInput({ min: 10, max: 120, step: 1, value: 60, precision: 1, parent: fovValue, onChange: (v) => events.fire('camera.setFov', v) });
        events.on('camera.fov', (v: number) => { fovSlider.value = v; });

        // === SH Bands ===
        const { value: shValue } = createFormRow({ label: localize('panel.view-options.sh-bands'), parent: body });
        const shBandsSlider = new SliderInput({ min: 0, max: 3, step: 1, value: 3, precision: 0, parent: shValue, onChange: (v) => events.fire('view.setBands', v) });
        events.on('view.bands', (v: number) => { shBandsSlider.value = v; });

        // === Fly Speed ===
        const { value: flyValue } = createFormRow({ label: localize('panel.view-options.fly-speed'), parent: body });
        const flySpeedSlider = new SliderInput({ min: 0.1, max: 30, step: 0.1, value: 1, precision: 1, parent: flyValue, onChange: (v) => events.fire('camera.setFlySpeed', v) });
        events.on('camera.flySpeed', (v: number) => { flySpeedSlider.value = v; });

        // === Centers Size ===
        const { value: csValue } = createFormRow({ label: localize('panel.view-options.centers-size'), parent: body });
        const centersSizeSlider = new SliderInput({
            min: 0, max: 10, step: 0.1, value: 2, precision: 1, parent: csValue,
            onChange: (v) => {
                events.fire('camera.setSplatSize', v);
                events.fire('camera.setOverlay', true);
                events.fire('camera.setMode', 'centers');
            }
        });
        events.on('camera.splatSize', (v: number) => { centersSizeSlider.value = v; });

        // === Toggle options ===
        const createToggleRow = (label: string, initial: boolean, onEvent: string, fireEvent: string): BooleanInput => {
            const { value } = createFormRow({ label, parent: body });
            const toggle = new BooleanInput({ type: 'toggle', value: initial, parent: value, onChange: (v) => events.fire(fireEvent, v) });
            events.on(onEvent, (v: boolean) => { toggle.value = v; });
            return toggle;
        };

        createToggleRow(localize('panel.view-options.centers-gaussian-color'), false, 'view.centersUseGaussianColor', 'view.setCentersUseGaussianColor');
        createToggleRow(localize('panel.view-options.outline-selection'), false, 'view.outlineSelection', 'view.setOutlineSelection');

        const shortcutManager: ShortcutManager = events.invoke('shortcutManager');
        const gridToggle = createToggleRow(localize('panel.view-options.show-grid'), true, 'grid.visible', 'grid.setVisible');
        createToggleRow(localize('panel.view-options.show-bound'), true, 'camera.bound', 'camera.setBound');
        if (!window.isFlutterApp) {
            createToggleRow(localize('panel.view-options.show-camera-poses'), false, 'camera.showPoses', 'camera.setShowPoses');
        }

        // === Visibility management ===
        this.hidden = true;

        events.function('viewPanel.visible', () => !this._hidden);

        events.on('viewPanel.setVisible', (visible: boolean) => this._setVisible(visible, events));
        events.on('viewPanel.toggleVisible', () => this._setVisible(this._hidden, events));
        events.on('colorPanel.visible', (visible: boolean) => {
            if (visible) this._setVisible(false, events);
        });
    }

    private _setVisible(visible: boolean, events: Events) {
        if (visible !== !this._hidden) {
            this._hidden = !visible;
            this.dom.style.display = this._hidden ? 'none' : '';
            events.fire('viewPanel.visible', visible);
        }
    }

    get hidden() { return this._hidden; }
    set hidden(v: boolean) {
        this._hidden = v;
        this.dom.style.display = v ? 'none' : '';
    }
}

export { ViewOptionsPanel };
