/**
 * VideoSettingsDialog (New)
 * Pure HTML/CSS replacement for PCUI VideoSettingsDialog.
 */

import { Events } from '../events';
import { VideoSettings } from '../render';
import { localize } from '../ui/localization';
import { createContainer, createLabel, createButton, createFormRow } from './dom-helpers';
import { BooleanInput, SelectInput, NumericInput } from './input-components';

class NewVideoSettingsDialog {
    dom: HTMLDivElement;
    show: () => Promise<VideoSettings | null>;
    hide: () => void;
    private _hidden = true;

    constructor(events: Events) {
        this.dom = createContainer({ id: 'video-settings-dialog', class: 'ax-modal-overlay', style: { display: 'none' } });
        this.dom.tabIndex = -1;

        const dialog = createContainer({ class: 'ax-modal', parent: this.dom });
        dialog.style.minWidth = '420px';
        dialog.addEventListener('click', e => e.stopPropagation());

        // Header
        const headerEl = createContainer({ class: 'ax-modal__header', parent: dialog });
        createLabel({ text: localize('popup.render-video.header').toUpperCase(), parent: headerEl });

        // Body
        const body = createContainer({ class: 'ax-modal__body', parent: dialog });
        body.style.display = 'flex';
        body.style.flexDirection = 'column';
        body.style.gap = '8px';

        const makeRow = (label: string) => createFormRow({ label, parent: body });

        // Resolution
        const { value: resVal } = makeRow(localize('popup.render-video.resolution'));
        const resolutionSelect = new SelectInput({
            value: '1080',
            options: [
                { value: '540', label: '960x540' },
                { value: '720', label: '1280x720' },
                { value: '1080', label: '1920x1080' },
                { value: '1440', label: '2560x1440' },
                { value: '4k', label: '3840x2160' }
            ],
            parent: resVal
        });

        // Format
        const { value: fmtVal } = makeRow(localize('popup.render-video.format'));
        const formatSelect = new SelectInput({
            value: 'mp4',
            options: [
                { value: 'mp4', label: 'MP4' },
                { value: 'webm', label: 'WebM' },
                { value: 'mov', label: 'MOV' },
                { value: 'mkv', label: 'MKV' }
            ],
            parent: fmtVal
        });

        // Codec
        const { value: codecVal } = makeRow(localize('popup.render-video.codec'));
        const codecSelect = new SelectInput({
            value: 'h264',
            options: [
                { value: 'h264', label: 'H.264' },
                { value: 'h265', label: 'H.265/HEVC' }
            ],
            parent: codecVal
        });

        const codecOptions: Record<string, Array<{ value: string; label: string }>> = {
            mp4: [{ value: 'h264', label: 'H.264' }, { value: 'h265', label: 'H.265/HEVC' }],
            webm: [{ value: 'vp9', label: 'VP9' }, { value: 'av1', label: 'AV1' }],
            mov: [{ value: 'h264', label: 'H.264' }, { value: 'h265', label: 'H.265/HEVC' }],
            mkv: [{ value: 'h264', label: 'H.264' }, { value: 'h265', label: 'H.265/HEVC' }, { value: 'vp9', label: 'VP9' }, { value: 'av1', label: 'AV1' }]
        };

        formatSelect.dom.addEventListener('change', () => {
            const fmt = formatSelect.value;
            codecSelect.setOptions(codecOptions[fmt] || codecOptions.mp4);
            codecSelect.value = fmt === 'webm' ? 'vp9' : 'h264';
        });

        // Frame Rate
        const { value: frVal } = makeRow(localize('popup.render-video.frame-rate'));
        const frameRateSelect = new SelectInput({
            value: '30',
            options: [
                { value: '12', label: '12 fps' }, { value: '15', label: '15 fps' },
                { value: '24', label: '24 fps' }, { value: '25', label: '25 fps' },
                { value: '30', label: '30 fps' }, { value: '48', label: '48 fps' },
                { value: '60', label: '60 fps' }, { value: '120', label: '120 fps' }
            ],
            parent: frVal
        });

        // Bitrate
        const { value: brVal } = makeRow(localize('popup.render-video.bitrate'));
        const bitrateSelect = new SelectInput({
            value: 'high',
            options: [
                { value: 'low', label: 'Low' }, { value: 'medium', label: 'Medium' },
                { value: 'high', label: 'High' }, { value: 'ultra', label: 'Ultra' }
            ],
            parent: brVal
        });

        // Frame Range
        const { value: rangeVal } = makeRow(localize('popup.render-video.frame-range'));
        const frameStart = new NumericInput({ value: 0, min: 0, precision: 0, parent: rangeVal });
        frameStart.dom.style.width = '70px';
        createLabel({ text: '~', parent: rangeVal, style: { padding: '0 4px' } });
        const frameEnd = new NumericInput({ value: 179, min: 0, precision: 0, parent: rangeVal });
        frameEnd.dom.style.width = '70px';

        // Portrait
        const { value: portVal } = makeRow(localize('popup.render-video.portrait'));
        const portraitBoolean = new BooleanInput({ type: 'toggle', value: false, parent: portVal });

        // Transparent BG (hidden)
        const { row: tbRow, value: tbVal } = makeRow(localize('popup.render-video.transparent-bg'));
        const transparentBg = new BooleanInput({ type: 'toggle', value: false, parent: tbVal });
        tbRow.style.display = 'none';

        // Show Debug
        const { value: dbVal } = makeRow(localize('popup.render-video.show-debug'));
        const showDebug = new BooleanInput({ type: 'toggle', value: false, parent: dbVal });

        // Footer
        const footer = createContainer({ class: 'ax-modal__footer', parent: dialog });
        const cancelBtn = createButton({ text: localize('panel.render.cancel'), parent: footer });
        const okBtn = createButton({ text: localize('panel.render.ok'), variant: 'primary', parent: footer });

        // Logic
        let onCancel: () => void;
        let onOK: () => void;

        cancelBtn.addEventListener('click', () => onCancel());
        okBtn.addEventListener('click', () => onOK());

        const keydown = (e: KeyboardEvent) => {
            if (e.key === 'Escape') { e.preventDefault(); e.stopPropagation(); onCancel(); }
        };

        const reset = () => {
            const totalFrames = events.invoke('timeline.frames');
            frameEnd.value = totalFrames - 1;
            frameStart.value = 0;
        };

        this.show = () => {
            reset();
            this.dom.style.display = '';
            this._hidden = false;
            document.addEventListener('keydown', keydown);
            this.dom.focus();

            return new Promise<VideoSettings | null>((resolve) => {
                onCancel = () => resolve(null);
                onOK = () => {
                    const widths: Record<string, number> = { '540': 960, '720': 1280, '1080': 1920, '1440': 2560, '4k': 3840 };
                    const heights: Record<string, number> = { '540': 540, '720': 720, '1080': 1080, '1440': 1440, '4k': 2160 };
                    const bppfs: Record<string, number> = { low: 0.001, medium: 0.01, high: 0.1, ultra: 1 };
                    const bbpfFactors: Record<string, number> = { '540': 1, '720': 1 / 2, '1080': 1 / 3, '1440': 1 / 4, '4k': 1 / 5 };

                    const portrait = portraitBoolean.value;
                    const rv = resolutionSelect.value;
                    const width = (portrait ? heights : widths)[rv];
                    const height = (portrait ? widths : heights)[rv];
                    const frameRate = parseInt(frameRateSelect.value);
                    const bppf = bppfs[bitrateSelect.value] * bbpfFactors[rv];
                    const bitrate = Math.floor(10 * width * height * frameRate * bppf);

                    resolve({
                        startFrame: frameStart.value,
                        endFrame: frameEnd.value,
                        frameRate, width, height, bitrate,
                        transparentBg: transparentBg.value,
                        showDebug: showDebug.value,
                        format: formatSelect.value as any,
                        codec: codecSelect.value as any
                    });
                };
            }).finally(() => {
                document.removeEventListener('keydown', keydown);
                this.hide();
            });
        };

        this.hide = () => { this.dom.style.display = 'none'; this._hidden = true; };
    }

    get hidden() { return this._hidden; }
    set hidden(v: boolean) { this._hidden = v; this.dom.style.display = v ? 'none' : ''; }
}

export { NewVideoSettingsDialog };
