import { Vec3 } from 'playcanvas';
import { Events } from './events';

// Interface for COLMAP camera data
interface ColmapCamera {
    id: number | string;
    model: string;
    width: number;
    height: number;
    params: number[];
    position: number[];
    rotation: number[]; // Quaternion [x, y, z, w]
    image_id?: number;
    image_name?: string;
}

interface ColmapImage {
    id: number;
    name: string;
    camera_id: number;
    position?: number[];
    rotation?: number[];
}


const loadColmapData = (events: Events): Promise<number> => {
    return new Promise((resolve, reject) => {
        try {
            const fileInput = document.createElement('input');
            fileInput.type = 'file';
            fileInput.accept = '.json';

            fileInput.onchange = async (e: Event) => {
                const file = (e.target as HTMLInputElement).files?.[0];
                if (!file) {
                    resolve(0);
                    return;
                }

                const reader = new FileReader();
                reader.onload = async (event) => {
                    try {
                        const jsonData = JSON.parse(event.target?.result as string);

                        // 기존 COLMAP 카메라 초기화
                        events.invoke('colmapCamera.clear');

                        let loadedCount = 0;
                        Object.entries(jsonData).forEach(([imageName, cameraData], index) => {
                            const { position, rotation } = cameraData as any;

                            if (!position || !rotation) {
                                console.warn(`카메라 데이터 누락: ${imageName}`);
                                return;
                            }

                            // loadCameraPoses와 동일한 좌표 변환 적용
                            // rotation matrix column 2 = look direction
                            const lookDir = new Vec3(rotation[0][2], rotation[1][2], rotation[2][2]);
                            const p = new Vec3(position[0], position[1], position[2]);
                            const target = new Vec3().copy(lookDir).add(p);

                            events.fire('colmapCamera.add', {
                                id: `camera_${index + 1}`,
                                imageId: index + 1,
                                imageName: imageName,
                                // (-x, -y, z) 좌표 변환
                                position: new Vec3(-p.x, -p.y, p.z),
                                target: new Vec3(-target.x, -target.y, target.z),
                                focalLength: 1.0
                            });

                            loadedCount++;
                        });

                        console.log(`Loaded ${loadedCount} COLMAP cameras`);
                        events.fire('showPopup', {
                            type: 'info',
                            header: 'COLMAP Data Loaded',
                            message: `Successfully loaded ${loadedCount} camera positions`
                        });

                        resolve(loadedCount);
                    } catch (error) {
                        console.error('JSON 파싱 오류:', error);
                        reject(error);
                    }
                };

                reader.onerror = (error) => {
                    reject(error);
                };

                reader.readAsText(file);
            };

            // 파일 선택 창이 취소되었을 때 처리
            const handleCancel = () => {
                resolve(0);
                window.removeEventListener('focus', handleCancel);
            };
            window.addEventListener('focus', handleCancel);

            fileInput.click();
        } catch (error) {
            console.error('COLMAP 데이터 로드 중 오류:', error);
            reject(error);
        }
    });
};

// Function to convert COLMAP camera data format to our format
const normalizeColmapData = (data: any) => {
    const result = {
        cameras: [{
            id: 1,
            model: 'PINHOLE',
            width: 1920,
            height: 1080,
            params: [1080, 1080, 960, 540]
        }],
        images: []
    };

    // 회전 행렬을 쿼터니언으로 변환하는 함수
    const rotationMatrixToQuaternion = (matrix) => {
        const trace = matrix[0][0] + matrix[1][1] + matrix[2][2];
        let qw, qx, qy, qz;

        if (trace > 0) {
            const s = 0.5 / Math.sqrt(trace + 1.0);
            qw = 0.25 / s;
            qx = (matrix[2][1] - matrix[1][2]) * s;
            qy = (matrix[0][2] - matrix[2][0]) * s;
            qz = (matrix[1][0] - matrix[0][1]) * s;
        } else if (matrix[0][0] > matrix[1][1] && matrix[0][0] > matrix[2][2]) {
            const s = 2.0 * Math.sqrt(1.0 + matrix[0][0] - matrix[1][1] - matrix[2][2]);
            qw = (matrix[2][1] - matrix[1][2]) / s;
            qx = 0.25 * s;
            qy = (matrix[0][1] + matrix[1][0]) / s;
            qz = (matrix[0][2] + matrix[2][0]) / s;
        } else if (matrix[1][1] > matrix[2][2]) {
            const s = 2.0 * Math.sqrt(1.0 + matrix[1][1] - matrix[0][0] - matrix[2][2]);
            qw = (matrix[0][2] - matrix[2][0]) / s;
            qx = (matrix[0][1] + matrix[1][0]) / s;
            qy = 0.25 * s;
            qz = (matrix[1][2] + matrix[2][1]) / s;
        } else {
            const s = 2.0 * Math.sqrt(1.0 + matrix[2][2] - matrix[0][0] - matrix[1][1]);
            qw = (matrix[1][0] - matrix[0][1]) / s;
            qx = (matrix[0][2] + matrix[2][0]) / s;
            qy = (matrix[1][2] + matrix[2][1]) / s;
            qz = 0.25 * s;
        }

        return [qx, qy, qz, qw];
    };

    for (const frameName of Object.keys(data)) {
        const frameData = data[frameName];

        result.images.push({
            id: result.images.length + 1,
            name: frameName,
            camera_id: 1,
            position: frameData.position,
            rotation: rotationMatrixToQuaternion(frameData.rotation)
        });
    }

    return result;
};

// 회전 행렬을 쿼터니언으로 변환하는 함수
function rotationMatrixToQuaternion(rotMatrix: number[][]) {
    const m = rotMatrix;
    let qw, qx, qy, qz;

    const trace = m[0][0] + m[1][1] + m[2][2];

    if (trace > 0) {
        const s = 0.5 / Math.sqrt(trace + 1.0);
        qw = 0.25 / s;
        qx = (m[2][1] - m[1][2]) * s;
        qy = (m[0][2] - m[2][0]) * s;
        qz = (m[1][0] - m[0][1]) * s;
    } else if (m[0][0] > m[1][1] && m[0][0] > m[2][2]) {
        const s = 2.0 * Math.sqrt(1.0 + m[0][0] - m[1][1] - m[2][2]);
        qw = (m[2][1] - m[1][2]) / s;
        qx = 0.25 * s;
        qy = (m[0][1] + m[1][0]) / s;
        qz = (m[0][2] + m[2][0]) / s;
    } else if (m[1][1] > m[2][2]) {
        const s = 2.0 * Math.sqrt(1.0 + m[1][1] - m[0][0] - m[2][2]);
        qw = (m[0][2] - m[2][0]) / s;
        qx = (m[0][1] + m[1][0]) / s;
        qy = 0.25 * s;
        qz = (m[1][2] + m[2][1]) / s;
    } else {
        const s = 2.0 * Math.sqrt(1.0 + m[2][2] - m[0][0] - m[1][1]);
        qw = (m[1][0] - m[0][1]) / s;
        qx = (m[0][2] + m[2][0]) / s;
        qy = (m[1][2] + m[2][1]) / s;
        qz = 0.25 * s;
    }

    return [qx, qy, qz, qw];
}

// loadFromFile 이벤트 핸들러 수정
const registerColmapLoaderEvents = (events: Events) => {
    // 파일에서 COLMAP 데이터 로드
    events.function('colmap.loadFromFile', async (file?: File) => {
        try {
            if (file) {
                // 파일이 직접 제공된 경우
                const text = await file.text();
                const data = JSON.parse(text);

                // 기존 COLMAP 카메라 초기화
                events.invoke('colmapCamera.clear');

                let loadedCount = 0;
                Object.entries(data).forEach(([imageName, cameraData], index) => {
                    const { position, rotation } = cameraData as any;

                    if (!position || !rotation) {
                        console.warn(`카메라 데이터 누락: ${imageName}`);
                        return;
                    }

                    // loadCameraPoses와 동일한 좌표 변환 적용
                    const lookDir = new Vec3(rotation[0][2], rotation[1][2], rotation[2][2]);
                    const p = new Vec3(position[0], position[1], position[2]);
                    const target = new Vec3().copy(lookDir).add(p);

                    events.fire('colmapCamera.add', {
                        id: `camera_${index + 1}`,
                        imageId: index + 1,
                        imageName: imageName,
                        position: new Vec3(-p.x, -p.y, p.z),
                        target: new Vec3(-target.x, -target.y, target.z),
                        focalLength: 1.0
                    });

                    loadedCount++;
                });

                console.log(`Loaded ${loadedCount} COLMAP cameras from provided file`);
                return loadedCount;
            } else {
                // 파일 선택 대화상자 사용
                return await loadColmapData(events);
            }
        } catch (error) {
            console.error('COLMAP 데이터 로드 중 오류:', error);
            events.fire('showPopup', {
                type: 'error',
                header: 'COLMAP 데이터 로드 오류',
                message: error.message
            });
            return 0;
        }
    });

    // Flutter에서 호출할 수 있는 전역 함수 추가
    window.colmapLoaderFromFlutter = async (file: File) => {
        try {
            console.log("Received COLMAP data from Flutter:", file.name);
            const camerasLoaded = await events.invoke('colmap.loadFromFile', file);
            console.log(`Loaded ${camerasLoaded} COLMAP cameras from Flutter`);
            return camerasLoaded;
        } catch (error) {
            console.error("Error processing COLMAP data from Flutter:", error);
            return 0;
        }
    };

};
export { registerColmapLoaderEvents, loadColmapData };