/**
 * DOM Helper Utilities
 * Lightweight replacement for PCUI Container/Button/Label pattern.
 * Each function returns a plain HTMLElement.
 */

// --- Element creation helpers ---

export interface ElementOptions {
    id?: string;
    class?: string | string[];
    parent?: HTMLElement;
    hidden?: boolean;
    enabled?: boolean;
    text?: string;
    html?: string;
    attrs?: Record<string, string>;
    style?: Partial<CSSStyleDeclaration>;
    children?: HTMLElement[];
    onClick?: (e: MouseEvent) => void;
}

/**
 * Create any HTML element with options
 */
export function createElement<K extends keyof HTMLElementTagNameMap>(
    tag: K,
    options: ElementOptions = {}
): HTMLElementTagNameMap[K] {
    const el = document.createElement(tag);

    if (options.id) el.id = options.id;

    if (options.class) {
        const classes = Array.isArray(options.class) ? options.class : options.class.split(' ');
        classes.forEach(c => {
            if (c) el.classList.add(c);
        });
    }

    if (options.hidden) el.style.display = 'none';
    if (options.enabled === false) {
        if ('disabled' in el) {
            (el as any).disabled = true;
        }
        el.classList.add('disabled');
    }

    if (options.text) el.textContent = options.text;
    if (options.html) el.innerHTML = options.html;

    if (options.attrs) {
        for (const [key, value] of Object.entries(options.attrs)) {
            el.setAttribute(key, value);
        }
    }

    if (options.style) {
        Object.assign(el.style, options.style);
    }

    if (options.children) {
        options.children.forEach(child => el.appendChild(child));
    }

    if (options.onClick) {
        el.addEventListener('click', options.onClick);
    }

    if (options.parent) {
        options.parent.appendChild(el);
    }

    return el;
}

/**
 * Create a div container
 */
export function createContainer(options: ElementOptions = {}): HTMLDivElement {
    return createElement('div', options);
}

/**
 * Create a span label
 */
export function createLabel(options: ElementOptions = {}): HTMLSpanElement {
    return createElement('span', options);
}

/**
 * Create a button
 */
export function createButton(options: ElementOptions & {
    icon?: string; // SVG string or data URI
    variant?: 'default' | 'primary' | 'ghost' | 'icon';
} = {}): HTMLButtonElement {
    const classes: string[] = ['ax-btn'];
    if (options.variant) {
        if (options.variant === 'icon') {
            classes[0] = 'ax-btn--icon';
        } else if (options.variant !== 'default') {
            classes.push(`ax-btn--${options.variant}`);
        }
    }
    if (options.class) {
        const extra = Array.isArray(options.class) ? options.class : options.class.split(' ');
        classes.push(...extra);
    }

    const btn = createElement('button', { ...options, class: classes });

    if (options.icon) {
        const iconSpan = createElement('span', { html: options.icon, class: 'ax-btn__icon' });
        btn.insertBefore(iconSpan, btn.firstChild);
    }

    return btn;
}

/**
 * Create a toolbar button (for left toolbar)
 */
export function createToolButton(options: ElementOptions & {
    icon?: string;
    active?: boolean;
    tooltip?: string;
} = {}): HTMLButtonElement {
    const classes: string[] = ['ax-tool-btn'];
    if (options.active) classes.push('active');
    if (options.class) {
        const extra = Array.isArray(options.class) ? options.class : options.class.split(' ');
        classes.push(...extra);
    }

    const btn = createElement('button', { ...options, class: classes });

    if (options.icon) {
        btn.innerHTML = options.icon;
    }

    if (options.tooltip) {
        btn.setAttribute('data-tooltip', options.tooltip);
    }

    return btn;
}

/**
 * Create a toolbar separator
 */
export function createSeparator(parent?: HTMLElement): HTMLDivElement {
    return createElement('div', { class: 'ax-toolbar-sep', parent });
}

/**
 * Create a panel with header and body
 */
export function createPanel(options: {
    id?: string;
    title: string;
    icon?: string;
    collapsed?: boolean;
    collapsible?: boolean;
    parent?: HTMLElement;
    headerExtra?: HTMLElement[];
}): { panel: HTMLDivElement; header: HTMLDivElement; body: HTMLDivElement } {
    const classes = ['ax-panel'];
    if (options.collapsed) classes.push('collapsed');

    const panel = createContainer({ id: options.id, class: classes });

    const header = createContainer({ class: 'ax-panel__header', parent: panel });
    if (options.icon) {
        createElement('span', { html: options.icon, parent: header });
    }
    createLabel({ text: options.title, parent: header });

    if (options.headerExtra) {
        const spacer = createContainer({ style: { flex: '1' }, parent: header });
        options.headerExtra.forEach(el => header.appendChild(el));
    }

    if (options.collapsible !== false) {
        header.addEventListener('click', () => {
            panel.classList.toggle('collapsed');
        });
    }

    const body = createContainer({ class: 'ax-panel__body', parent: panel });

    if (options.parent) {
        options.parent.appendChild(panel);
    }

    return { panel, header, body };
}

/**
 * Create a form row (label + value)
 */
export function createFormRow(options: {
    label: string;
    parent?: HTMLElement;
}): { row: HTMLDivElement; value: HTMLDivElement } {
    const row = createContainer({ class: 'ax-form-row' });
    createLabel({ text: options.label, class: 'ax-form-row__label', parent: row });
    const value = createContainer({ class: 'ax-form-row__value', parent: row });

    if (options.parent) {
        options.parent.appendChild(row);
    }

    return { row, value };
}

/**
 * Create a dropdown menu
 */
export function createDropdownMenu(options: {
    items: DropdownItem[];
    parent?: HTMLElement;
}): HTMLDivElement {
    const menu = createContainer({ class: 'ax-dropdown' });

    options.items.forEach(item => {
        if (item.separator) {
            createElement('div', { class: 'ax-dropdown__separator', parent: menu });
            return;
        }

        const itemEl = createContainer({
            class: item.disabled ? ['ax-dropdown__item', 'disabled'] : 'ax-dropdown__item',
            parent: menu
        });

        createLabel({ text: item.label || '', parent: itemEl });

        if (item.shortcut) {
            createLabel({ text: item.shortcut, class: 'ax-dropdown__item__shortcut', parent: itemEl });
        }

        if (item.hasSubmenu) {
            createLabel({ text: '\u25B6', class: 'ax-dropdown__item__arrow', parent: itemEl });
        }

        if (item.onClick && !item.disabled) {
            itemEl.addEventListener('click', (e) => {
                e.stopPropagation();
                item.onClick!();
            });
        }
    });

    if (options.parent) {
        options.parent.appendChild(menu);
    }

    return menu;
}

export interface DropdownItem {
    label?: string;
    shortcut?: string;
    separator?: boolean;
    disabled?: boolean;
    hasSubmenu?: boolean;
    onClick?: () => void;
    children?: DropdownItem[];
}

// --- Utility functions ---

/**
 * Show/hide an element
 */
export function setVisible(el: HTMLElement, visible: boolean) {
    el.style.display = visible ? '' : 'none';
}

/**
 * Toggle a CSS class
 */
export function toggleClass(el: HTMLElement, className: string, force?: boolean) {
    el.classList.toggle(className, force);
}

/**
 * Set element enabled/disabled
 */
export function setEnabled(el: HTMLElement, enabled: boolean) {
    if ('disabled' in el) {
        (el as any).disabled = !enabled;
    }
    el.classList.toggle('disabled', !enabled);
}

/**
 * Remove all children from an element
 */
export function clearChildren(el: HTMLElement) {
    while (el.firstChild) {
        el.removeChild(el.firstChild);
    }
}

/**
 * Prevent pointer events from bubbling (used on overlays/panels over canvas)
 */
export function blockPointerEvents(el: HTMLElement) {
    el.addEventListener('pointerdown', (e) => e.stopPropagation());
    el.addEventListener('pointermove', (e) => e.stopPropagation());
    el.addEventListener('pointerup', (e) => e.stopPropagation());
    el.addEventListener('wheel', (e) => e.stopPropagation());
    el.addEventListener('dblclick', (e) => e.stopPropagation());
    el.addEventListener('contextmenu', (e) => e.stopPropagation());
}
