/**
 * MeasurementPanel
 * Right sidebar panel for Distance Measurement tool settings.
 */

import { Events } from '../events';
import { createPanel, createFormRow, createButton, blockPointerEvents } from './dom-helpers';
import { SelectInput } from './input-components';
import { TooltipSystem } from './tooltip-system';

class MeasurementPanel {
    dom: HTMLDivElement;
    private _hidden = true;

    constructor(events: Events, tooltips: TooltipSystem, parent: HTMLElement) {
        const { panel, body } = createPanel({
            title: 'Distance Measurement',
            collapsible: false,
            parent
        });

        this.dom = panel;
        this.dom.id = 'measurement-panel';
        blockPointerEvents(this.dom);

        // === Distance display ===
        const { value: distValue } = createFormRow({ label: 'Distance', parent: body });
        const distLabel = document.createElement('span');
        distLabel.textContent = 'Select two points';
        distLabel.style.fontSize = '13px';
        distLabel.style.color = 'var(--ax-text-primary)';
        distLabel.style.fontWeight = '600';
        distValue.appendChild(distLabel);

        // === Scale ===
        const { value: scaleValue } = createFormRow({ label: 'Scale', parent: body });
        const scaleInput = document.createElement('input');
        scaleInput.type = 'number';
        scaleInput.step = '0.001';
        scaleInput.value = '1';
        scaleInput.min = '0.001';
        scaleInput.className = 'ax-input';
        scaleInput.style.width = '100%';
        scaleValue.appendChild(scaleInput);

        // === Unit ===
        const { value: unitValue } = createFormRow({ label: 'Unit', parent: body });
        const unitSelect = new SelectInput({
            options: [
                { value: 'mm', label: 'mm' },
                { value: 'cm', label: 'cm' },
                { value: 'm', label: 'm' },
                { value: 'km', label: 'km' },
                { value: 'in', label: 'in' },
                { value: 'ft', label: 'ft' }
            ],
            value: 'm',
            parent: unitValue,
            onChange: (value: string) => {
                events.fire('measurement.unitChanged', value);
            }
        });

        // === Scale info ===
        const { value: scaleInfoValue } = createFormRow({ label: 'Scale Info', parent: body });
        const scaleInfoLabel = document.createElement('span');
        scaleInfoLabel.textContent = 'Scale: 1 units/m';
        scaleInfoLabel.style.fontSize = 'var(--ax-font-size-xs)';
        scaleInfoLabel.style.color = 'var(--ax-text-secondary)';
        scaleInfoValue.appendChild(scaleInfoLabel);

        // === Buttons ===
        const btnRow = document.createElement('div');
        btnRow.style.display = 'flex';
        btnRow.style.gap = '8px';
        btnRow.style.marginTop = '8px';
        body.appendChild(btnRow);

        const setRefBtn = createButton({ text: 'Set Reference', parent: btnRow });
        const clearBtn = createButton({ text: 'Clear', parent: btnRow });

        // === Events: panel → tool ===
        scaleInput.addEventListener('change', () => {
            events.fire('measurement.scaleChanged', parseFloat(scaleInput.value));
        });

        setRefBtn.addEventListener('click', () => {
            events.fire('measurement.setReference');
        });

        clearBtn.addEventListener('click', () => {
            events.fire('measurement.clear');
        });

        // === Events: tool → panel ===
        events.on('measurement.distanceUpdated', (text: string) => {
            distLabel.textContent = text;
        });

        events.on('measurement.scaleUpdated', (data: { scale: number; unit: string; info: string }) => {
            scaleInput.value = String(data.scale);
            scaleInfoLabel.textContent = data.info;
        });

        // === Visibility ===
        this.hidden = true;

        events.on('measurePanel.setVisible', (visible: boolean) => {
            this.hidden = !visible;
            events.fire('measurePanel.visible', visible);
        });
    }

    get hidden() { return this._hidden; }
    set hidden(value: boolean) {
        this._hidden = value;
        this.dom.style.display = value ? 'none' : '';
    }
}

export { MeasurementPanel };
