// 환경 설정
import { CacheManagerUI } from './cache-manager-ui';
declare global {
    interface LaunchParams {
        readonly files: FileSystemFileHandle[];
    }

    interface Window {
        launchQueue: {
            setConsumer: (callback: (launchParams: LaunchParams) => void) => void;
        };
        scene: Scene;
        loadFileFromFlutter?: (filePath: string) => void;
        isFlutterApp?: boolean; // Flutter 환경에서 실행 중인지 여부
        isSubscribed?: boolean; // 구독 여부
        promptFileFromFlutter?: (defaultPath: string, fileType: string) => void;
        colmapLoaderFromFlutter?: (file: File) => Promise<number>;
        updateSubscriptionStatus?: (isSubscribed: boolean) => void; // 구독 상태 동적 업데이트
        flutterFileServerBaseUrl?: string; // Flutter 로컬 파일 서버 base URL
        loadColmapFromFlutter?: () => Promise<number>; // Flutter 환경에서 COLMAP 자동 로드
        flutter_inappwebview?: any; // Flutter InAppWebView bridge
    }
}

const getURLArgs = () => {
    // extract settings from command line in non-prod builds only
    const config = {};

    const apply = (key: string, value: string) => {
        let obj: any = config;
        key.split('.').forEach((k, i, a) => {
            if (i === a.length - 1) {
                obj[k] = value;
            } else {
                if (!obj.hasOwnProperty(k)) {
                    obj[k] = {};
                }
                obj = obj[k];
            }
        });
    };

    const params = new URLSearchParams(window.location.search.slice(1));
    params.forEach((value: string, key: string) => {
        apply(key, value);
    });

    // Flutter 환경 감지 (여러 방법으로 통합적으로 검사)
    if (
        params.has('flutter') ||
        navigator.userAgent.includes('Flutter') ||
        window.isFlutterApp === true ||
        document.referrer.includes('flutter_inappwebview')
    ) {
        // 이미 다른 코드에서 window.isFlutterApp을 직접 접근할 수 있도록 설정
        window.isFlutterApp = true;
        console.log("Flutter environment detected");
    }

    return config;
};


/**
 * Flutter 연동 기능 초기화
 *
 * - window.loadFileFromFlutter를 실제 파일 로드 핸들러로 교체
 * - 앱 초기화 전에 Flutter에서 호출되어 큐에 쌓인 파일이 있으면 처리
 *   (큐는 index.html의 인라인 스크립트에서 설정됨)
 * - 구독 상태 동적 업데이트 함수 등록
 */
const initFlutterIntegration = (scene: Scene, events: Events) => {
    console.log("Initializing Flutter integration...");

    const handleFlutterFile = (filePath: string) => {
        console.log("Received file path from Flutter:", filePath);

        // base URL 저장 (camera_poses.json 로드용)
        const lastSlash = filePath.lastIndexOf('/');
        if (lastSlash >= 0) {
            window.flutterFileServerBaseUrl = filePath.substring(0, lastSlash + 1);
            console.log("Flutter file server base URL:", window.flutterFileServerBaseUrl);
        }

        const filename = filePath.split('/').pop() || filePath;
        events.invoke('import', [{
            url: filePath,
            filename: filename
        }])
            .then(() => console.log("Model loaded successfully!"))
            .catch((err: Error) => console.error("Error loading model:", err));
    };

    // 실제 핸들러로 교체
    window.loadFileFromFlutter = handleFlutterFile;

    // Flutter 환경에서 COLMAP camera_poses.json 자동 로드
    window.loadColmapFromFlutter = async () => {
        const baseUrl = window.flutterFileServerBaseUrl;
        if (!baseUrl) {
            console.error("Flutter file server base URL not available");
            return 0;
        }

        try {
            const url = `${baseUrl}camera_poses.json`;
            console.log("Fetching COLMAP data from:", url);
            const response = await fetch(url);
            if (!response.ok) {
                throw new Error(`camera_poses.json not found (${response.status})`);
            }
            const text = await response.text();
            const file = new File([text], 'camera_poses.json', { type: 'application/json' });
            const count = await events.invoke('colmap.loadFromFile', file);
            console.log(`Loaded ${count} COLMAP cameras from Flutter`);
            return count;
        } catch (error) {
            console.error("Error loading COLMAP from Flutter:", error);
            events.fire('showPopup', {
                type: 'error',
                header: 'COLMAP Load Error',
                message: error.message
            });
            return 0;
        }
    };

    // COLMAP 카메라 썸네일 이미지 로드 (이벤트로 호출)
    events.function('colmapCamera.loadThumbnails', async () => {
        await loadColmapCameraImages(events);
    });
    const loadColmapCameraImages = async (events: Events) => {
        const cameras = events.invoke('colmapCamera.getAll') || [];
        const total = cameras.length;
        if (total === 0) return;

        console.log(`Preparing thumbnails for ${total} COLMAP cameras...`);
        events.fire('progressStart', 'Preparing camera thumbnails...', false);

        // 1단계: Flutter에서 썸네일 생성 (없으면 생성, 있으면 스킵)
        // Flutter가 진행률을 직접 progressUpdate 이벤트로 전달함
        try {
            console.log('Calling prepareColmapThumbnails...');
            const prepResult = await window.flutter_inappwebview.callHandler('prepareColmapThumbnails');
            console.log('prepareColmapThumbnails result:', prepResult);

            if (!prepResult) {
                events.fire('showPopup', {
                    type: 'error',
                    header: 'Thumbnail Error',
                    message: 'Failed to prepare thumbnails'
                });
                events.fire('progressEnd');
                return;
            }
        } catch (error) {
            console.error('Failed to prepare thumbnails:', error);
            events.fire('progressEnd');
            return;
        }

        // 2단계: 썸네일 이미지 로드 (progressStart로 완전 리셋)
        events.fire('progressEnd');
        await new Promise(r => requestAnimationFrame(r));
        events.fire('progressStart', 'Loading thumbnails...', false);
        events.fire('progressUpdate', { progress: 0, text: `0 / ${total}` });
        await new Promise(r => requestAnimationFrame(r));

        let loaded = 0;
        let failed = 0;

        for (const camera of cameras) {
            if (camera.imageName) {
                try {
                    // .thumbnails 폴더에서 썸네일 읽기
                    const base64Data = await window.flutter_inappwebview.callHandler(
                        'readColmapThumbnail',
                        camera.imageName
                    );
                    if (base64Data && base64Data !== 'null' && base64Data.length > 0) {
                        const imageUrl = `data:image/jpeg;base64,${base64Data}`;
                        camera.loadImage(imageUrl);
                    } else {
                        if (failed < 3) {
                            console.warn(`Thumbnail not found: "${camera.imageName}", response:`, typeof base64Data, base64Data ? base64Data.substring(0, 50) : base64Data);
                        }
                        failed++;
                    }
                } catch (error) {
                    if (failed < 3) {
                        console.warn(`Failed to load thumbnail for ${camera.imageName}:`, error);
                    }
                    failed++;
                }
            }
            loaded++;
            events.fire('progressUpdate', {
                progress: loaded / total,
                text: `${loaded} / ${total}`
            });
        }

        events.fire('progressEnd');
        console.log(`Thumbnails loaded: ${loaded - failed} success, ${failed} failed`);
    };

    // 앱 초기화 전에 큐에 쌓인 파일이 있으면 처리
    const pending: string[] = (window as any).__pendingFlutterFiles || [];
    if (pending.length > 0) {
        console.log(`Processing ${pending.length} queued Flutter file(s)`);
        pending.forEach(handleFlutterFile);
        pending.length = 0;
    }

    // 구독 상태 동적 업데이트 함수
    window.updateSubscriptionStatus = function (isSubscribed: boolean) {
        console.log("Subscription status updated to:", isSubscribed);
        window.isSubscribed = isSubscribed;
        events.fire('subscription.statusChanged', isSubscribed);
    };
};

const main = async () => {
    // root events object
    const events = new Events();

    // url
    const url = new URL(window.location.href);

    // 환경 구성 및 감지
    const urlArgs = getURLArgs();

    let isFlutterEnvironment = window.isFlutterApp || false;

    // 추가적인 Flutter 환경 파라미터 확인
    if (url.searchParams.has('flutter') || navigator.userAgent.includes('Flutter')) {
        window.isFlutterApp = true;
        isFlutterEnvironment = true;
    }

    console.log(`Running in ${isFlutterEnvironment ? 'Flutter' : 'Web'} environment`);

    // edit history
    const editHistory = new EditHistory(events);
    console.log('[init] EditHistory created');

    // 다국어 초기화
    // - 웹: HTTP backend로 번역 파일을 fetch()로 로드 (서버 필요)
    // - Flutter: 번들에 포함된 번역 데이터를 즉시 사용 (네트워크 불필요)
    if (isFlutterEnvironment) {
        await localizeInitMinimal();
    } else {
        await localizeInit();
    }
    console.log('[init] Localization initialized');

    // Configure WebP WASM for SOG format (used for both reading and writing)
    if (isFlutterEnvironment) {
        // Windows WebView2 cannot fetch() from file:// or virtual URLs.
        // Decode the build-time inlined base64 WASM and create a Blob URL.
        try {
            const binaryStr = atob(webpWasmBase64);
            const bytes = new Uint8Array(binaryStr.length);
            for (let i = 0; i < binaryStr.length; i++) {
                bytes[i] = binaryStr.charCodeAt(i);
            }
            const blob = new Blob([bytes], { type: 'application/wasm' });
            WebPCodec.wasmUrl = URL.createObjectURL(blob);
            console.log('[init] WebP WASM loaded via inlined base64 Blob URL');
        } catch (e) {
            console.warn('[init] Failed to create WASM Blob URL from base64:', e);
            WebPCodec.wasmUrl = new URL('static/lib/webp/webp.wasm', document.baseURI).toString();
        }
    } else {
        WebPCodec.wasmUrl = new URL('static/lib/webp/webp.wasm', document.baseURI).toString();
    }

    // register events that only need the events object (before UI is created)
    registerTimelineEvents(events);
    registerCameraPosesEvents(events);
    registerTrackManagerEvents(events);
    registerTransformHandlerEvents(events);
    registerPlySequenceEvents(events);
    registerPublishEvents(events);
    registerIframeApi(events);
    console.log('[init] Events registered');

    // initialize shortcuts
    const shortcutManager = new ShortcutManager(events);
    events.function('shortcutManager', () => shortcutManager);

    // editor ui
    console.log('[init] Creating EditorUI...');
    const editorUI = new EditorUI(events);
    console.log('[init] EditorUI created');

    // EnhancedSpinner 추가 (기존 Spinner와 별도로 추가)
    const enhancedSpinner = new EnhancedSpinner(events);
    editorUI.appContainer.append(enhancedSpinner);
    console.log('[init] EnhancedSpinner created');

    // create the graphics device
    console.log('[init] Creating graphics device...');
    const graphicsDevice = await createGraphicsDevice(editorUI.canvas, {
        deviceTypes: ['webgl2'],
        antialias: false,
        depth: false,
        stencil: false,
        xrCompatible: false,
        powerPreference: 'high-performance'
    });

    const overrides = [
        getURLArgs()
    ];

    // resolve scene config
    const sceneConfig = getSceneConfig(overrides);

    // construct the manager
    const scene = new Scene(
        events,
        sceneConfig,
        editorUI.canvas,
        graphicsDevice
    );

    // colors
    const bgClr = new Color();
    const selectedClr = new Color();
    const unselectedClr = new Color();
    const lockedClr = new Color();

    const setClr = (target: Color, value: Color, event: string) => {
        if (!target.equals(value)) {
            target.copy(value);
            events.fire(event, target);
        }
    };

    const setBgClr = (clr: Color) => {
        setClr(bgClr, clr, 'bgClr');
    };
    const setSelectedClr = (clr: Color) => {
        setClr(selectedClr, clr, 'selectedClr');
    };
    const setUnselectedClr = (clr: Color) => {
        setClr(unselectedClr, clr, 'unselectedClr');
    };
    const setLockedClr = (clr: Color) => {
        setClr(lockedClr, clr, 'lockedClr');
    };

    events.on('setBgClr', (clr: Color) => {
        setBgClr(clr);
    });
    events.on('setSelectedClr', (clr: Color) => {
        setSelectedClr(clr);
    });
    events.on('setUnselectedClr', (clr: Color) => {
        setUnselectedClr(clr);
    });
    events.on('setLockedClr', (clr: Color) => {
        setLockedClr(clr);
    });

    events.function('bgClr', () => {
        return bgClr;
    });
    events.function('selectedClr', () => {
        return selectedClr;
    });
    events.function('unselectedClr', () => {
        return unselectedClr;
    });
    events.function('lockedClr', () => {
        return lockedClr;
    });

    events.on('bgClr', (clr: Color) => {
        const cnv = (v: number) => `${Math.max(0, Math.min(255, (v * 255))).toFixed(0)}`;
        const cssColor = `rgba(${cnv(clr.r)},${cnv(clr.g)},${cnv(clr.b)},1)`;
        document.body.style.backgroundColor = cssColor;
        // Also set canvas container background so it's visible through the new layout
        const canvasContainer = document.getElementById('canvas-container');
        if (canvasContainer) canvasContainer.style.backgroundColor = cssColor;
        scene.forceRender = true;
    });
    events.on('selectedClr', (clr: Color) => {
        scene.forceRender = true;
    });
    events.on('unselectedClr', (clr: Color) => {
        scene.forceRender = true;
    });
    events.on('lockedClr', (clr: Color) => {
        scene.forceRender = true;
    });

    // initialize colors from application config
    const toColor = (value: { r: number, g: number, b: number, a: number }) => {
        return new Color(value.r, value.g, value.b, value.a);
    };
    setBgClr(toColor(sceneConfig.bgClr));
    setSelectedClr(toColor(sceneConfig.selectedClr));
    setUnselectedClr(toColor(sceneConfig.unselectedClr));
    setLockedClr(toColor(sceneConfig.lockedClr));

    // create the mask selection canvas
    const maskCanvas = document.createElement('canvas');
    const maskContext = maskCanvas.getContext('2d');
    maskCanvas.setAttribute('id', 'mask-canvas');
    maskContext.globalCompositeOperation = 'copy';

    const mask = {
        canvas: maskCanvas,
        context: maskContext
    };

    // tool manager
    const toolManager = new ToolManager(events);
    toolManager.register('rectSelection', new RectSelection(events, editorUI.toolsContainer.dom));
    toolManager.register('brushSelection', new BrushSelection(events, editorUI.toolsContainer.dom, mask));
    toolManager.register('floodSelection', new FloodSelection(events, editorUI.toolsContainer.dom, mask, editorUI.canvasContainer));
    toolManager.register('polygonSelection', new PolygonSelection(events, editorUI.toolsContainer.dom, mask));
    toolManager.register('lassoSelection', new LassoSelection(events, editorUI.toolsContainer.dom, mask));
    toolManager.register('sphereSelection', new SphereSelection(events, scene, editorUI.canvasContainer));
    toolManager.register('boxSelection', new BoxSelection(events, scene, editorUI.canvasContainer));
    toolManager.register('distanceMeasurement', new DistanceMeasurement(events, scene, editorUI.canvasContainer));
    toolManager.register('eyedropperSelection', new EyedropperSelection(events, editorUI.toolsContainer.dom, editorUI.canvasContainer));
    toolManager.register('move', new MoveTool(events, scene));
    toolManager.register('rotate', new RotateTool(events, scene));
    toolManager.register('scale', new ScaleTool(events, scene));
    toolManager.register('measure', new MeasureTool(events, scene, editorUI.toolsContainer.dom, editorUI.canvasContainer));

    editorUI.toolsContainer.dom.appendChild(maskCanvas);

    window.scene = scene;

    registerEditorEvents(events, editHistory, scene);
    registerSelectionEvents(events, scene);
    registerDocEvents(scene, events);
    registerRenderEvents(scene, events);
    registerColmapCameraEvents(events); // Register COLMAP camera events
    registerColmapLoaderEvents(events); // Register COLMAP loader events
    initFileHandler(scene, events, editorUI.appContainer.dom);

    // S3 로더 이벤트 등록
    // registerS3LoaderEvents(scene, events);
    registerEnhancedS3LoaderEvents(scene, events); // 새 로더 사용
    
    // 캐시 관리 UI 초기화 (웹 환경에서만)
    if (!isFlutterEnvironment) {
        // new CacheManagerUI(events, document.body);
        new CacheManagerUI(events)
    }

    // Flutter 환경에 따른 초기화 분기
    if (isFlutterEnvironment) {
        // Flutter 환경에서만 실행될 코드
        console.log("Initializing for Flutter environment");
        initFlutterIntegration(scene, events);
    }

    // 공통 코드: 씬 시작
    console.log('[init] Starting scene...');
    scene.start();
    console.log('[init] Scene started');

    // index.html의 로딩 스피너 제거 (앱 초기화 완료)
    document.getElementById('app-loading')?.remove();
    console.log('[init] App loading complete');

    // handle load params
    // S3 presigned URL 등에서 & 문자가 메인 URL 파라미터로 잘못 파싱되는 문제 처리
    // URLSearchParams는 &를 구분자로 사용하므로, 원본 쿼리 스트링에서 직접 추출
    const searchString = window.location.search;
    const loadIndex = searchString.indexOf('load=');
    
    if (loadIndex !== -1) {
        // load= 이후의 전체 문자열을 URL로 취급
        let rawUrl = searchString.substring(loadIndex + 5);
        
        console.log('[Load] 원본 파라미터:', rawUrl);
        
        // URL이 인코딩되어 있는지 확인 (http%3A 또는 https%3A로 시작하면 인코딩된 상태)
        let fullLoadUrl: string;
        if (rawUrl.startsWith('http%3A') || rawUrl.startsWith('https%3A')) {
            // 인코딩된 URL이므로 디코딩
            fullLoadUrl = decodeURIComponent(rawUrl);
            console.log('[Load] 디코딩된 URL:', fullLoadUrl);
        } else {
            // 이미 디코딩된 상태이므로 그대로 사용
            fullLoadUrl = rawUrl;
            console.log('[Load] URL (디코딩 불필요):', fullLoadUrl);
        }
        
        // 파일명 추출: URL 경로 부분에서 쿼리 스트링 제거 후 마지막 세그먼트
        let filename: string;
        try {
            // URL에서 경로 부분만 추출 (쿼리 스트링 제외)
            const urlWithoutQuery = fullLoadUrl.split('?')[0];
            filename = urlWithoutQuery.split('/').pop();
            // 파일명이 인코딩되어 있을 수 있으므로 디코딩
            filename = decodeURIComponent(filename);
        } catch {
            filename = fullLoadUrl.split('/').pop()?.split('?')[0];
        }
        
        console.log('[Load] 추출된 파일명:', filename);
        
        await events.invoke('import', [{
            filename,
            url: fullLoadUrl
        }]);
    }

    // handle OS-based file association in PWA mode
    if ('launchQueue' in window) {
        window.launchQueue.setConsumer(async (launchParams: LaunchParams) => {
            for (const file of launchParams.files) {
                await events.invoke('import', [{
                    filename: file.name,
                    contents: await file.getFile()
                }]);
            }
        });
    }
};

export { main };