/**
 * Tooltip System
 * Pure DOM replacement for PCUI-based Tooltips.
 * Compatible API: register(element, text, direction)
 */

import { createElement } from './dom-helpers';

type Direction = 'left' | 'right' | 'top' | 'bottom';

interface TooltipEntry {
    enter: () => void;
    leave: () => void;
}

export class TooltipSystem {
    dom: HTMLDivElement;
    private _text: HTMLSpanElement;
    private _targets: Map<HTMLElement, TooltipEntry> = new Map();
    private _timer: number = 0;

    constructor(parent?: HTMLElement) {
        this.dom = createElement('div', {
            class: 'ax-tooltip',
            style: { display: 'none' }
        });

        this._text = createElement('span', { parent: this.dom });

        if (parent) {
            parent.appendChild(this.dom);
        }
    }

    /**
     * Register a tooltip on a target element.
     * Works with both plain HTMLElements and PCUI-style objects with .dom property.
     */
    register(target: HTMLElement | { dom: HTMLElement }, text: string, direction: Direction = 'bottom') {
        const el = 'dom' in target ? target.dom : target;

        const activate = () => {
            const rect = el.getBoundingClientRect();
            const midx = Math.floor((rect.left + rect.right) * 0.5);
            const midy = Math.floor((rect.top + rect.bottom) * 0.5);
            const style = this.dom.style;

            switch (direction) {
                case 'left':
                    style.left = `${rect.left}px`;
                    style.top = `${midy}px`;
                    style.transform = 'translate(calc(-100% - 10px), -50%)';
                    break;
                case 'right':
                    style.left = `${rect.right}px`;
                    style.top = `${midy}px`;
                    style.transform = 'translate(10px, -50%)';
                    break;
                case 'top':
                    style.left = `${midx}px`;
                    style.top = `${rect.top}px`;
                    style.transform = 'translate(-50%, calc(-100% - 10px))';
                    break;
                case 'bottom':
                    style.left = `${midx}px`;
                    style.top = `${rect.bottom}px`;
                    style.transform = 'translate(-50%, 10px)';
                    break;
            }

            this._text.textContent = text;
            style.display = 'inline';

            // Clamp to viewport
            const tooltipRect = this.dom.getBoundingClientRect();
            if (tooltipRect.left < 0) {
                style.left = `${parseFloat(style.left) - tooltipRect.left}px`;
            } else if (tooltipRect.right > window.innerWidth) {
                style.left = `${parseFloat(style.left) - (tooltipRect.right - window.innerWidth)}px`;
            }
        };

        const startTimer = (fn: () => void) => {
            this._timer = window.setTimeout(() => {
                fn();
                this._timer = -1;
            }, 250);
        };

        const cancelTimer = () => {
            if (this._timer >= 0) {
                clearTimeout(this._timer);
                this._timer = -1;
            }
        };

        const enter = () => {
            cancelTimer();
            if (this.dom.style.display === 'inline') {
                activate();
            } else {
                startTimer(activate);
            }
        };

        const leave = () => {
            cancelTimer();
            if (this.dom.style.display === 'inline') {
                startTimer(() => {
                    this.dom.style.display = 'none';
                });
            }
        };

        el.addEventListener('pointerenter', enter);
        el.addEventListener('pointerleave', leave);

        this._targets.set(el, { enter, leave });
    }

    /**
     * Unregister a tooltip from a target element.
     */
    unregister(target: HTMLElement | { dom: HTMLElement }) {
        const el = 'dom' in target ? target.dom : target;
        const entry = this._targets.get(el);
        if (entry) {
            el.removeEventListener('pointerenter', entry.enter);
            el.removeEventListener('pointerleave', entry.leave);
            this._targets.delete(el);
        }
    }

    /**
     * Remove all tooltips and clean up.
     */
    destroy() {
        for (const el of this._targets.keys()) {
            this.unregister(el);
        }
        this._targets.clear();
    }
}
