// cache-manager-ui.ts
import { Events } from './events';

/**
 * PLY 파일 캐시 관리를 위한 UI 컴포넌트
 */
export class CacheManagerUI {
    private events: Events;
    private panelEl: HTMLDivElement;
    private fileSelect: HTMLSelectElement;
    private containerEl: HTMLDivElement;
    private cacheInfoLabel: HTMLDivElement;
    private initialized: boolean = false;

    constructor(events: Events) {
        this.events = events;
        
        // 이벤트 등록 - 메뉴에서 호출될 때만 패널 표시
        this.events.on('cacheManager.toggle', () => {
            if (!this.initialized) {
                this.initUI();
                this.addMenuStyles(); // 메뉴 스타일 개선도 함께 적용
            } else {
                // 이미 초기화된 경우 패널 표시
                this.showPanel();
            }
        });
    }
    
    /**
     * 패널 표시
     */
    private showPanel() {
        if (this.panelEl) {
            this.panelEl.style.display = '';
            this.refreshCacheList();
        }
    }

    private hidePanel() {
        if (this.panelEl) {
            this.panelEl.style.display = 'none';
        }
    }
    
    /**
     * UI 컴포넌트 초기화 (지연 초기화)
     */
    private initUI() {
        // 캐시 관리 패널 생성
        this.panelEl = document.createElement('div');
        this.panelEl.className = 'cache-manager-panel';
        Object.assign(this.panelEl.style, {
            position: 'fixed', left: '50%', top: '50%',
            transform: 'translate(-50%, -50%)', zIndex: '1000',
            width: '360px', backgroundColor: 'rgba(30, 30, 30, 0.95)',
            borderRadius: '4px', boxShadow: '0 2px 8px rgba(0, 0, 0, 0.5)',
            overflow: 'hidden'
        });

        // 헤더
        const header = document.createElement('div');
        header.className = 'cache-panel-header';
        header.textContent = 'PLY 파일 캐시 관리';
        Object.assign(header.style, {
            backgroundColor: '#1976d2', color: 'white', padding: '10px',
            fontSize: '14px', textAlign: 'center', cursor: 'move'
        });
        this.panelEl.appendChild(header);

        // 컨테이너
        this.containerEl = document.createElement('div');
        Object.assign(this.containerEl.style, {
            display: 'flex', flexDirection: 'column', padding: '15px'
        });
        this.panelEl.appendChild(this.containerEl);

        // 캐시 정보 레이블
        this.cacheInfoLabel = document.createElement('div');
        this.cacheInfoLabel.textContent = '로드 중...';
        Object.assign(this.cacheInfoLabel.style, {
            whiteSpace: 'pre-line', fontFamily: 'monospace', padding: '8px',
            backgroundColor: 'rgba(0, 0, 0, 0.2)', borderRadius: '3px',
            margin: '5px 0', minHeight: '80px', overflow: 'auto',
            color: 'var(--ax-text-primary, #e0e0e0)', fontSize: '12px'
        });
        this.containerEl.appendChild(this.cacheInfoLabel);
        
        // 네이티브 select 요소 생성 및 스타일 설정
        this.fileSelect = document.createElement('select');
        this.fileSelect.style.width = '100%';
        this.fileSelect.style.padding = '8px';
        this.fileSelect.style.backgroundColor = '#424242';
        this.fileSelect.style.color = 'white';
        this.fileSelect.style.border = '1px solid #555';
        this.fileSelect.style.borderRadius = '3px';
        this.fileSelect.style.marginBottom = '10px';
        this.fileSelect.style.marginTop = '5px';
        this.fileSelect.style.height = '36px';
        this.fileSelect.style.boxSizing = 'border-box';
        
        // 기본 옵션 추가
        const defaultOption = document.createElement('option');
        defaultOption.value = '';
        defaultOption.textContent = '파일을 선택하세요';
        this.fileSelect.appendChild(defaultOption);
        
        // 이벤트 리스너 추가
        this.fileSelect.addEventListener('change', () => {
            const selectedFile = this.fileSelect.value;
            console.log('파일 선택됨:', selectedFile);
            if (selectedFile) {
                this.showFileDetails(selectedFile);
            } else {
                this.cacheInfoLabel.textContent = '파일을 선택하세요.';
            }
        });
        
        this.containerEl.appendChild(this.fileSelect);

        // 버튼 컨테이너
        const buttonContainer = document.createElement('div');
        Object.assign(buttonContainer.style, { display: 'flex', flexDirection: 'column', marginTop: '10px' });

        const createCacheBtn = (text: string, cls?: string): HTMLButtonElement => {
            const btn = document.createElement('button');
            btn.textContent = text;
            if (cls) btn.className = cls;
            Object.assign(btn.style, {
                backgroundColor: '#424242', color: 'white', border: 'none',
                borderRadius: '3px', padding: '8px 12px', cursor: 'pointer',
                marginBottom: '8px', width: '100%', fontSize: '13px', height: '32px'
            });
            btn.addEventListener('mouseenter', () => { btn.style.backgroundColor = '#1976d2'; });
            btn.addEventListener('mouseleave', () => { btn.style.backgroundColor = cls === 'delete-all-button' ? '#d32f2f' : '#424242'; });
            buttonContainer.appendChild(btn);
            return btn;
        };

        const refreshButton = createCacheBtn('새로고침');
        const deleteSelectedButton = createCacheBtn('선택한 파일 캐시 삭제');
        const deleteAllButton = createCacheBtn('모든 캐시 삭제', 'delete-all-button');
        deleteAllButton.style.backgroundColor = '#d32f2f';
        const forceReloadButton = createCacheBtn('현재 파일 강제 리로드');
        const closeButton = createCacheBtn('닫기');
        closeButton.style.backgroundColor = '#333';
        closeButton.style.marginTop = '20px';

        refreshButton.addEventListener('click', () => this.refreshCacheList());

        deleteSelectedButton.addEventListener('click', async () => {
            const selectedFile = this.fileSelect.value;
            if (selectedFile) {
                try {
                    this.cacheInfoLabel.textContent = `'${selectedFile}' 캐시 삭제 중...`;
                    if (await this.events.invoke('s3.clearCache', selectedFile)) {
                        this.showMessage(`'${selectedFile}' 캐시가 삭제되었습니다.`);
                        this.refreshCacheList();
                    } else {
                        this.showMessage('캐시 삭제 중 오류가 발생했습니다.');
                    }
                } catch (error) {
                    console.error('캐시 삭제 중 오류:', error);
                    this.showMessage('캐시 삭제 중 오류가 발생했습니다.');
                }
            } else {
                this.showMessage('삭제할 파일을 선택하세요.');
            }
        });
        
        deleteAllButton.addEventListener('click', async () => {
            if (confirm('모든 PLY 파일 캐시를 삭제하시겠습니까?')) {
                try {
                    this.cacheInfoLabel.textContent = '모든 캐시 삭제 중...';
                    if (await this.events.invoke('s3.clearCache')) {
                        this.showMessage('모든 캐시가 삭제되었습니다.');
                        this.refreshCacheList();
                    } else {
                        this.showMessage('캐시 삭제 중 오류가 발생했습니다.');
                    }
                } catch (error) {
                    console.error('캐시 삭제 중 오류:', error);
                    this.showMessage('캐시 삭제 중 오류가 발생했습니다.');
                }
            }
        });

        forceReloadButton.addEventListener('click', () => {
            const url = new URL(window.location.href);
            const s3File = url.searchParams.get('s3File');
            
            if (s3File) {
                // 강제 리로드 파라미터를 추가하고 페이지 새로고침
                url.searchParams.set('forceReload', 'true');
                window.location.href = url.toString();
            } else {
                this.showMessage('URL에 s3File 파라미터가 없습니다.');
            }
        });

        closeButton.addEventListener('click', () => {
            this.hidePanel();
        });

        this.containerEl.appendChild(buttonContainer);
        document.body.appendChild(this.panelEl);
        
        // 드래그 기능
        this.makeDraggable(this.panelEl);
        
        // 캐시 목록 초기 로드
        setTimeout(() => {
            this.refreshCacheList();
        }, 500);

        this.initialized = true;
    }
    
    /**
     * 캐시 목록을 새로고침
     */
    async refreshCacheList() {
        try {
            this.cacheInfoLabel.textContent = '캐시 정보 로드 중...';
            
            // 캐시된 파일 목록 가져오기
            console.log('[CacheManagerUI] s3.listCachedFiles 호출');
            const cachedFiles = await this.events.invoke('s3.listCachedFiles');
            console.log('[CacheManagerUI] 캐시된 파일 목록:', cachedFiles);
            
            // 현재 선택된 값 저장
            const currentSelection = this.fileSelect.value;
            
            // 기존 옵션 모두 제거 (첫 번째 기본 옵션 제외)
            while (this.fileSelect.options.length > 1) {
                this.fileSelect.remove(1);
            }
            
            // 새 옵션 추가
            if (Array.isArray(cachedFiles) && cachedFiles.length > 0) {
                cachedFiles.forEach(file => {
                    const option = document.createElement('option');
                    option.value = file;
                    option.textContent = file;
                    this.fileSelect.appendChild(option);
                });
                
                // 캐시 정보 업데이트
                this.cacheInfoLabel.textContent = `${cachedFiles.length}개의 PLY 파일이 캐시되어 있습니다.`;
                
                // 이전 선택 항목이 존재하고 새 목록에도 있으면 다시 선택
                if (currentSelection) {
                    // 옵션 목록에서 현재 선택값이 있는지 확인
                    for (let i = 0; i < this.fileSelect.options.length; i++) {
                        if (this.fileSelect.options[i].value === currentSelection) {
                            this.fileSelect.value = currentSelection;
                            this.showFileDetails(currentSelection);
                            break;
                        }
                    }
                }
            } else {
                this.cacheInfoLabel.textContent = '캐시된 PLY 파일이 없습니다.';
            }
        } catch (error) {
            console.error('[CacheManagerUI] 캐시 목록 로드 중 오류:', error);
            this.cacheInfoLabel.textContent = '캐시 정보를 불러올 수 없습니다.';
        }
    }
    
    /**
     * 상태 메시지 표시
     */
    showMessage(message: string) {
        this.cacheInfoLabel.textContent = message;
        
        // 3초 후 캐시 정보 업데이트
        setTimeout(() => this.refreshCacheList(), 3000);
    }
    
    /**
     * 선택한 파일의 상세 정보 표시
     */
    async showFileDetails(fileName: string) {
        try {
            this.cacheInfoLabel.textContent = `${fileName} 정보 로드 중...`;
            
            // 파일 정보를 캐시 서비스에서 직접 가져오기
            console.log(`[CacheManagerUI] s3.getCachedFileInfo 호출: ${fileName}`);
            const fileInfo = await this.events.invoke('s3.getCachedFileInfo', fileName);
            console.log('[CacheManagerUI] 가져온 파일 정보:', fileInfo);
            
            if (fileInfo) {
                // 날짜 포맷팅
                const date = new Date(fileInfo.timestamp);
                const dateStr = date.toLocaleString();
                
                // 파일 크기 포맷팅
                const size = this.formatFileSize(fileInfo.size);
                
                // 추가 메타데이터 확인
                let metadataText = '';
                if (fileInfo.metadata && typeof fileInfo.metadata === 'object') {
                    const originalUrl = fileInfo.metadata.originalUrl;
                    const downloadedAt = fileInfo.metadata.downloadedAt;
                    
                    if (originalUrl) {
                        metadataText += `\n원본 URL: ${originalUrl}`;
                    }
                    
                    if (downloadedAt) {
                        metadataText += `\n다운로드 시간: ${downloadedAt}`;
                    }
                }
                
                // 정보 표시
                this.cacheInfoLabel.textContent = `파일: ${fileName}\n크기: ${size}\n캐시 날짜: ${dateStr}${metadataText}`;
            } else {
                this.cacheInfoLabel.textContent = `${fileName} 정보를 가져올 수 없습니다.`;
            }
        } catch (error) {
            console.error('[CacheManagerUI] 파일 상세 정보 로드 중 오류:', error);
            this.cacheInfoLabel.textContent = `${fileName} 정보를 가져올 수 없습니다. (오류: ${error.message || '알 수 없음'})`;
        }
    }
    
    /**
     * 파일 크기를 읽기 쉬운 형식으로 변환
     */
    formatFileSize(bytes: number): string {
        if (bytes === 0 || isNaN(bytes)) return '0 Bytes';
        
        const k = 1024;
        const sizes = ['Bytes', 'KB', 'MB', 'GB'];
        const i = Math.floor(Math.log(bytes) / Math.log(k));
        
        return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
    }
    
    // Styles are now handled by the new design system CSS
    
    /**
     * 메뉴 스타일 개선
     */
    private addMenuStyles() {
        // 이미 스타일이 있는지 확인
        if (document.getElementById('menu-enhanced-styles')) {
            return;
        }
        
        const style = document.createElement('style');
        style.id = 'menu-enhanced-styles';
        style.textContent = `
            /* 메뉴 패널 스타일 */
            .menu-panel {
                background-color: rgba(30, 30, 30, 0.95);
                border-radius: 4px;
                box-shadow: 0 2px 8px rgba(0, 0, 0, 0.5);
                padding: 5px 0;
                min-width: 200px;
                max-width: 280px;
            }
            
            /* 메뉴 항목 스타일 */
            .menu-row {
                padding: 8px 12px;
                display: flex;
                align-items: center;
                cursor: pointer;
                transition: background-color 0.2s;
                box-sizing: border-box;
                width: 100%;
            }
            
            .menu-row:hover {
                background-color: rgba(25, 118, 210, 0.2);
            }
            
            /* 메뉴 아이콘 스타일 */
            .menu-row-icon {
                flex: 0 0 24px;
                width: 24px;
                height: 24px;
                display: flex;
                align-items: center;
                justify-content: center;
                margin-right: 8px;
            }
            
            /* 메뉴 텍스트 스타일 */
            .menu-row-text {
                flex: 1;
                font-size: 14px;
                white-space: nowrap;
                overflow: hidden;
                text-overflow: ellipsis;
                line-height: 1.5;
            }
            
            /* 메뉴 포스트스크립트(단축키 등) 스타일 */
            .menu-row-postscript {
                flex: 0 0 auto;
                font-size: 12px;
                color: rgba(255, 255, 255, 0.6);
                margin-left: 8px;
            }
            
            /* 메뉴 구분선 스타일 */
            .menu-row-separator {
                height: 1px;
                background-color: rgba(255, 255, 255, 0.1);
                margin: 5px 0;
            }
        `;
        
        document.head.appendChild(style);
    }
    
    /**
     * 패널 드래그 가능하게 만들기
     */
    private makeDraggable(panel: HTMLElement) {
        const header = panel.querySelector('.cache-panel-header') as HTMLElement;
        if (!header) return;
        
        let offsetX = 0;
        let offsetY = 0;
        
        const dragMouseDown = (e: MouseEvent) => {
            e.preventDefault();
            
            // 초기 마우스 위치 기록
            offsetX = e.clientX;
            offsetY = e.clientY;
            
            // 이벤트 리스너 추가
            document.addEventListener('mousemove', elementDrag);
            document.addEventListener('mouseup', closeDragElement);
        };
        
        const elementDrag = (e: MouseEvent) => {
            e.preventDefault();
            
            // 이동 거리 계산
            const dx = e.clientX - offsetX;
            const dy = e.clientY - offsetY;
            offsetX = e.clientX;
            offsetY = e.clientY;
            
            // 요소 위치 업데이트
            const rect = panel.getBoundingClientRect();
            
            // 새 위치 계산 (중앙 기준이 아닌 절대 위치로 변경)
            const left = rect.left + dx;
            const top = rect.top + dy;
            
            // 패널이 화면 바깥으로 나가지 않도록 제한
            if (left > 0 && left + rect.width < window.innerWidth) {
                panel.style.left = left + 'px';
            }
            
            if (top > 0 && top + rect.height < window.innerHeight) {
                panel.style.top = top + 'px';
            }
            
            // transform 속성 제거하여 중앙 기준점 해제
            panel.style.transform = 'none';
        };
        
        const closeDragElement = () => {
            // 이벤트 리스너 제거
            document.removeEventListener('mousemove', elementDrag);
            document.removeEventListener('mouseup', closeDragElement);
        };
        
        // 헤더에 이벤트 리스너 추가
        header.addEventListener('mousedown', dragMouseDown);
    }
}
