/**
 * ColorAdjustmentsPanel (New)
 * Pure HTML/CSS replacement for PCUI ColorPanel.
 * Shows in the right sidebar.
 */

import { Color } from 'playcanvas';

import { Events } from '../events';
import { SetSplatColorAdjustmentOp } from '../edit-ops';
import { Splat } from '../splat';
import { localize } from '../ui/localization';
import { createContainer, createElement, createPanel, createFormRow, createButton, blockPointerEvents } from './dom-helpers';
import { iconReset } from './icons';
import { SliderInput } from './input-components';
import { TooltipSystem } from './tooltip-system';

class ColorAdjustmentsPanel {
    dom: HTMLDivElement;
    private _hidden = true;

    constructor(events: Events, tooltips: TooltipSystem, parent: HTMLElement) {
        const { panel, body } = createPanel({
            title: localize('panel.colors'),
            collapsible: false,
            parent
        });

        this.dom = panel;
        this.dom.id = 'color-adjustments-panel';
        blockPointerEvents(this.dom);

        // === Tint Color ===
        const { value: tintValue } = createFormRow({ label: localize('panel.colors.tint'), parent: body });
        const tintPicker = document.createElement('input');
        tintPicker.type = 'color';
        tintPicker.value = '#ffffff';
        tintPicker.className = 'ax-color-swatch';
        tintPicker.style.cursor = 'pointer';
        tintPicker.style.border = 'none';
        tintPicker.style.padding = '0';
        tintValue.appendChild(tintPicker);

        // === Sliders ===
        const createSliderRow = (label: string, min: number, max: number, step: number, value: number): SliderInput => {
            const { value: rowValue } = createFormRow({ label, parent: body });
            return new SliderInput({ min, max, step, value, precision: 3, parent: rowValue });
        };

        const temperatureSlider = createSliderRow(localize('panel.colors.temperature'), -0.5, 0.5, 0.005, 0);
        const saturationSlider = createSliderRow(localize('panel.colors.saturation'), 0, 2, 0.1, 1);
        const brightnessSlider = createSliderRow(localize('panel.colors.brightness'), -1, 1, 0.1, 0);
        const blackPointSlider = createSliderRow(localize('panel.colors.black-point'), 0, 1, 0.01, 0);
        const whitePointSlider = createSliderRow(localize('panel.colors.white-point'), 0, 1, 0.01, 1);
        const transparencySlider = createSliderRow(localize('panel.colors.transparency'), -6, 6, 0.01, 0);

        // === Reset Button ===
        const resetBtn = createButton({
            text: 'Reset',
            icon: iconReset,
            variant: 'ghost',
            parent: body,
            style: { alignSelf: 'center', marginTop: '4px' }
        });
        tooltips.register(resetBtn, localize('panel.colors.reset'), 'bottom');

        // === Logic ===
        let suppress = false;
        let selected: Splat | null = null;
        let op: SetSplatColorAdjustmentOp | null = null;

        const colorToHex = (clr: Color): string => {
            const r = Math.round(clr.r * 255).toString(16).padStart(2, '0');
            const g = Math.round(clr.g * 255).toString(16).padStart(2, '0');
            const b = Math.round(clr.b * 255).toString(16).padStart(2, '0');
            return `#${r}${g}${b}`;
        };

        const updateUIFromState = (splat: Splat) => {
            if (suppress) return;
            suppress = true;
            tintPicker.value = splat ? colorToHex(splat.tintClr) : '#ffffff';
            temperatureSlider.value = splat ? splat.temperature : 0;
            saturationSlider.value = splat ? splat.saturation : 1;
            brightnessSlider.value = splat ? splat.brightness : 0;
            blackPointSlider.value = splat ? splat.blackPoint : 0;
            whitePointSlider.value = splat ? splat.whitePoint : 1;
            transparencySlider.value = splat ? Math.log(splat.transparency) : 0;
            suppress = false;
        };

        const getCurrentState = (splat: Splat) => ({
            tintClr: splat.tintClr.clone(),
            temperature: splat.temperature,
            saturation: splat.saturation,
            brightness: splat.brightness,
            blackPoint: splat.blackPoint,
            whitePoint: splat.whitePoint,
            transparency: splat.transparency
        });

        const start = () => {
            if (selected) {
                op = new SetSplatColorAdjustmentOp({
                    splat: selected,
                    newState: getCurrentState(selected),
                    oldState: getCurrentState(selected)
                });
            }
        };

        const end = () => {
            if (op) {
                const hex = tintPicker.value;
                const r = parseInt(hex.slice(1, 3), 16) / 255;
                const g = parseInt(hex.slice(3, 5), 16) / 255;
                const b = parseInt(hex.slice(5, 7), 16) / 255;
                op.newState.tintClr.set(r, g, b);
                op.newState.temperature = temperatureSlider.value;
                op.newState.saturation = saturationSlider.value;
                op.newState.brightness = brightnessSlider.value;
                op.newState.blackPoint = blackPointSlider.value;
                op.newState.whitePoint = whitePointSlider.value;
                op.newState.transparency = Math.exp(transparencySlider.value);
                events.fire('edit.add', op);
                op = null;
            }
        };

        const updateOp = (setFunc: (op: SetSplatColorAdjustmentOp) => void) => {
            if (!suppress) {
                suppress = true;
                if (op) {
                    setFunc(op);
                    op.do();
                } else if (selected) {
                    start();
                    setFunc(op!);
                    op!.do();
                    end();
                }
                suppress = false;
            }
        };

        // Slider events with start/end for undo batching
        const sliders = [temperatureSlider, saturationSlider, brightnessSlider, blackPointSlider, whitePointSlider, transparencySlider];
        sliders.forEach(slider => {
            // onSlideStart/End already wired via SliderInput constructor options aren't available
            // We wire them via the underlying slider's pointerdown/up
        });

        // onChange handlers
        const wireSlider = (slider: SliderInput, field: string, transform?: (v: number) => number) => {
            // Use the SliderInput's onChange callback by overriding
            const origOnChange = (slider as any)._onChange;
            (slider as any)._onChange = (value: number) => {
                origOnChange?.(value);
                updateOp((op) => {
                    (op.newState as any)[field] = transform ? transform(value) : value;
                });
            };
            // Wire start/end for undo batching
            (slider as any)._onSlideStart = start;
            (slider as any)._onSlideEnd = end;
        };

        wireSlider(temperatureSlider, 'temperature');
        wireSlider(saturationSlider, 'saturation');
        wireSlider(brightnessSlider, 'brightness');
        wireSlider(blackPointSlider, 'blackPoint');
        wireSlider(whitePointSlider, 'whitePoint');
        wireSlider(transparencySlider, 'transparency', (v) => Math.exp(v));

        // Black/white point clamping
        blackPointSlider.dom.addEventListener('change', () => {
            if (blackPointSlider.value > whitePointSlider.value) {
                whitePointSlider.value = blackPointSlider.value;
            }
        });
        whitePointSlider.dom.addEventListener('change', () => {
            if (whitePointSlider.value < blackPointSlider.value) {
                blackPointSlider.value = whitePointSlider.value;
            }
        });

        // Tint picker
        tintPicker.addEventListener('focus', start);
        tintPicker.addEventListener('input', () => {
            const hex = tintPicker.value;
            const r = parseInt(hex.slice(1, 3), 16) / 255;
            const g = parseInt(hex.slice(3, 5), 16) / 255;
            const b = parseInt(hex.slice(5, 7), 16) / 255;
            updateOp((op) => { op.newState.tintClr.set(r, g, b); });
        });
        tintPicker.addEventListener('change', end);

        // Reset
        resetBtn.addEventListener('click', () => {
            if (selected) {
                const resetOp = new SetSplatColorAdjustmentOp({
                    splat: selected,
                    newState: {
                        tintClr: new Color(1, 1, 1),
                        temperature: 0,
                        saturation: 1,
                        brightness: 0,
                        blackPoint: 0,
                        whitePoint: 1,
                        transparency: 1
                    },
                    oldState: getCurrentState(selected)
                });
                events.fire('edit.add', resetOp);
            }
        });

        // Selection changed
        events.on('selection.changed', (splat: Splat) => {
            selected = splat;
            updateUIFromState(splat);
        });

        events.on('splat.tintClr', updateUIFromState);
        events.on('splat.temperature', updateUIFromState);
        events.on('splat.saturation', updateUIFromState);
        events.on('splat.brightness', updateUIFromState);
        events.on('splat.blackPoint', updateUIFromState);
        events.on('splat.whitePoint', updateUIFromState);
        events.on('splat.transparency', updateUIFromState);

        // === Visibility management ===
        this.hidden = true;

        events.function('colorPanel.visible', () => !this._hidden);

        events.on('colorPanel.setVisible', (visible: boolean) => this._setVisible(visible, events));
        events.on('colorPanel.toggleVisible', () => this._setVisible(this._hidden, events));
        events.on('viewPanel.visible', (visible: boolean) => {
            if (visible) this._setVisible(false, events);
        });
    }

    private _setVisible(visible: boolean, events: Events) {
        if (visible !== !this._hidden) {
            this._hidden = !visible;
            this.dom.style.display = this._hidden ? 'none' : '';
            events.fire('colorPanel.visible', visible);
        }
    }

    get hidden() { return this._hidden; }
    set hidden(v: boolean) {
        this._hidden = v;
        this.dom.style.display = v ? 'none' : '';
    }
}

export { ColorAdjustmentsPanel };
