/**
 * ExportPopup (New)
 * Pure HTML/CSS replacement for PCUI ExportPopup.
 */

import { localize } from '../ui/localization';
import { Events } from '../events';
import { ExportType, SceneExportOptions } from '../file-handler';
import { AnimTrack, ExperienceSettings, defaultPostEffectSettings } from '../splat-serialize';
import { Pose } from '../camera-poses';
import { createContainer, createLabel, createButton, createFormRow } from './dom-helpers';
import { BooleanInput, SelectInput, SliderInput, TextInput } from './input-components';

const removeKnownExtension = (filename: string) => {
    const exts = ['.compressed.ply', '.ksplat', '.splat', '.html', '.ply', '.sog', '.spz', '.lcc', '.zip'];
    for (const ext of exts) {
        if (filename.endsWith(ext)) return filename.slice(0, -ext.length);
    }
    return filename;
};

class NewExportPopup {
    dom: HTMLDivElement;
    show: (exportType: ExportType, splatNames: string[], showFilenameEdit: boolean) => Promise<null | SceneExportOptions>;
    hide: () => void;
    private _hidden = true;

    constructor(events: Events) {
        // Overlay
        this.dom = createContainer({ id: 'export-popup', class: 'ax-modal-overlay', style: { display: 'none' } });
        this.dom.tabIndex = -1;

        // Dialog
        const dialog = createContainer({ class: 'ax-modal', parent: this.dom });
        dialog.style.minWidth = '400px';
        dialog.style.maxWidth = '520px';
        dialog.addEventListener('click', e => e.stopPropagation());

        // Header
        const headerEl = createContainer({ class: 'ax-modal__header', parent: dialog });
        createLabel({ text: localize('popup.export.header'), parent: headerEl });

        // Body
        const body = createContainer({ class: 'ax-modal__body', parent: dialog });
        body.style.display = 'flex';
        body.style.flexDirection = 'column';
        body.style.gap = '8px';

        // --- Rows ---
        const makeRow = (label: string) => {
            const { row, value } = createFormRow({ label, parent: body });
            return { row, value };
        };

        // Type
        const { row: viewerTypeRow, value: vtVal } = makeRow(localize('popup.export.type'));
        const viewerTypeSelect = new SelectInput({ value: 'html', options: [{ value: 'html', label: localize('popup.export.html') }, { value: 'zip', label: localize('popup.export.package') }], parent: vtVal });

        // HTML Format
        const { row: formatRow, value: fmtVal } = makeRow(localize('popup.export.format'));
        const viewerFormatSelect = new SelectInput({
            value: 'compressedPly',
            options: [
                { value: 'ply', label: localize('popup.export.format-original-ply') },
                { value: 'compressedPly', label: localize('popup.export.format-compressed-ply') },
                { value: 'sog', label: localize('popup.export.format-sog') }
            ],
            parent: fmtVal
        });

        // Animation
        const { row: animationRow, value: animVal } = makeRow(localize('popup.export.animation'));
        const animationToggle = new BooleanInput({ type: 'toggle', value: false, parent: animVal });

        // Loop
        const { row: loopRow, value: loopVal } = makeRow(localize('popup.export.loop-mode'));
        const loopSelect = new SelectInput({ value: 'repeat', options: [{ value: 'none', label: localize('popup.export.loop-mode.none') }, { value: 'repeat', label: localize('popup.export.loop-mode.repeat') }, { value: 'pingpong', label: localize('popup.export.loop-mode.pingpong') }], parent: loopVal });

        // Color
        const { row: colorRow, value: clrVal } = makeRow(localize('popup.export.background-color'));
        const colorPicker = document.createElement('input');
        colorPicker.type = 'color';
        colorPicker.value = '#ffffff';
        colorPicker.style.width = '32px';
        colorPicker.style.height = '24px';
        colorPicker.style.border = 'none';
        colorPicker.style.cursor = 'pointer';
        clrVal.appendChild(colorPicker);

        // FOV
        const { row: fovRow, value: fovVal } = makeRow(localize('popup.export.fov'));
        const fovSlider = new SliderInput({ min: 10, max: 120, step: 1, value: 60, precision: 0, parent: fovVal });

        // Compress
        const { row: compressRow, value: compVal } = makeRow(localize('popup.export.compress-ply'));
        const compressBoolean = new BooleanInput({ type: 'toggle', value: false, parent: compVal });

        // SH Bands
        const { row: bandsRow, value: bandsVal } = makeRow(localize('popup.export.sh-bands'));
        const bandsSlider = new SliderInput({ min: 0, max: 3, step: 1, value: 3, precision: 0, parent: bandsVal });

        // Iterations
        const { row: iterationsRow, value: iterVal } = makeRow(localize('popup.export.iterations'));
        const iterationsSlider = new SliderInput({ min: 1, max: 20, step: 1, value: 10, precision: 0, parent: iterVal });

        // Filename
        const { row: filenameRow, value: fnVal } = makeRow(localize('popup.export.filename'));
        const filenameEntry = new TextInput({ parent: fnVal });
        filenameEntry.dom.style.flex = '1';

        // Footer
        const footer = createContainer({ class: 'ax-modal__footer', parent: dialog });
        const cancelButton = createButton({ text: localize('popup.cancel'), parent: footer });
        const exportButton = createButton({ text: localize('popup.export'), variant: 'primary', parent: footer });

        // --- Logic ---
        let onCancel: () => void;
        let onExport: () => void;

        cancelButton.addEventListener('click', () => onCancel());
        exportButton.addEventListener('click', () => onExport());

        const keydown = (e: KeyboardEvent) => {
            switch (e.key) {
                case 'Escape': onCancel(); break;
                case 'Enter': if (!e.shiftKey) onExport(); break;
                default: e.stopPropagation(); break;
            }
        };

        const updateExtension = (ext: string) => {
            filenameEntry.value = removeKnownExtension(filenameEntry.value) + ext;
        };

        compressBoolean.dom.addEventListener('change', () => {
            updateExtension(compressBoolean.value ? '.compressed.ply' : '.ply');
        });

        const updateViewerOptionRows = () => {
            formatRow.style.display = viewerTypeSelect.value === 'html' ? '' : 'none';
        };

        viewerTypeSelect.dom.addEventListener('change', () => {
            updateExtension(viewerTypeSelect.value === 'html' ? '.html' : '.zip');
            updateViewerOptionRows();
        });

        animationToggle.dom.addEventListener('change', () => {
            loopSelect.enabled = animationToggle.value;
        });

        const allRows = [viewerTypeRow, formatRow, animationRow, loopRow, colorRow, fovRow, compressRow, bandsRow, iterationsRow, filenameRow];

        const reset = (exportType: ExportType, splatNames: string[], hasPoses: boolean) => {
            const activeRows: Record<string, HTMLElement[]> = {
                ply: [compressRow, bandsRow, filenameRow],
                splat: [filenameRow],
                sog: [bandsRow, iterationsRow, filenameRow],
                viewer: [viewerTypeRow, formatRow, animationRow, loopRow, colorRow, fovRow, bandsRow, filenameRow]
            };

            const active = activeRows[exportType] || [];
            allRows.forEach(r => { r.style.display = active.includes(r) ? '' : 'none'; });

            bandsSlider.value = events.invoke('view.bands');
            compressBoolean.value = false;
            iterationsSlider.value = 10;

            filenameEntry.value = splatNames[0];
            switch (exportType) {
                case 'ply': updateExtension('.ply'); break;
                case 'splat': updateExtension('.splat'); break;
                case 'sog': updateExtension('.sog'); break;
                case 'viewer': updateExtension(viewerTypeSelect.value === 'html' ? '.html' : '.zip'); break;
            }
            updateViewerOptionRows();

            const bgClr = events.invoke('bgClr');
            animationToggle.value = hasPoses;
            animationToggle.dom.querySelector('input')!.disabled = !hasPoses;
            loopSelect.value = 'repeat';
            loopSelect.enabled = hasPoses;

            const toHex = (v: number) => Math.round(v * 255).toString(16).padStart(2, '0');
            colorPicker.value = `#${toHex(bgClr.r)}${toHex(bgClr.g)}${toHex(bgClr.b)}`;
            fovSlider.value = events.invoke('camera.fov');
        };

        this.show = (exportType: ExportType, splatNames: string[], showFilenameEdit: boolean) => {
            const frames = events.invoke('timeline.frames');
            const frameRate = events.invoke('timeline.frameRate');
            const smoothness = events.invoke('timeline.smoothness');
            const orderedPoses = (events.invoke('camera.poses') as Pose[])
                .slice()
                .filter(p => p.frame >= 0 && p.frame < frames)
                .sort((a, b) => a.frame - b.frame);

            reset(exportType, splatNames, orderedPoses.length > 0);
            filenameRow.style.display = showFilenameEdit ? '' : 'none';

            this.dom.style.display = '';
            this._hidden = false;
            this.dom.addEventListener('keydown', keydown);
            this.dom.focus();

            const getColorArray = (): [number, number, number] => {
                const hex = colorPicker.value;
                return [parseInt(hex.slice(1, 3), 16) / 255, parseInt(hex.slice(3, 5), 16) / 255, parseInt(hex.slice(5, 7), 16) / 255];
            };

            return new Promise<null | SceneExportOptions>((resolve) => {
                onCancel = () => resolve(null);
                onExport = () => {
                    switch (exportType) {
                        case 'ply':
                            resolve({ filename: filenameEntry.value, splatIdx: 'all', serializeSettings: { maxSHBands: bandsSlider.value }, compressedPly: compressBoolean.value });
                            break;
                        case 'splat':
                            resolve({ filename: filenameEntry.value, splatIdx: 'all', serializeSettings: {} });
                            break;
                        case 'sog':
                            resolve({ filename: filenameEntry.value, splatIdx: 'all', serializeSettings: { maxSHBands: bandsSlider.value }, sogIterations: iterationsSlider.value });
                            break;
                        case 'viewer': {
                            const fov = fovSlider.value;
                            const pose = events.invoke('camera.getPose');
                            const p = pose?.position;
                            const t = pose?.target;
                            const cameras = (p && t) ? [{ initial: { position: [p.x, p.y, p.z] as [number, number, number], target: [t.x, t.y, t.z] as [number, number, number], fov } }] : [];

                            const animTracks: AnimTrack[] = [];
                            if (animationToggle.value && orderedPoses.length > 0) {
                                const times: number[] = [], position: number[] = [], target: number[] = [], fovKeys: number[] = [];
                                for (const op of orderedPoses) {
                                    times.push(op.frame);
                                    position.push(op.position.x, op.position.y, op.position.z);
                                    target.push(op.target.x, op.target.y, op.target.z);
                                    fovKeys.push(op.fov ?? fov);
                                }
                                animTracks.push({ name: 'cameraAnim', duration: frames / frameRate, frameRate, loopMode: loopSelect.value as any, interpolation: 'spline', smoothness, keyframes: { times, values: { position, target, fov: fovKeys } } });
                            }

                            const experienceSettings: ExperienceSettings = {
                                version: 2, tonemapping: 'none', highPrecisionRendering: false,
                                background: { color: getColorArray() }, postEffectSettings: defaultPostEffectSettings,
                                animTracks, cameras, annotations: [], startMode: animationToggle.value ? 'animTrack' : 'default'
                            };

                            resolve({
                                filename: filenameEntry.value,
                                splatIdx: 'all',
                                serializeSettings: { maxSHBands: bandsSlider.value },
                                viewerExportSettings: {
                                    type: viewerTypeSelect.value as 'html' | 'zip',
                                    format: viewerFormatSelect.value as 'ply' | 'compressedPly' | 'sog',
                                    experienceSettings
                                }
                            });
                            break;
                        }
                    }
                };
            }).finally(() => {
                this.dom.removeEventListener('keydown', keydown);
                this.hide();
            });
        };

        this.hide = () => {
            this.dom.style.display = 'none';
            this._hidden = true;
        };
    }

    get hidden() { return this._hidden; }
    set hidden(v: boolean) { this._hidden = v; this.dom.style.display = v ? 'none' : ''; }
}

export { NewExportPopup };
