/**
 * SecondaryToolbar
 * Horizontal toolbar below the menu bar with:
 * Undo | Redo | Scene Manager toggle | Position XYZ | Rotation XYZ | Scale | Move | Rotate | Scale | LocalSpace | BoundCenter
 */

import { Quat, Vec3 } from 'playcanvas';

import { Events } from '../events';
import { Pivot } from '../pivot';
import { localize } from '../ui/localization';
import { createContainer, createElement, createLabel, createButton, createToolButton, createSeparator, blockPointerEvents } from './dom-helpers';
import { NumericInput } from './input-components';
import { TooltipSystem } from './tooltip-system';
import { ShortcutManager } from '../shortcut-manager';

import { iconUndo, iconRedo, iconMove, iconRotate, iconScale, iconCoordSpace, iconOrigin } from './icons';

class SecondaryToolbar {
    dom: HTMLDivElement;

    constructor(events: Events, tooltips: TooltipSystem, onToggleScenePanel: () => void) {
        this.dom = createContainer({ id: 'secondary-toolbar' });
        blockPointerEvents(this.dom);

        const shortcutManager: ShortcutManager = events.invoke('shortcutManager');
        const tip = (key: string, sid?: string) => {
            const t = localize(key);
            if (sid) { const s = shortcutManager.formatShortcut(sid); if (s) return `${t} ( ${s} )`; }
            return t;
        };

        // === Undo / Redo ===
        const undo = createToolButton({ icon: iconUndo, parent: this.dom });
        const redo = createToolButton({ icon: iconRedo, parent: this.dom });
        undo.disabled = true;
        redo.disabled = true;
        undo.addEventListener('click', () => events.fire('edit.undo'));
        redo.addEventListener('click', () => events.fire('edit.redo'));
        events.on('edit.canUndo', (v: boolean) => { undo.disabled = !v; });
        events.on('edit.canRedo', (v: boolean) => { redo.disabled = !v; });
        tooltips.register(undo, tip('tooltip.bottom-toolbar.undo', 'edit.undo'), 'bottom');
        tooltips.register(redo, tip('tooltip.bottom-toolbar.redo', 'edit.redo'), 'bottom');

        // Separator
        createSeparator(this.dom);

        // === Scene Manager Toggle ===
        const sceneToggle = createButton({
            text: localize('panel.scene-manager'),
            variant: 'ghost',
            parent: this.dom
        });
        sceneToggle.classList.add('ax-secondary-toolbar__btn');
        sceneToggle.addEventListener('click', () => {
            sceneToggle.classList.toggle('active');
            onToggleScenePanel();
        });
        tooltips.register(sceneToggle, localize('panel.scene-manager'), 'bottom');

        // Separator
        createSeparator(this.dom);

        // === Transform: Position ===
        const createAxisInput = (axis: string, color: string): { label: HTMLSpanElement; input: NumericInput } => {
            const label = createLabel({
                text: axis,
                parent: this.dom,
                style: { fontSize: '11px', fontWeight: '600', color, minWidth: '10px', textAlign: 'center' }
            });
            const input = new NumericInput({
                value: 0,
                precision: 3,
                step: 0.01,
                enabled: false,
                parent: this.dom
            });
            input.dom.style.width = '60px';
            input.dom.style.fontSize = '11px';
            return { label, input };
        };

        createLabel({ text: localize('panel.scene-manager.transform.position'), parent: this.dom, style: { fontSize: '11px', color: 'var(--ax-text-muted)', padding: '0 4px' } });
        const posX = createAxisInput('X', '#f44336');
        const posY = createAxisInput('Y', '#4caf50');
        const posZ = createAxisInput('Z', '#2196f3');

        createSeparator(this.dom);

        // === Transform: Rotation ===
        createLabel({ text: localize('panel.scene-manager.transform.rotation'), parent: this.dom, style: { fontSize: '11px', color: 'var(--ax-text-muted)', padding: '0 4px' } });
        const rotX = createAxisInput('X', '#f44336');
        const rotY = createAxisInput('Y', '#4caf50');
        const rotZ = createAxisInput('Z', '#2196f3');

        createSeparator(this.dom);

        // === Transform: Scale ===
        createLabel({ text: localize('panel.scene-manager.transform.scale'), parent: this.dom, style: { fontSize: '11px', color: 'var(--ax-text-muted)', padding: '0 4px' } });
        const scaleInput = new NumericInput({
            value: 1,
            min: 0.001,
            max: 10000,
            precision: 3,
            step: 0.01,
            enabled: false,
            parent: this.dom
        });
        scaleInput.dom.style.width = '60px';
        scaleInput.dom.style.fontSize = '11px';

        createSeparator(this.dom);

        // === Transform Tools ===
        const translate = createToolButton({ icon: iconMove, parent: this.dom });
        const rotate = createToolButton({ icon: iconRotate, parent: this.dom });
        const scale = createToolButton({ icon: iconScale, parent: this.dom });

        translate.addEventListener('click', () => events.fire('tool.move'));
        rotate.addEventListener('click', () => events.fire('tool.rotate'));
        scale.addEventListener('click', () => events.fire('tool.scale'));

        tooltips.register(translate, tip('tooltip.bottom-toolbar.translate', 'tool.move'), 'bottom');
        tooltips.register(rotate, tip('tooltip.bottom-toolbar.rotate', 'tool.rotate'), 'bottom');
        tooltips.register(scale, tip('tooltip.bottom-toolbar.scale', 'tool.scale'), 'bottom');

        createSeparator(this.dom);

        // === Coord Space & Origin ===
        const coordSpace = createToolButton({ icon: iconCoordSpace, parent: this.dom });
        const origin = createToolButton({ icon: iconOrigin, parent: this.dom });

        coordSpace.addEventListener('click', () => events.fire('tool.toggleCoordSpace'));
        origin.addEventListener('click', () => events.fire('pivot.toggleOrigin'));

        tooltips.register(coordSpace, tip('tooltip.bottom-toolbar.local-space', 'tool.toggleCoordSpace'), 'bottom');
        tooltips.register(origin, tip('tooltip.bottom-toolbar.bound-center'), 'bottom');

        // === Event Listeners ===
        events.on('tool.activated', (toolName: string) => {
            translate.classList.toggle('active', toolName === 'move');
            rotate.classList.toggle('active', toolName === 'rotate');
            scale.classList.toggle('active', toolName === 'scale');
        });

        events.on('tool.coordSpace', (space: string) => {
            coordSpace.classList.toggle('active', space === 'local');
        });

        events.on('pivot.origin', (o: string) => {
            origin.classList.toggle('active', o === 'boundCenter');
        });

        // === Transform Logic ===
        const v = new Vec3();
        let uiUpdating = false;
        let mouseUpdating = false;

        const updateUI = (pivot: Pivot) => {
            uiUpdating = true;
            const transform = pivot.transform;
            transform.rotation.getEulerAngles(v);
            posX.input.value = transform.position.x;
            posY.input.value = transform.position.y;
            posZ.input.value = transform.position.z;
            rotX.input.value = v.x;
            rotY.input.value = v.y;
            rotZ.input.value = v.z;
            scaleInput.value = transform.scale.x;
            uiUpdating = false;
        };

        const updatePivot = (pivot: Pivot) => {
            const px = posX.input.value, py = posY.input.value, pz = posZ.input.value;
            const rx = rotX.input.value, ry = rotY.input.value, rz = rotZ.input.value;
            const q = new Quat().setFromEulerAngles(rx, ry, rz);
            const s = scaleInput.value;
            if (q.w < 0) q.mulScalar(-1);
            pivot.moveTRS(new Vec3(px, py, pz), q, new Vec3(s, s, s));
        };

        const change = () => {
            if (!uiUpdating) {
                const pivot = events.invoke('pivot') as Pivot;
                if (mouseUpdating) {
                    updatePivot(pivot);
                } else {
                    pivot.start();
                    updatePivot(pivot);
                    pivot.end();
                }
            }
        };

        // Wire change events on all inputs
        [posX.input, posY.input, posZ.input, rotX.input, rotY.input, rotZ.input, scaleInput].forEach(inp => {
            inp.dom.addEventListener('change', change);
        });

        events.on('selection.changed', (selection: any) => {
            const has = !!selection;
            [posX.input, posY.input, posZ.input, rotX.input, rotY.input, rotZ.input, scaleInput].forEach(inp => {
                inp.enabled = has;
            });
        });

        events.on('pivot.placed', (pivot: Pivot) => updateUI(pivot));
        events.on('pivot.moved', (pivot: Pivot) => { if (!mouseUpdating) updateUI(pivot); });
        events.on('pivot.ended', (pivot: Pivot) => updateUI(pivot));
    }
}

export { SecondaryToolbar };
