import {
    BoundingBox,
    Color,
    Entity,
    Vec3,
    StandardMaterial,
    Texture,
    BLEND_NORMAL,
    ADDRESS_CLAMP_TO_EDGE,
    FILTER_LINEAR
} from 'playcanvas';

import { Element, ElementType } from './element';
import { Events } from './events';
import { Serializer } from './serializer';

// Define a new element type for colmap cameras
enum CustomElementType {
    colmapCamera = 'colmapCamera'
}

// Add the new element type to the ElementType enum
Object.assign(ElementType, CustomElementType);

// COLMAP 카메라 클래스 - 빨간색 반투명 Rect + 테두리
class ColmapCamera extends Element {
    entity: Entity;
    id: string;
    imageId: number;
    imageName: string;
    position: Vec3;
    target: Vec3;
    focalLength: number;
    selected: boolean = false;
    hasImage: boolean = false;
    rectMaterial: StandardMaterial;
    borderMaterial: StandardMaterial;
    rectEntity: Entity;
    borderEntities: Entity[] = [];  // image plane 테두리 (4변)
    frustumEntities: Entity[] = []; // apex→corner 선 (4개)
    containerEntity: Entity;

    constructor(
        id: string,
        imageId: number,
        imageName: string,
        position: Vec3,
        target: Vec3,
        focalLength: number = 1.0
    ) {
        super(CustomElementType.colmapCamera);

        this.id = id;
        this.imageId = imageId;
        this.imageName = imageName;
        this.position = position;
        this.target = target;
        this.focalLength = focalLength;
    }

    add() {
        if (!this.scene) {
            console.error("Cannot add ColmapCamera, scene is null");
            return;
        }

        // 메인 카메라 엔티티 생성
        this.entity = new Entity(`ColmapCamera_${this.id}`);
        // 씬의 elements 배열에 명시적으로 추가
        if (!this.scene.elements.includes(this)) {
            this.scene.elements.push(this);
        }
        this.scene.contentRoot.addChild(this.entity);

        // 위치 설정 후 target을 바라보도록 회전
        this.entity.setLocalPosition(this.position);
        this.entity.lookAt(this.target);

        // 빨간색 반투명 Rect 생성
        this.createRect();

        // 마우스 오버 시 하이라이트 효과
        this.scene.events.on('camera.frustumPicked', (details) => {
            const isMe = details.entity === this.entity ||
                details.entity === this.rectEntity ||
                details.entity === this.containerEntity ||
                this.borderEntities.some(b => b === details.entity);
            if (isMe) {
                this.highlightModel(true);
            } else if (this.selected) {
                this.highlightModel(false);
            }
        });
    }

    createRect() {
        // 컨테이너 - lookAt은 -Z 방향을 target으로 향하게 하므로
        // frustum이 target 방향을 바라보려면 180° Y 회전 필요
        this.containerEntity = new Entity('CameraContainer');
        this.entity.addChild(this.containerEntity);
        this.containerEntity.setLocalEulerAngles(0, 180, 0);

        const rectW = 0.3;   // image plane 가로
        const rectH = 0.225; // image plane 세로 (4:3 비율)
        const depth = 0.25;  // apex에서 image plane까지 거리
        const bt = 0.005;    // 선 굵기

        const halfW = rectW / 2;
        const halfH = rectH / 2;

        // image plane 코너 좌표 (Z=depth 위치)
        const corners = [
            new Vec3(-halfW,  halfH, depth),  // top-left
            new Vec3( halfW,  halfH, depth),  // top-right
            new Vec3( halfW, -halfH, depth),  // bottom-right
            new Vec3(-halfW, -halfH, depth),  // bottom-left
        ];
        const apex = new Vec3(0, 0, 0); // 카메라 위치 (원점)

        // 면 재질 - 빨간색 반투명
        this.rectMaterial = new StandardMaterial();
        this.rectMaterial.diffuse = new Color(1.0, 0.3, 0.3);
        this.rectMaterial.emissive = new Color(0.7, 0.1, 0.1);
        this.rectMaterial.emissiveIntensity = 0.7;
        this.rectMaterial.opacity = 0.4;
        this.rectMaterial.blendType = BLEND_NORMAL;
        this.rectMaterial.depthWrite = false;
        this.rectMaterial.depthTest = false;
        this.rectMaterial.cull = 0;
        this.rectMaterial.update();

        // image plane (반투명 면) - gizmoLayer에 배치하여 splat 위에 렌더링
        const gizmoLayerId = this.scene.gizmoLayer.id;

        this.rectEntity = new Entity('ImagePlane');
        this.containerEntity.addChild(this.rectEntity);
        this.rectEntity.addComponent('render', {
            type: 'plane',
            castShadows: false,
            layers: [gizmoLayerId]
        });
        this.rectEntity.setLocalScale(rectW, 1, rectH);
        this.rectEntity.setLocalPosition(0, 0, depth);
        this.rectEntity.setLocalEulerAngles(90, 0, 0);

        if (this.rectEntity.render?.meshInstances) {
            this.rectEntity.render.meshInstances[0].material = this.rectMaterial;
            this.rectEntity.render.meshInstances[0].cull = false; // frustum culling 비활성화
        }

        // 테두리 재질 - 진한 빨간색
        this.borderMaterial = new StandardMaterial();
        this.borderMaterial.diffuse = new Color(0.8, 0.05, 0.05);
        this.borderMaterial.emissive = new Color(0.9, 0.1, 0.1);
        this.borderMaterial.emissiveIntensity = 1.2;
        this.borderMaterial.opacity = 0.9;
        this.borderMaterial.blendType = BLEND_NORMAL;
        this.borderMaterial.depthWrite = false;
        this.borderMaterial.depthTest = false;
        this.borderMaterial.cull = 0;
        this.borderMaterial.update();

        this.borderEntities = [];
        this.frustumEntities = [];

        // 선분 생성 헬퍼
        const createEdge = (name: string, from: Vec3, to: Vec3): Entity => {
            const mid = new Vec3().lerp(from, to, 0.5);
            const diff = new Vec3().sub2(to, from);
            const len = diff.length();

            const edge = new Entity(`Edge_${name}`);
            this.containerEntity.addChild(edge);
            edge.addComponent('render', {
                type: 'box',
                castShadows: false,
                layers: [gizmoLayerId]
            });

            edge.setLocalPosition(mid.x, mid.y, mid.z);

            const dir = diff.clone().normalize();
            const pitch = -Math.asin(dir.y) * (180 / Math.PI);
            const yaw = Math.atan2(dir.x, dir.z) * (180 / Math.PI);
            edge.setLocalEulerAngles(pitch, yaw, 0);
            edge.setLocalScale(bt, bt, len);

            if (edge.render?.meshInstances) {
                edge.render.meshInstances[0].material = this.borderMaterial;
                edge.render.meshInstances[0].cull = false; // frustum culling 비활성화
            }

            return edge;
        };

        // image plane 테두리 4변
        this.borderEntities.push(createEdge('Top', corners[0], corners[1]));
        this.borderEntities.push(createEdge('Right', corners[1], corners[2]));
        this.borderEntities.push(createEdge('Bottom', corners[2], corners[3]));
        this.borderEntities.push(createEdge('Left', corners[3], corners[0]));

        // apex에서 각 코너로 가는 4개의 선 (frustum)
        this.frustumEntities.push(createEdge('Edge_TL', apex, corners[0]));
        this.frustumEntities.push(createEdge('Edge_TR', apex, corners[1]));
        this.frustumEntities.push(createEdge('Edge_BR', apex, corners[2]));
        this.frustumEntities.push(createEdge('Edge_BL', apex, corners[3]));
    }

    // 모델 하이라이트 효과
    highlightModel(highlight: boolean) {
        if (this.selected === highlight) {
            return;
        }

        this.selected = highlight;

        try {
            if (this.rectMaterial) {
                if (this.hasImage) {
                    // 이미지가 있을 때: 텍스처 유지, opacity만 조절
                    this.rectMaterial.opacity = highlight ? 1.0 : 0.9;
                } else {
                    // 이미지 없을 때: 색상 변경
                    if (highlight) {
                        this.rectMaterial.diffuse = new Color(1.0, 1.0, 0.3);
                        this.rectMaterial.emissive = new Color(1.0, 0.9, 0.0);
                        this.rectMaterial.emissiveIntensity = 1.2;
                        this.rectMaterial.opacity = 0.5;
                    } else {
                        this.rectMaterial.diffuse = new Color(1.0, 0.3, 0.3);
                        this.rectMaterial.emissive = new Color(0.7, 0.1, 0.1);
                        this.rectMaterial.emissiveIntensity = 0.7;
                        this.rectMaterial.opacity = 0.4;
                    }
                }
                this.rectMaterial.update();
            }

            if (this.borderMaterial) {
                if (highlight) {
                    this.borderMaterial.diffuse = new Color(1.0, 1.0, 0.0);
                    this.borderMaterial.emissive = new Color(1.0, 1.0, 0.0);
                    this.borderMaterial.emissiveIntensity = 2.0;
                } else {
                    this.borderMaterial.diffuse = new Color(0.8, 0.05, 0.05);
                    this.borderMaterial.emissive = new Color(0.9, 0.1, 0.1);
                    this.borderMaterial.emissiveIntensity = 1.2;
                }
                this.borderMaterial.update();
            }
        } catch (error) {
            console.error(`하이라이트 에러:`, error);
        }
    }

    onUpdate(deltaTime: number) {
        // reserved for future use
    }

    // 이미지 텍스처를 image plane에 표시
    loadImage(imageUrl: string) {
        if (!this.rectEntity || !this.scene) return;

        const img = new Image();
        img.crossOrigin = 'anonymous';
        img.onload = () => {
            const device = this.scene.app.graphicsDevice;

            // plane 비율 (4:3)에 맞게 이미지를 중앙 크랍하여 캔버스에 그림
            const planeAspect = 4 / 3;
            const imgAspect = img.width / img.height;

            let sx = 0, sy = 0, sw = img.width, sh = img.height;
            if (imgAspect > planeAspect) {
                // 이미지가 plane보다 넓음 → 좌우 크랍
                sw = Math.round(img.height * planeAspect);
                sx = Math.round((img.width - sw) / 2);
            } else if (imgAspect < planeAspect) {
                // 이미지가 plane보다 좁음 (세로 이미지) → 상하 크랍
                sh = Math.round(img.width / planeAspect);
                sy = Math.round((img.height - sh) / 2);
            }

            const canvas = document.createElement('canvas');
            canvas.width = sw;
            canvas.height = sh;
            const ctx = canvas.getContext('2d');
            ctx.drawImage(img, sx, sy, sw, sh, 0, 0, sw, sh);

            const croppedImg = new Image();
            croppedImg.onload = () => {
                const texture = new Texture(device, {
                    width: sw,
                    height: sh,
                    addressU: ADDRESS_CLAMP_TO_EDGE,
                    addressV: ADDRESS_CLAMP_TO_EDGE,
                    minFilter: FILTER_LINEAR,
                    magFilter: FILTER_LINEAR,
                    mipmaps: false
                });
                texture.setSource(croppedImg);

                this._applyImageTexture(texture);
            };
            croppedImg.src = canvas.toDataURL('image/jpeg', 0.9);

            // (텍스처 적용은 크랍 후 _applyImageTexture에서 처리)
        };
        img.onerror = () => {
            console.warn(`Failed to load image: ${imageUrl}`);
        };
        img.src = imageUrl;
    }

    // 저장된 텍스처 참조 (모드 전환 시 보존)
    private _savedEmissiveMap: any = null;

    // 크랍된 텍스처를 material에 적용
    private _applyImageTexture(texture: Texture) {
        this.rectMaterial.emissiveMap = texture;
        this.rectMaterial.emissive = new Color(1, 1, 1);
        this.rectMaterial.emissiveIntensity = 1.0;
        this.rectMaterial.diffuse = new Color(0, 0, 0);
        this.rectMaterial.opacity = 0.9;
        this.rectMaterial.update();
        this.hasImage = true;
        this._savedEmissiveMap = texture;
    }

    // 표시 모드: 'frustum' (사각뿔) / 'thumbnail' (썸네일+사각뿔)
    setDisplayMode(mode: 'frustum' | 'thumbnail') {

        if (mode === 'thumbnail' && this.hasImage) {
            // thumbnail 모드: 저장된 텍스처 복원
            if (this._savedEmissiveMap) {
                this.rectMaterial.emissiveMap = this._savedEmissiveMap;
            }
            this.rectMaterial.emissive = new Color(1, 1, 1);
            this.rectMaterial.emissiveIntensity = 1.0;
            this.rectMaterial.diffuse = new Color(0, 0, 0);
            this.rectMaterial.opacity = 0.9;
            this.rectMaterial.update();
        } else if (mode === 'frustum') {
            // frustum 모드: 텍스처 보존 후 빨간 반투명 면 복원
            if (this.rectMaterial.emissiveMap) {
                this._savedEmissiveMap = this.rectMaterial.emissiveMap;
                this.rectMaterial.emissiveMap = null;
            }
            this.rectMaterial.diffuse = new Color(1.0, 0.3, 0.3);
            this.rectMaterial.emissive = new Color(0.7, 0.1, 0.1);
            this.rectMaterial.emissiveIntensity = 0.7;
            this.rectMaterial.opacity = 0.4;
            this.rectMaterial.update();
        }
    }

    remove() {
        if (this.entity) {
            this.entity.destroy();
            this.entity = null;
            this.rectEntity = null;
            this.containerEntity = null;
            this.borderEntities = [];
            this.frustumEntities = [];
        }
    }

    serialize(serializer: Serializer) {
        try {
            if (!this.entity || !this.entity.getWorldTransform) {
                console.error("Entity is missing or incomplete");
                serializer.pack(this.id || "unknown", 0, "unknown", false);
                serializer.pack(0, 0, 0);
                serializer.pack(0, 0, 1);
                serializer.pack(1.0);
                return;
            }

            serializer.packa(this.entity.getWorldTransform().data);
            serializer.pack(this.id, this.imageId, this.imageName, this.selected);
            serializer.pack(this.position.x, this.position.y, this.position.z);
            serializer.pack(this.target.x, this.target.y, this.target.z);
            serializer.pack(this.focalLength);
        } catch (error) {
            console.error("ColmapCamera 직렬화 중 오류:", error);
            serializer.pack(this.id || "unknown", 0, "unknown", false);
            serializer.pack(0, 0, 0);
            serializer.pack(0, 0, 0, 1);
            serializer.pack(1.0);
        }
    }

    get worldBound() {
        const bound = new BoundingBox();
        bound.setFromTransformedAabb(
            new BoundingBox(new Vec3(-0.2, -0.15, -0.01), new Vec3(0.2, 0.15, 0.01)),
            this.entity.getWorldTransform()
        );
        return bound;
    }
}

// COLMAP 카메라 이벤트 등록
const registerColmapCameraEvents = (events: Events) => {

    const cameras: ColmapCamera[] = [];

    // 카메라 추가 이벤트
    events.on('colmapCamera.add', (cameraData: any) => {
        try {
            const {
                id,
                imageId,
                imageName,
                position,
                target,
                focalLength
            } = cameraData;

            const camera = new ColmapCamera(
                id,
                imageId || 0,
                imageName || id,
                position,
                target,
                focalLength || 1.0
            );

            cameras.push(camera);

            const scene = window.scene;
            camera.scene = scene;
            camera.add();

            events.fire('scene.addElement', camera);
        } catch (error) {
            console.error("카메라 생성 중 오류:", error);
        }
    });

    // 모든 카메라 가져오기
    events.function('colmapCamera.getAll', () => {
        return cameras;
    });

    // 모든 카메라 지우기
    events.function('colmapCamera.clear', () => {
        while (cameras.length > 0) {
            const camera = cameras.pop();
            if (camera && camera.entity) {
                camera.entity.destroy();
            }
        }
        return true;
    });

    // display mode 전환
    events.function('colmapCamera.setDisplayMode', (mode: 'frustum' | 'thumbnail') => {
        cameras.forEach(cam => cam.setDisplayMode(mode));
    });

    // 카메라 크기 조절
    events.function('colmapCamera.setScale', (scale: number) => {
        cameras.forEach(cam => {
            if (cam.entity) {
                cam.entity.setLocalScale(scale, scale, scale);
            }
        });
        const scene = window.scene;
        if (scene) scene.forceRender = true;
    });

    // 클릭 모드 관리
    let clickMode = 'move';
    events.on('colmapCamera.clickMode', (mode: string) => {
        clickMode = mode;
    });
    events.function('colmapCamera.getClickMode', () => clickMode);

    // 원본 이미지 팝업 (Flutter 핸들러 경유)
    // colmap/input 에서 먼저 찾고, 없으면 colmap/images fallback (360카메라 프로젝트)
    events.on('colmapCamera.showOriginalImage', async (imageName: string) => {
        if (!window.isFlutterApp || !window.flutter_inappwebview) return;
        try {
            let base64Data = await window.flutter_inappwebview.callHandler(
                'readColmapImage',
                imageName
            );
            if (!base64Data) {
                base64Data = await window.flutter_inappwebview.callHandler(
                    'readColmapImageFallback',
                    imageName
                );
            }
            if (base64Data) {
                events.fire('colmapCamera.showImagePopup', {
                    imageName,
                    imageUrl: `data:image/jpeg;base64,${base64Data}`
                });
            }
        } catch (error) {
            console.warn(`Failed to load original image: ${imageName}`, error);
        }
    });

    let camerasVisible = true;

    events.on('colmapCamera.toggle', () => {
        events.invoke('colmapCamera.toggleVisibility');
    });

    // 단축키 K → 카메라가 로드된 상태에서만 토글 (Flutter에서는 left-toolbar가 처리)
    if (!window.isFlutterApp) {
        events.on('colmap.toggleCameras', () => {
            if (cameras.length > 0) {
                events.invoke('colmapCamera.toggleVisibility');
            }
        });
    }

    events.function('colmapCamera.toggleVisibility', (visible?: boolean) => {
        if (visible === undefined) {
            camerasVisible = !camerasVisible;
        } else {
            camerasVisible = visible;
        }

        cameras.forEach(camera => {
            if (camera.entity) {
                camera.entity.enabled = camerasVisible;
            }
        });

        const scene = window.scene;
        if (scene) {
            scene.forceRender = true;
        }

        events.fire('colmapCamera.visibilityChanged', camerasVisible);

        return camerasVisible;
    });

    // 카메라 클릭 이벤트 처리
    events.on('camera.frustumPicked', (details) => {
        const pickedCamera = cameras.find(cam =>
            cam.entity === details.entity ||
            cam.rectEntity === details.entity ||
            cam.containerEntity === details.entity ||
            cam.borderEntities.some(b => b === details.entity)
        );

        if (pickedCamera) {
            console.log(`선택된 카메라: ${pickedCamera.imageName || pickedCamera.id}`);
        }
    });
};

export { ColmapCamera, registerColmapCameraEvents };
