import { Events } from '../events';
import { NumericInput } from '../ui-new/input-components';

type Pt = {x : number, y: number };

const RED = 0;
const GREEN = 1;
const BLUE = 2;
const ALPHA = 3;
const PIXEL = 4;

class FloodSelection {
    activate: () => void;
    deactivate: () => void;

    constructor(events: Events, parent: HTMLElement, mask: { canvas: HTMLCanvasElement, context: CanvasRenderingContext2D }, canvasContainer: { dom: HTMLElement }) {

        // create canvas
        const { canvas, context } = mask;

        let threshold = 0.2;
        let point: Pt;
        let imageData: ImageData;

        // ui
        const selectToolbar = document.createElement('div');
        selectToolbar.className = 'select-toolbar';
        selectToolbar.style.display = 'none';

        selectToolbar.addEventListener('pointerdown', (e) => {
            e.stopPropagation();
        });

        const thresholdInput = new NumericInput({ value: threshold, placeholder: 'Threshold', precision: 3, step: 0.001, min: 0.001, max: 0.999, parent: selectToolbar });
        thresholdInput.dom.style.width = '120px';

        canvasContainer.dom.appendChild(selectToolbar);

        const apply = async (op: 'set' | 'add' | 'remove') => {
            await events.invoke(
                'select.byMask',
                op,
                canvas,
                context
            );
        };

        const refreshSelection = async () => {
            if (!point) return;

            const width = parent.clientWidth;
            const height = parent.clientHeight;

            if (!imageData || canvas.width !== width || canvas.height !== height) {
                canvas.width = width;
                canvas.height = height;
                imageData = context.createImageData(width, height);
            }

            const data = await (events.invoke('render.offscreen', width, height) as Promise<Uint8Array>);
            let current: Pt = {
                ...point
            };

            const start = (current.y * width + current.x) * PIXEL;
            let idx = start;
            const pickedOpacity = data[idx + ALPHA];

            const testPixels: Pt[] = [current];
            const d = imageData.data;

            d.fill(102);

            while (testPixels.length > 0) {
                current = testPixels.pop();
                idx = (current.y * width + current.x) * PIXEL;
                if (Math.abs(data[idx + 3] - pickedOpacity) < threshold * 255) {
                    d[idx + RED] = 255;
                    d[idx + BLUE] = 0;
                    d[idx + ALPHA] = 255;

                    if (current.x > 0 && d[idx - PIXEL + ALPHA] === 102) testPixels.push({ x: current.x - 1, y: current.y });
                    if (current.x < width - 1 && d[idx + PIXEL + ALPHA] === 102) testPixels.push({ x: current.x + 1, y: current.y });
                    if (current.y > 0 && d[idx - width * PIXEL + ALPHA] === 102) testPixels.push({ x: current.x, y: current.y - 1 });
                    if (current.y < height - 1 && d[idx + width * PIXEL + ALPHA] === 102) testPixels.push({ x: current.x, y: current.y + 1 });
                } else {
                    d[idx + ALPHA] = 0;
                }
            }

            context.putImageData(imageData, 0, 0);
        };

        thresholdInput.dom.addEventListener('change', () => {
            threshold = thresholdInput.value;
        });

        // [Fix] pointerId 기반 추적 + setPointerCapture 방식으로 변경
        // 기존: clicked boolean 플래그 사용 시 pointermove가 무조건 clicked=false로 리셋하여
        // Flutter InAppWebView(WebView2) 환경에서 synthetic pointermove 발생 시 동작 불가했음
        let pointerId: number | null = null;

        const resetPointer = () => {
            if (pointerId !== null) {
                parent.releasePointerCapture(pointerId);
                pointerId = null;
            }
        };

        const pointerdown = (e: PointerEvent) => {
            if (pointerId === null && (e.pointerType === 'mouse' ? e.button === 0 : e.isPrimary)) {
                e.preventDefault();
                e.stopPropagation();
                pointerId = e.pointerId;
                parent.setPointerCapture(pointerId);
            }
        };

        const pointermove = (e: PointerEvent) => {
            if (e.pointerId === pointerId) {
                e.preventDefault();
                e.stopPropagation();
            }
        };

        const pointerup = async (e: PointerEvent) => {
            if (e.pointerId === pointerId) {
                e.preventDefault();
                e.stopPropagation();

                point = {
                    x: Math.floor(e.offsetX),
                    y: Math.floor(e.offsetY)
                };

                await refreshSelection();

                await apply(e.shiftKey ? 'add' : (e.ctrlKey ? 'remove' : 'set'));

                context.clearRect(0, 0, canvas.width, canvas.height);

                resetPointer();
            }
        };

        const pointercancel = (e: PointerEvent) => {
            if (e.pointerId === pointerId) {
                e.preventDefault();
                e.stopPropagation();
                resetPointer();
            }
        };

        // [Fix] 이벤트를 parent(toolsContainer)에 등록하고, capture 플래그를 일관되게 사용
        // 기존: canvasContainer.dom에 등록 + pointerup만 capture(true)로 등록했으나
        // removeEventListener에서 capture 플래그 누락으로 리스너가 제거되지 않는 버그 존재
        this.activate = () => {
            parent.style.display = 'block';
            selectToolbar.style.display = '';
            parent.addEventListener('pointerdown', pointerdown);
            parent.addEventListener('pointermove', pointermove);
            parent.addEventListener('pointerup', pointerup);
            parent.addEventListener('pointercancel', pointercancel);
        };

        this.deactivate = () => {
            parent.style.display = 'none';
            selectToolbar.style.display = 'none';
            resetPointer();
            parent.removeEventListener('pointerdown', pointerdown);
            parent.removeEventListener('pointermove', pointermove);
            parent.removeEventListener('pointerup', pointerup);
            parent.removeEventListener('pointercancel', pointercancel);
            point = undefined;
        };
    }
}

export { FloodSelection };
